window.__saMergeCourse({id:'bal-class9-physics', board:'balochistan', title:'Physics', urdu:'طبیعیات', class:'Class 9', icon:'⚛️', desc:'Balochistan Board Class 9 Physics — full syllabus with lessons and quizzes.', chapters:[
{id:'bal-c9-phy-ch1', title:'Introduction', urdu:'تعارف', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch1-l1', title:'What is Physics?', html:'<h3>What is Physics?</h3><p><strong>Physics</strong> is the branch of science that studies matter, energy and their mutual interaction. The word physics comes from the Greek word <em>physis</em>, meaning nature.</p><p>Physics explains how the world works — from the motion of a cricket ball to the orbit of the Moon. Every device you use, from a mobile phone to a ceiling fan, works on principles discovered by physicists.</p>'},
{id:'bal-c9-phy-ch1-l2', title:'Branches of Physics', html:'<h3>Branches of Physics</h3><ul><li><strong>Mechanics</strong> — motion of bodies and the forces that cause it.</li><li><strong>Heat (Thermodynamics)</strong> — nature of heat and its transfer.</li><li><strong>Sound (Acoustics)</strong> — production and properties of sound.</li><li><strong>Optics</strong> — behaviour of light and optical instruments.</li><li><strong>Electricity and Magnetism</strong> — charges, currents and magnetic effects.</li><li><strong>Atomic and Nuclear Physics</strong> — structure of atoms and nuclei.</li><li><strong>Plasma Physics</strong> — the ionised fourth state of matter.</li><li><strong>Geophysics</strong> — physics of the Earth.</li></ul>'},
{id:'bal-c9-phy-ch1-l3', title:'Science, Technology and the Scientific Method', html:'<h3>Science, Technology and Engineering</h3><p><strong>Science</strong> discovers how nature works; <strong>technology</strong> applies that knowledge to make tools and machines; <strong>engineering</strong> designs and builds them. A mobile phone, for example, applies physics (electromagnetism), chemistry (batteries) and engineering (design).</p><p><strong>Scientific method:</strong> observe → ask a question → form a hypothesis → test by experiment → analyse results → draw a conclusion. A good conclusion must be repeatable by others.</p>'}],
quiz:[
{q:'Physics is the study of', options:['living things only','matter, energy and their interaction','chemicals and reactions','rocks and minerals'], answer:1, explain:'Physics studies matter, energy and how they interact with each other.'},
{q:'The word “physics” comes from the Greek word physis, which means', options:['energy','nature','motion','light'], answer:1, explain:'Physis is the Greek word for nature; physics is the study of nature.'},
{q:'The branch of physics dealing with the motion of bodies and forces is', options:['optics','mechanics','acoustics','geophysics'], answer:1, explain:'Mechanics studies motion, its causes (forces) and its effects.'},
{q:'The study of light and optical instruments is called', options:['acoustics','optics','thermodynamics','plasma physics'], answer:1, explain:'Optics is the branch of physics that studies light.'},
{q:'Which branch studies the ionised fourth state of matter?', options:['Nuclear physics','Atomic physics','Plasma physics','Geophysics'], answer:2, explain:'Plasma physics studies plasma — ionised gas, the fourth state of matter.'},
{q:'Geophysics is the study of', options:['the Earth using physics','gases in the atmosphere','geometry of shapes','gems and minerals'], answer:0, explain:'Geophysics applies physics to study the structure and processes of the Earth.'},
{q:'The correct order of the scientific method is', options:['conclusion → experiment → hypothesis','observe → hypothesis → experiment → conclusion','experiment → observe → conclusion','hypothesis → conclusion → experiment'], answer:1, explain:'Observe, form a hypothesis, test it by experiment, then conclude.'},
{q:'Technology is best described as', options:['pure thinking about nature','the application of scientific knowledge to make tools','the study of ancient machines','random invention without science'], answer:1, explain:'Technology applies scientific knowledge to build useful tools and machines.'},
{q:'A hypothesis must be', options:['testable by experiment','always true','a proven law','based on opinion'], answer:0, explain:'A hypothesis is a testable proposed explanation, checked by experiment.'},
{q:'Which of these is an application of physics?', options:['a mobile phone signal','a chemical fertiliser','a new wheat variety','a grammar rule'], answer:0, explain:'Mobile phone signals use electromagnetic waves — an application of physics.'}]},
{id:'bal-c9-phy-ch2', title:'Physical Quantities', urdu:'طبعی مقداریں', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch2-l1', title:'Physical and Non-Physical Quantities', html:'<h3>Physical Quantities</h3><p>A <strong>physical quantity</strong> is anything that can be measured and expressed with a number and a unit — for example, length (5 m), mass (2 kg), time (10 s).</p><p>Quantities that cannot be measured with instruments — such as love, beauty or honesty — are <strong>non-physical quantities</strong>.</p><p>Physical quantities are of two types: <strong>base quantities</strong> (independent, e.g. length, mass, time) and <strong>derived quantities</strong> (built from base quantities, e.g. speed, force, pressure).</p>'},
{id:'bal-c9-phy-ch2-l2', title:'SI Units, Prefixes and Scientific Notation', html:'<h3>International System of Units (SI)</h3><table><tr><th>Base quantity</th><th>SI unit</th><th>Symbol</th></tr><tr><td>Length</td><td>metre</td><td>m</td></tr><tr><td>Mass</td><td>kilogram</td><td>kg</td></tr><tr><td>Time</td><td>second</td><td>s</td></tr><tr><td>Electric current</td><td>ampere</td><td>A</td></tr><tr><td>Temperature</td><td>kelvin</td><td>K</td></tr><tr><td>Amount of substance</td><td>mole</td><td>mol</td></tr><tr><td>Luminous intensity</td><td>candela</td><td>cd</td></tr></table><p><strong>Prefixes:</strong> kilo (k) = 10³, mega (M) = 10⁶, giga (G) = 10⁹, milli (m) = 10⁻³, micro (µ) = 10⁻⁶, nano (n) = 10⁻⁹.</p><p><strong>Scientific notation:</strong> a number written as a × 10ⁿ, e.g. 300000000 m/s = 3 × 10⁸ m/s.</p>'},
{id:'bal-c9-phy-ch2-l3', title:'Significant Figures, Precision and Accuracy', html:'<h3>Significant Figures</h3><ul><li>All non-zero digits are significant: 4.75 has 3.</li><li>Zeros between non-zero digits count: 2008 has 4.</li><li>Leading zeros never count: 0.0040 has 2.</li><li>A final zero after a decimal point counts: 5.00 has 3.</li></ul><p><strong>Precision</strong> means how close repeated measurements are to each other; <strong>accuracy</strong> means how close a measurement is to the true value. A faulty ruler can be precise but not accurate.</p><p><strong>Errors:</strong> systematic errors (faulty instrument) can be corrected; random errors (human reaction) are reduced by averaging repeated readings.</p>'}],
quiz:[
{q:'Which of the following is a physical quantity?', options:['honesty','length','beauty','kindness'], answer:1, explain:'Length can be measured with a number and unit; the others cannot.'},
{q:'How many base quantities are there in the SI system?', options:['3','5','7','9'], answer:2, explain:'There are seven SI base quantities: length, mass, time, current, temperature, amount of substance, luminous intensity.'},
{q:'The SI unit of electric current is', options:['volt','ampere','ohm','watt'], answer:1, explain:'Electric current is measured in amperes (A).'},
{q:'The SI unit of luminous intensity is', options:['lux','lumen','candela','mole'], answer:2, explain:'Luminous intensity is measured in candela (cd).'},
{q:'1 nanometre equals', options:['10⁻³ m','10⁻⁶ m','10⁻⁹ m','10⁻¹² m'], answer:2, explain:'Nano (n) means 10⁻⁹, so 1 nm = 10⁻⁹ m.'},
{q:'The speed of light 300000000 m/s in scientific notation is', options:['3 × 10⁷ m/s','3 × 10⁸ m/s','30 × 10⁸ m/s','0.3 × 10⁹ m/s'], answer:1, explain:'300000000 = 3 × 10⁸.'},
{q:'How many significant figures are in 0.005040?', options:['3','4','5','6'], answer:1, explain:'Leading zeros do not count; 5, 0, 4 and the final 0 are significant = 4.'},
{q:'Accuracy means', options:['readings close to each other','a reading close to the true value','a large number of readings','using a digital instrument'], answer:1, explain:'Accuracy is closeness to the true value; precision is closeness of readings to each other.'},
{q:'A systematic error is caused by', options:['human reaction time','a faulty instrument','taking one reading','rounding off'], answer:1, explain:'Systematic errors come from faulty instruments or method and repeat every time.'},
{q:'Which quantity is derived?', options:['mass','time','force','length'], answer:2, explain:'Force (F = ma) is built from mass, length and time, so it is derived.'}]},
{id:'bal-c9-phy-ch3', title:'Kinematics', urdu:'حرکیات', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch3-l1', title:'Rest, Motion and Types of Motion', html:'<h3>Rest and Motion</h3><p>A body is at <strong>rest</strong> if it does not change its position with time, and in <strong>motion</strong> if it does. Motion is always described relative to a reference point.</p><p><strong>Types of motion:</strong></p><ul><li><strong>Translatory</strong> — moves from one place to another (car on a road).</li><li><strong>Rotatory</strong> — spins about an axis (ceiling fan).</li><li><strong>Vibratory</strong> — moves to and fro about a mean position (pendulum).</li></ul>'},
{id:'bal-c9-phy-ch3-l2', title:'Distance, Displacement, Speed and Velocity', html:'<h3>Distance and Displacement</h3><p><strong>Distance</strong> is the total path length (scalar); <strong>displacement</strong> is the shortest straight-line change of position (vector). Walking 3 m east then 4 m north covers 7 m but the displacement is 5 m.</p><p><strong>Speed</strong> = distance ÷ time (scalar, m/s). <strong>Velocity</strong> = displacement ÷ time (vector, m/s). A car moving in a circle at constant speed has changing velocity because its direction changes.</p>'},
{id:'bal-c9-phy-ch3-l3', title:'Acceleration and Equations of Motion', html:'<h3>Acceleration</h3><p><strong>Acceleration</strong> is the rate of change of velocity: a = (v − u) ÷ t, measured in m/s². Positive acceleration speeds up; negative acceleration (retardation) slows down.</p><p><strong>Equations of uniformly accelerated motion:</strong></p><ul><li>v = u + at</li><li>S = ut + ½at²</li><li>v² = u² + 2aS</li></ul><p>Example: a car starting from rest (u = 0) accelerates at 2 m/s² for 5 s → v = 0 + 2 × 5 = 10 m/s.</p>'}],
quiz:[
{q:'A body changes its position with time. It is in', options:['rest','motion','equilibrium','inertia'], answer:1, explain:'Motion is defined as change of position with time.'},
{q:'Which of the following is a vector quantity?', options:['distance','speed','displacement','time'], answer:2, explain:'Displacement has both magnitude and direction, so it is a vector.'},
{q:'A car moves in a circle at constant speed. Its velocity', options:['is constant','changes because direction changes','is zero','is a scalar'], answer:1, explain:'Velocity includes direction; in circular motion the direction keeps changing.'},
{q:'SI unit of acceleration is', options:['m/s','m/s²','km/h','N'], answer:1, explain:'Acceleration = change in velocity ÷ time, so its unit is m/s².'},
{q:'A car starts from rest and accelerates at 2 m/s² for 5 s. Its final velocity is', options:['5 m/s','7 m/s','10 m/s','25 m/s'], answer:2, explain:'v = u + at = 0 + 2 × 5 = 10 m/s.'},
{q:'Which equation gives distance when u, a and t are known?', options:['v = u + at','S = ut + ½at²','v² = u² + 2aS','a = v/t'], answer:1, explain:'S = ut + ½at² directly relates displacement to u, a and t.'},
{q:'Negative acceleration is also called', options:['impulse','retardation','momentum','torque'], answer:1, explain:'Retardation (deceleration) is acceleration opposite to the direction of motion.'},
{q:'The motion of a pendulum is an example of', options:['translatory motion','rotatory motion','vibratory motion','random motion'], answer:2, explain:'A pendulum moves to and fro about a mean position — vibratory motion.'},
{q:'Slope of a distance–time graph gives', options:['acceleration','speed','force','momentum'], answer:1, explain:'Speed = distance ÷ time, which is the slope of the distance–time graph.'},
{q:'A body falling freely near Earth accelerates at about', options:['1.6 m/s²','9.8 m/s²','3 × 10⁸ m/s²','0 m/s²'], answer:1, explain:'Free-fall acceleration due to gravity g ≈ 9.8 m/s² (10 m/s² in simple problems).'}]},
{id:'bal-c9-phy-ch4', title:'Dynamics and Forces', urdu:'حرکیات اور قوتیں', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch4-l1', title:'Force and Newton’s Laws of Motion', html:'<h3>Force</h3><p>A <strong>force</strong> is a push or pull that can change the state of motion of a body. Its SI unit is the <strong>newton (N)</strong>: 1 N = 1 kg·m/s².</p><p><strong>Newton’s laws:</strong></p><ul><li><strong>First law (inertia):</strong> a body stays at rest or in uniform motion unless a net force acts on it.</li><li><strong>Second law:</strong> F = ma — force equals mass times acceleration.</li><li><strong>Third law:</strong> every action has an equal and opposite reaction.</li></ul>'},
{id:'bal-c9-phy-ch4-l2', title:'Fundamental Forces and Friction', html:'<h3>Fundamental Forces of Nature</h3><ul><li><strong>Gravitational</strong> — weakest, acts between all masses.</li><li><strong>Electromagnetic</strong> — between charges; holds atoms together.</li><li><strong>Strong nuclear</strong> — strongest, binds protons and neutrons in the nucleus.</li><li><strong>Weak nuclear</strong> — responsible for radioactive decay.</li></ul><p><strong>Friction</strong> opposes relative motion between surfaces. It lets us walk and grip, but wastes energy as heat in machines.</p>'},
{id:'bal-c9-phy-ch4-l3', title:'Reducing Friction and its Uses', html:'<h3>Advantages and Disadvantages of Friction</h3><p><strong>Advantages:</strong> walking, writing, gripping objects, brakes stopping vehicles. <strong>Disadvantages:</strong> wear and tear of machine parts, wastage of energy as heat, reduced efficiency.</p><p><strong>Methods of reducing friction:</strong> lubrication (oil/grease), ball bearings, polishing surfaces, streamlining (aerodynamic shapes), and using air cushions.</p><p>Example: F = ma → a 2 kg mass accelerating at 3 m/s² needs F = 2 × 3 = 6 N.</p>'}],
quiz:[
{q:'SI unit of force is', options:['joule','newton','watt','pascal'], answer:1, explain:'Force is measured in newtons (N).'},
{q:'Newton’s second law is expressed as', options:['F = mv','F = ma','F = m/a','F = at'], answer:1, explain:'The second law states force equals mass times acceleration: F = ma.'},
{q:'A 2 kg mass accelerates at 3 m/s². The force required is', options:['1.5 N','5 N','6 N','9 N'], answer:2, explain:'F = ma = 2 × 3 = 6 N.'},
{q:'Newton’s first law is also called the law of', options:['action','inertia','gravitation','momentum'], answer:1, explain:'The first law describes inertia — the tendency to resist change in motion.'},
{q:'A rocket moves forward because of', options:['friction with air','Newton’s third law','gravity','centrifugal force'], answer:1, explain:'The rocket pushes exhaust gases back (action); gases push the rocket forward (reaction).'},
{q:'Which is the strongest fundamental force?', options:['gravitational','electromagnetic','strong nuclear','weak nuclear'], answer:2, explain:'The strong nuclear force binds the nucleus and is the strongest of the four.'},
{q:'Which is the weakest fundamental force?', options:['gravitational','electromagnetic','strong nuclear','weak nuclear'], answer:0, explain:'Gravity is by far the weakest fundamental force.'},
{q:'Friction can be reduced by', options:['making surfaces rough','using lubricants','increasing weight','removing wheels'], answer:1, explain:'Lubricants form a slippery layer between surfaces, reducing friction.'},
{q:'An advantage of friction is that it', options:['wastes fuel','causes wear','allows us to walk','heats machines'], answer:2, explain:'Without friction between shoes and ground, walking would be impossible.'},
{q:'The coefficient of friction has', options:['unit N','unit m/s','no unit','unit kg'], answer:2, explain:'It is the ratio of two forces, so it is a unitless (dimensionless) number.'}]},
{id:'bal-c9-phy-ch5', title:'Momentum', urdu:'مومنٹم', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch5-l1', title:'Momentum', html:'<h3>Momentum</h3><p><strong>Momentum</strong> (p) is the quantity of motion in a body: p = mv (mass × velocity). Its SI unit is <strong>kg·m/s</strong> (or N·s).</p><p>Momentum is a <strong>vector</strong>. A heavy slow truck and a light fast car can have the same momentum. Example: a 1000 kg car at 20 m/s has p = 20000 kg·m/s.</p>'},
{id:'bal-c9-phy-ch5-l2', title:'Impulse of a Force', html:'<h3>Impulse</h3><p><strong>Impulse</strong> = force × time = change in momentum: J = F × t = Δp. Its unit is N·s.</p><p>This is why airbags, helmets and cricket gloves work — they increase the <em>time</em> of impact, so the <em>force</em> on the body is smaller for the same change in momentum. A fielder pulls his hands back while catching to lengthen the stopping time.</p>'},
{id:'bal-c9-phy-ch5-l3', title:'Law of Conservation of Momentum', html:'<h3>Conservation of Momentum</h3><p>In the absence of external forces, the <strong>total momentum of a system stays constant</strong>: momentum before collision = momentum after collision.</p><p>Applications: recoil of a gun (bullet goes forward, gun kicks back), rocket propulsion, and a rowing boat moving when the rower pushes water backwards.</p><p>Numerically: a 0.01 kg bullet fired at 400 m/s from a 4 kg gun gives the gun a recoil speed v = (0.01 × 400) ÷ 4 = 1 m/s.</p>'}],
quiz:[
{q:'Momentum is defined as', options:['mass ÷ velocity','mass × velocity','force × time','weight × height'], answer:1, explain:'Momentum p = mv (mass times velocity).'},
{q:'SI unit of momentum is', options:['kg·m/s','N/m','J','W'], answer:0, explain:'p = mv gives kg × m/s = kg·m/s (also written N·s).'},
{q:'Momentum is a', options:['scalar quantity','vector quantity','unitless number','constant'], answer:1, explain:'Momentum has both magnitude and direction, so it is a vector.'},
{q:'A 1000 kg car moves at 20 m/s. Its momentum is', options:['50 kg·m/s','500 kg·m/s','20000 kg·m/s','200000 kg·m/s'], answer:2, explain:'p = mv = 1000 × 20 = 20000 kg·m/s.'},
{q:'Impulse equals', options:['force × distance','force × time','mass × acceleration','work ÷ time'], answer:1, explain:'Impulse J = F × t, which equals the change in momentum.'},
{q:'A fielder pulls his hands back while catching a ball to', options:['increase the force','increase the time of impact and reduce force','look stylish','increase momentum'], answer:1, explain:'Longer stopping time means smaller force for the same momentum change.'},
{q:'The law of conservation of momentum states that', options:['momentum always increases','total momentum stays constant without external force','momentum equals energy','momentum is destroyed in collisions'], answer:1, explain:'With no external force, total momentum before = total momentum after.'},
{q:'A gun recoils when fired because of', options:['gravity','conservation of momentum','friction','air pressure'], answer:1, explain:'Forward momentum of the bullet must be balanced by backward momentum of the gun.'},
{q:'A 0.01 kg bullet at 400 m/s fired from a 4 kg gun gives recoil speed', options:['0.1 m/s','1 m/s','4 m/s','40 m/s'], answer:1, explain:'4 × v = 0.01 × 400 = 4, so v = 1 m/s.'},
{q:'Airbags in cars reduce injury by', options:['increasing momentum','increasing impact time, reducing force','stopping the car faster','absorbing fuel'], answer:1, explain:'Airbags lengthen the time over which the passenger slows down, cutting the force.'}]},
{id:'bal-c9-phy-ch6', title:'Turning Effect of Forces', urdu:'قوتوں کا گھماؤ اثر', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch6-l1', title:'Torque and the Principle of Moments', html:'<h3>Turning Effect (Torque)</h3><p>The <strong>turning effect of a force</strong> is called <strong>torque</strong> (moment of force): torque = force × perpendicular distance from the pivot. SI unit: <strong>newton-metre (N·m)</strong>.</p><p>A longer spanner turns a nut more easily because the moment arm is larger. <strong>Principle of moments:</strong> for a balanced body, clockwise moments = anticlockwise moments.</p>'},
{id:'bal-c9-phy-ch6-l2', title:'Centre of Gravity and Equilibrium', html:'<h3>Centre of Gravity</h3><p>The <strong>centre of gravity</strong> is the point where the whole weight of a body appears to act. For a uniform ruler it is at the middle.</p><p><strong>States of equilibrium:</strong> <strong>stable</strong> (returns after a small push — wide base, low centre of gravity), <strong>unstable</strong> (topples), <strong>neutral</strong> (stays in the new position — a ball on a flat table).</p>'},
{id:'bal-c9-phy-ch6-l3', title:'Conditions of Equilibrium', html:'<h3>Conditions of Equilibrium</h3><p>A body is in <strong>equilibrium</strong> when:</p><ul><li><strong>First condition:</strong> the vector sum of all forces is zero (ΣF = 0) — no translational motion.</li><li><strong>Second condition:</strong> the sum of all torques about any point is zero (Στ = 0) — no rotation.</li></ul><p>Racing cars are built low and wide so their centre of gravity stays low — improving stability on turns.</p>'}],
quiz:[
{q:'Torque is calculated as', options:['force ÷ distance','force × perpendicular distance','mass × velocity','work ÷ time'], answer:1, explain:'Torque (moment) = force × perpendicular distance from the pivot.'},
{q:'SI unit of torque is', options:['N','N·m','J/s','kg·m/s'], answer:1, explain:'Torque = force × distance, so its unit is the newton-metre (N·m).'},
{q:'A longer spanner opens a tight nut more easily because', options:['it is heavier','the moment arm is larger','it is shinier','friction is less'], answer:1, explain:'Greater distance from the pivot gives greater torque for the same force.'},
{q:'The principle of moments states that for balance', options:['forces must be equal','clockwise moments = anticlockwise moments','torques must be zero','mass must be centred'], answer:1, explain:'A body balances when total clockwise moments equal total anticlockwise moments.'},
{q:'The centre of gravity of a uniform ruler is', options:['at one end','at its midpoint','below it','at the top'], answer:1, explain:'For a uniform body, the centre of gravity is at its geometric centre.'},
{q:'A racing car is built low and wide to', options:['look attractive','lower the centre of gravity for stability','reduce weight','increase speed'], answer:1, explain:'A low centre of gravity and wide base give stable equilibrium.'},
{q:'The first condition of equilibrium is', options:['ΣF = 0','Στ = 0','ΣF = ma','ΣE = 0'], answer:0, explain:'No net force means no translational acceleration — the first condition.'},
{q:'The second condition of equilibrium is', options:['ΣF = 0','Στ = 0','Σm = 0','Σv = 0'], answer:1, explain:'No net torque means no rotation — the second condition.'},
{q:'A ball on a flat table is in', options:['stable equilibrium','unstable equilibrium','neutral equilibrium','no equilibrium'], answer:2, explain:'Pushed slightly, it stays in its new position — neutral equilibrium.'},
{q:'A force of 10 N applied 0.5 m from a pivot produces torque', options:['5 N·m','10 N·m','20 N·m','0.5 N·m'], answer:0, explain:'Torque = 10 × 0.5 = 5 N·m.'}]},
{id:'bal-c9-phy-ch7', title:'Centripetal Force', urdu:'مرکز مائل قوت', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch7-l1', title:'Circular Motion', html:'<h3>Circular Motion</h3><p>A body moving in a circle constantly changes direction, so even at constant speed it is <strong>accelerating</strong> — its velocity keeps changing.</p><p>Examples: a stone whirled on a string, the Moon orbiting Earth, a car rounding a bend. The time for one full circle is the <strong>period (T)</strong>; the number of circles per second is the <strong>frequency (f)</strong>, with f = 1/T.</p>'},
{id:'bal-c9-phy-ch7-l2', title:'Centripetal Force and Acceleration', html:'<h3>Centripetal Force</h3><p><strong>Centripetal force</strong> is the net force pulling a body toward the centre of its circular path: Fc = mv²/r. Without it, the body would fly off in a straight line (Newton’s first law).</p><p><strong>Centripetal acceleration</strong> ac = v²/r, also directed toward the centre. For a stone on a string, the string’s tension provides the centripetal force; for the Moon, it is Earth’s gravity.</p>'},
{id:'bal-c9-phy-ch7-l3', title:'Centrifugal Force and Applications', html:'<h3>Centrifugal Force</h3><p><strong>Centrifugal force</strong> is the apparent outward push felt in a rotating frame — for example, passengers pushed outward when a bus turns. It is not a real force but an effect of inertia.</p><p><strong>Applications:</strong> the cream separator spins milk so denser skim milk moves outward; the spin dryer in a washing machine; banked (tilted) road curves help cars turn safely.</p>'}],
quiz:[
{q:'A body moving in a circle at constant speed', options:['has constant velocity','is accelerating because direction changes','has no acceleration','is at rest'], answer:1, explain:'Velocity includes direction, which changes continuously in circular motion.'},
{q:'Centripetal force always acts', options:['away from the centre','toward the centre','along the motion','upwards'], answer:1, explain:'Centripetal means “centre-seeking” — it pulls the body toward the centre.'},
{q:'The formula for centripetal force is', options:['Fc = mv/r','Fc = mv²/r','Fc = mvr','Fc = v²/mr'], answer:1, explain:'Centripetal force Fc = mv²/r.'},
{q:'For the Moon orbiting Earth, the centripetal force is provided by', options:['the Sun’s pull','Earth’s gravity','air pressure','magnetism'], answer:1, explain:'Earth’s gravitational pull keeps the Moon in its circular orbit.'},
{q:'For a stone whirled on a string, centripetal force comes from', options:['gravity','tension in the string','air resistance','friction'], answer:1, explain:'The string pulls the stone inward — its tension is the centripetal force.'},
{q:'If the string breaks, the stone will', options:['fall straight down at once','fly off tangentially in a straight line','stop immediately','spiral inward'], answer:1, explain:'With no inward force, inertia carries it straight along the tangent.'},
{q:'Centrifugal force is', options:['a real inward force','an apparent outward effect of inertia','equal to gravity','the same as friction'], answer:1, explain:'It is felt in rotating frames but is an effect of inertia, not a real force.'},
{q:'A cream separator works on the principle of', options:['gravity','centrifugal effect','magnetism','osmosis'], answer:1, explain:'Spinning throws denser skim milk outward, separating it from cream.'},
{q:'Frequency f and period T are related by', options:['f = T','f = 1/T','f = T²','f = 2T'], answer:1, explain:'Frequency is the reciprocal of the period: f = 1/T.'},
{q:'Road curves are banked (tilted) to', options:['look modern','help provide centripetal force for safe turning','reduce distance','increase friction only'], answer:1, explain:'Banking tilts the normal force inward, supplying part of the needed centripetal force.'}]},
{id:'bal-c9-phy-ch8', title:'Work, Energy and Power', urdu:'کام، توانائی اور طاقت', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch8-l1', title:'Work', html:'<h3>Work</h3><p><strong>Work</strong> is done when a force moves a body: W = F × d (force × distance in the direction of the force). SI unit: the <strong>joule (J)</strong>.</p><p>No displacement means no work in physics — holding a heavy bag still does no work, however tired you feel. Lifting a 10 N weight through 2 m does W = 20 J of work.</p>'},
{id:'bal-c9-phy-ch8-l2', title:'Energy: Kinetic and Potential', html:'<h3>Energy</h3><p><strong>Energy</strong> is the ability to do work, measured in joules.</p><ul><li><strong>Kinetic energy</strong> (motion): KE = ½mv².</li><li><strong>Potential energy</strong> (position): gravitational PE = mgh.</li></ul><p>A moving car has kinetic energy; water stored behind a dam has potential energy. Energy constantly changes form — a falling ball converts PE into KE.</p>'},
{id:'bal-c9-phy-ch8-l3', title:'Conservation of Energy, Power and Sources', html:'<h3>Conservation of Energy</h3><p>Energy cannot be created or destroyed, only <strong>converted</strong> from one form to another — the <strong>principle of conservation of energy</strong>.</p><p><strong>Power</strong> is the rate of doing work: P = W/t, measured in <strong>watts (W)</strong>.</p><p><strong>Renewable sources:</strong> solar, wind, hydro, biomass, geothermal. <strong>Non-renewable:</strong> coal, oil, natural gas — they pollute and will run out.</p>'}],
quiz:[
{q:'Work is defined as', options:['force × time','force × distance','mass × velocity','energy × time'], answer:1, explain:'Work W = F × d, force times distance moved in the force’s direction.'},
{q:'SI unit of work and energy is', options:['watt','newton','joule','pascal'], answer:2, explain:'Both work and energy are measured in joules (J).'},
{q:'Holding a heavy bag without moving does', options:['maximum work','no work in physics','negative work','double work'], answer:1, explain:'Work needs displacement; with d = 0, W = 0.'},
{q:'Kinetic energy of a body is given by', options:['mgh','½mv²','mv','Fd'], answer:1, explain:'KE = ½mv² (half mass times velocity squared).'},
{q:'Potential energy of a mass m at height h is', options:['½mv²','mgh','mv²','m/h'], answer:1, explain:'Gravitational potential energy PE = mgh.'},
{q:'The principle of conservation of energy states that energy', options:['can be created','can be destroyed','only changes form, total stays constant','disappears as heat'], answer:2, explain:'Energy is never created or destroyed, only converted between forms.'},
{q:'Power is defined as', options:['work × time','work ÷ time','force × distance','energy × time'], answer:1, explain:'Power P = W/t, the rate of doing work, measured in watts.'},
{q:'Which is a renewable source of energy?', options:['coal','natural gas','solar energy','petrol'], answer:2, explain:'Solar energy is continuously renewed by nature.'},
{q:'Lifting a 10 N weight through 2 m does work of', options:['5 J','12 J','20 J','200 J'], answer:2, explain:'W = F × d = 10 × 2 = 20 J.'},
{q:'A machine does 500 J of work in 10 s. Its power is', options:['50 W','500 W','5000 W','5 W'], answer:0, explain:'P = W/t = 500 ÷ 10 = 50 W.'}]},
{id:'bal-c9-phy-ch9', title:'Pressure', urdu:'دباؤ', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch9-l1', title:'Pressure and its Unit', html:'<h3>Pressure</h3><p><strong>Pressure</strong> is force per unit area: P = F/A. SI unit: the <strong>pascal (Pa)</strong> = 1 N/m².</p><p>The same force gives more pressure on a smaller area — that is why a sharp knife cuts better than a blunt one, and why a person sinks in soft snow but a snowshoe wearer does not.</p>'},
{id:'bal-c9-phy-ch9-l2', title:'Pressure in Liquids and Pascal’s Law', html:'<h3>Liquid Pressure</h3><p>Pressure in a liquid increases with <strong>depth</strong>: P = ρgh (density × g × height). It acts equally in all directions and depends only on depth, not on the container’s shape.</p><p><strong>Pascal’s law:</strong> pressure applied to an enclosed fluid is transmitted equally in all directions. Hydraulic brakes and hydraulic lifts work on this principle — a small force on a small piston creates a large force on a large piston.</p>'},
{id:'bal-c9-phy-ch9-l3', title:'Atmospheric Pressure', html:'<h3>Atmospheric Pressure</h3><p>The air around us exerts pressure — about <strong>101325 Pa (1 atm)</strong> at sea level. It is measured with a <strong>barometer</strong>.</p><p>Atmospheric pressure <strong>decreases with altitude</strong>: it is lower on a mountain top than at sea level, which is why water boils below 100 °C on mountains. Drinking through a straw works because sucking lowers the pressure inside the straw and the atmosphere pushes the liquid up.</p>'}],
quiz:[
{q:'Pressure is defined as', options:['force × area','force ÷ area','mass × volume','work ÷ time'], answer:1, explain:'Pressure P = F/A.'},
{q:'SI unit of pressure is', options:['newton','joule','pascal','watt'], answer:2, explain:'Pressure is measured in pascals (Pa = N/m²).'},
{q:'A sharp knife cuts better than a blunt one because', options:['it is heavier','the same force acts on a smaller area, giving more pressure','it is longer','steel is stronger'], answer:1, explain:'Smaller area means greater pressure for the same force.'},
{q:'Pressure in a liquid depends on', options:['the shape of the container','depth only','the colour of liquid','the container’s width'], answer:1, explain:'P = ρgh — it depends on depth (and density), not container shape.'},
{q:'Pascal’s law states that pressure applied to an enclosed fluid', options:['disappears','is transmitted equally in all directions','acts only downward','doubles'], answer:1, explain:'Pascal’s law: applied pressure spreads undiminished through the fluid.'},
{q:'Hydraulic brakes work on', options:['Archimedes’ principle','Pascal’s law','Hooke’s law','Ohm’s law'], answer:1, explain:'Hydraulics transmit pressure through enclosed brake fluid — Pascal’s law.'},
{q:'Atmospheric pressure at sea level is about', options:['101 Pa','1013 Pa','101325 Pa','10⁶ Pa'], answer:2, explain:'Standard atmospheric pressure is 101325 Pa (1 atm).'},
{q:'Atmospheric pressure decreases when we go', options:['underground','to higher altitude','near the sea','into a valley'], answer:1, explain:'There is less air above at higher altitude, so pressure falls.'},
{q:'Water boils below 100 °C on a mountain because', options:['air is colder','atmospheric pressure is lower','water is purer','gravity is less'], answer:1, explain:'Lower air pressure means water boils at a lower temperature.'},
{q:'A barometer measures', options:['temperature','humidity','atmospheric pressure','wind speed'], answer:2, explain:'A barometer measures the pressure of the atmosphere.'}]},
{id:'bal-c9-phy-ch10', title:'Deformation of Solids', urdu:'ٹھوس کی شکل میں تبدیلی', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch10-l1', title:'Stress and Strain', html:'<h3>Deformation of Solids</h3><p>When a force is applied to a solid, it may stretch, compress or bend — this change of shape is <strong>deformation</strong>.</p><p><strong>Stress</strong> = deforming force ÷ area (unit: Pa). <strong>Strain</strong> = change in length ÷ original length (no unit). A rubber band shows large strain for small stress; a steel wire shows small strain.</p>'},
{id:'bal-c9-phy-ch10-l2', title:'Hooke’s Law', html:'<h3>Hooke’s Law</h3><p><strong>Hooke’s law:</strong> within the elastic limit, the extension of a spring is directly proportional to the applied force: F = kx, where k is the spring constant.</p><p>A load–extension graph is a straight line through the origin while Hooke’s law holds. Beyond the <strong>elastic limit</strong>, the spring stays permanently stretched.</p>'},
{id:'bal-c9-phy-ch10-l3', title:'Elasticity and Applications', html:'<h3>Elasticity</h3><p><strong>Elasticity</strong> is the property of returning to the original shape after the deforming force is removed. Steel is more elastic than rubber in the physics sense — it returns to shape more completely.</p><p><strong>Applications of Hooke’s law:</strong> spring balances, bathroom scales, vehicle suspension springs, and seismometers that detect earthquakes.</p>'}],
quiz:[
{q:'Stress is defined as', options:['force × area','force ÷ area','extension ÷ length','mass × gravity'], answer:1, explain:'Stress = deforming force per unit area (Pa).'},
{q:'Strain is', options:['force per unit area','change in length ÷ original length','mass per unit volume','work per unit time'], answer:1, explain:'Strain = extension ÷ original length; it has no unit.'},
{q:'Hooke’s law states that within the elastic limit', options:['stress × strain is constant','extension is proportional to force','force is proportional to area','strain equals stress'], answer:1, explain:'F = kx — extension is directly proportional to the applied force.'},
{q:'In F = kx, k represents', options:['kinetic energy','spring constant','strain','stress'], answer:1, explain:'k is the spring constant — stiffness of the spring.'},
{q:'Beyond the elastic limit, a stretched spring', options:['returns exactly','stays permanently deformed','becomes stronger','shrinks'], answer:1, explain:'Past the elastic limit the deformation becomes permanent.'},
{q:'Which is more elastic in the physics sense?', options:['rubber','steel','clay','wax'], answer:1, explain:'Steel returns to its original shape more completely than rubber.'},
{q:'A spring balance works on', options:['Pascal’s law','Hooke’s law','Ohm’s law','Archimedes’ principle'], answer:1, explain:'It measures weight from spring extension using F = kx.'},
{q:'The unit of stress is', options:['newton','pascal','metre','joule'], answer:1, explain:'Stress = force ÷ area, so its unit is N/m² = pascal.'},
{q:'A load–extension graph is a straight line through the origin while', options:['Hooke’s law holds','the spring breaks','temperature rises','force is zero'], answer:0, explain:'Proportionality (F ∝ x) gives a straight-line graph through the origin.'},
{q:'If a 10 N force extends a spring by 0.2 m, the spring constant is', options:['2 N/m','5 N/m','50 N/m','0.02 N/m'], answer:2, explain:'k = F/x = 10 ÷ 0.2 = 50 N/m.'}]},
{id:'bal-c9-phy-ch11', title:'Density', urdu:'کثافت', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch11-l1', title:'Density and its Measurement', html:'<h3>Density</h3><p><strong>Density</strong> = mass ÷ volume: ρ = m/V. SI unit: <strong>kg/m³</strong> (also g/cm³; 1 g/cm³ = 1000 kg/m³).</p><p>Density tells how tightly matter is packed. Iron (7900 kg/m³) is denser than water (1000 kg/m³), so iron sinks while wood floats.</p>'},
{id:'bal-c9-phy-ch11-l2', title:'Determining Density', html:'<h3>Finding Density</h3><ul><li><strong>Regular solid:</strong> measure mass with a balance, volume from dimensions (e.g. l × w × h), then ρ = m/V.</li><li><strong>Irregular solid that sinks:</strong> volume = volume of water displaced in a measuring cylinder (or by a Eureka can).</li><li><strong>Liquid:</strong> mass of a known volume measured with a measuring cylinder.</li></ul>'},
{id:'bal-c9-phy-ch11-l3', title:'Relative Density and Floating', html:'<h3>Relative Density</h3><p><strong>Relative density</strong> = density of substance ÷ density of water. It has <strong>no unit</strong>.</p><p>A body <strong>floats</strong> if its density is less than the fluid’s, and <strong>sinks</strong> if greater. Ships float because their overall density (hull + air inside) is less than water’s; submarines dive by letting water into ballast tanks.</p>'}],
quiz:[
{q:'Density is defined as', options:['mass × volume','mass ÷ volume','weight ÷ area','force × distance'], answer:1, explain:'Density ρ = m/V.'},
{q:'SI unit of density is', options:['g/cm³','kg/m³','N/m²','kg·m/s'], answer:1, explain:'The SI unit is kg/m³ (g/cm³ is the common cgs unit).'},
{q:'1 g/cm³ equals', options:['10 kg/m³','100 kg/m³','1000 kg/m³','1 kg/m³'], answer:2, explain:'1 g/cm³ = 1000 kg/m³.'},
{q:'An iron nail sinks in water because', options:['it is small','its density is greater than water’s','it is cold','water pushes it down'], answer:1, explain:'Iron’s density (7900 kg/m³) exceeds water’s (1000 kg/m³), so it sinks.'},
{q:'Relative density has', options:['unit kg/m³','unit g/cm³','no unit','unit N'], answer:2, explain:'It is a ratio of two densities, so it is unitless.'},
{q:'Volume of an irregular stone is found by', options:['a ruler','water displacement in a measuring cylinder','weighing it','a stopwatch'], answer:1, explain:'The displaced water’s volume equals the stone’s volume.'},
{q:'A ship floats because', options:['it is made of steel','its overall density is less than water’s','it is painted','engines push it up'], answer:1, explain:'The hull encloses air, so average density stays below water’s.'},
{q:'A 2 kg block has volume 0.5 m³. Its density is', options:['1 kg/m³','2.5 kg/m³','4 kg/m³','0.25 kg/m³'], answer:2, explain:'ρ = m/V = 2 ÷ 0.5 = 4 kg/m³.'},
{q:'Submarines dive by', options:['increasing speed','letting water into ballast tanks','heating the hull','releasing air only'], answer:1, explain:'Water in the tanks raises overall density above water’s, so it sinks.'},
{q:'Density of water is', options:['100 kg/m³','1000 kg/m³','10 kg/m³','10000 kg/m³'], answer:1, explain:'Water’s density is 1000 kg/m³ (1 g/cm³).'}]},
{id:'bal-c9-phy-ch12', title:'Particle Theory of Matter', urdu:'مادے کا ذراتی نظریہ', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch12-l1', title:'States of Matter and the Kinetic Theory', html:'<h3>States of Matter</h3><ul><li><strong>Solid:</strong> fixed shape and volume; particles vibrate in fixed positions.</li><li><strong>Liquid:</strong> fixed volume, takes the container’s shape; particles slide past each other.</li><li><strong>Gas:</strong> no fixed shape or volume; particles move freely and fill the container.</li><li><strong>Plasma:</strong> ionised gas at very high temperature (stars, lightning).</li></ul><p>The <strong>kinetic theory</strong> says all matter is made of tiny particles in constant motion.</p>'},
{id:'bal-c9-phy-ch12-l2', title:'Heat, Temperature and Thermometers', html:'<h3>Heat and Temperature</h3><p><strong>Heat</strong> is energy flowing from a hot body to a cold one (joule). <strong>Temperature</strong> measures how hot or cold a body is — the average kinetic energy of its particles.</p><p><strong>Thermometer scales:</strong> Celsius (°C), Fahrenheit (°F), Kelvin (K). Water freezes at 0 °C / 273 K and boils at 100 °C / 373 K. A <strong>clinical thermometer</strong> measures body temperature (≈ 37 °C) and has a kink to hold the reading.</p>'},
{id:'bal-c9-phy-ch12-l3', title:'Thermal Expansion and Particle Motion', html:'<h3>Effect of Heat on Particles</h3><p>Heating makes particles move faster and spread apart — most solids, liquids and gases <strong>expand on heating</strong> and contract on cooling. Gaps are left between railway tracks for this reason.</p><p><strong>Brownian motion</strong> — the random zigzag movement of smoke particles in air — is direct evidence that particles of matter are constantly moving.</p>'}],
quiz:[
{q:'Which state has a fixed shape and volume?', options:['gas','liquid','solid','plasma'], answer:2, explain:'Solids keep both shape and volume because particles are locked in place.'},
{q:'Plasma is', options:['frozen gas','ionised gas at very high temperature','a type of liquid','compressed solid'], answer:1, explain:'Plasma — found in stars and lightning — is ionised gas.'},
{q:'Temperature measures', options:['total heat energy','average kinetic energy of particles','amount of matter','pressure'], answer:1, explain:'Temperature reflects the average kinetic energy of the particles.'},
{q:'Water boils at', options:['0 °C','37 °C','100 °C','273 °C'], answer:2, explain:'At standard pressure, water boils at 100 °C (373 K).'},
{q:'0 °C in kelvin is', options:['0 K','100 K','273 K','373 K'], answer:2, explain:'K = °C + 273, so 0 °C = 273 K.'},
{q:'A clinical thermometer has a kink to', options:['look nice','prevent mercury falling back before reading','measure high heat','break easily'], answer:1, explain:'The kink holds the mercury thread in place so the reading can be taken.'},
{q:'Railway tracks have gaps because', options:['of looks','rails expand in heat','of noise','of cost'], answer:1, explain:'Metal rails expand on heating; gaps prevent buckling.'},
{q:'Brownian motion is evidence that', options:['air is still','particles are constantly moving','smoke is heavy','light bends'], answer:1, explain:'The random zigzag of smoke particles is caused by collisions with moving air molecules.'},
{q:'Normal human body temperature is about', options:['35 °C','37 °C','40 °C','42 °C'], answer:1, explain:'Normal body temperature is about 37 °C (98.6 °F).'},
{q:'Heat flows from', options:['cold to hot','hot to cold','both ways equally','nowhere'], answer:1, explain:'Heat energy always flows from higher to lower temperature.'}]},
{id:'bal-c9-phy-ch13', title:'Magnetism', urdu:'مقناطیسیت', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch13-l1', title:'Magnets and Magnetic Materials', html:'<h3>Magnets</h3><p>A <strong>magnet</strong> attracts iron, nickel and cobalt. Every magnet has two poles — <strong>north and south</strong>; like poles repel, unlike poles attract. A magnet’s power is strongest at its poles.</p><p><strong>Magnetic materials</strong> (iron, steel, nickel, cobalt) are attracted to magnets; <strong>non-magnetic materials</strong> (wood, plastic, copper, aluminium) are not. <strong>Temporary magnets</strong> (soft iron) lose magnetism easily; <strong>permanent magnets</strong> (steel) keep it.</p>'},
{id:'bal-c9-phy-ch13-l2', title:'Magnetic Field and Domain Theory', html:'<h3>Magnetic Field</h3><p>The region around a magnet where its force acts is the <strong>magnetic field</strong>, shown by <strong>field lines</strong> going from north to south pole outside the magnet.</p><p><strong>Domain theory:</strong> in an unmagnetised iron bar, tiny magnetic domains point randomly and cancel out. Stroking with a magnet aligns the domains, making the bar a magnet. Heating or hammering jumbles them again — <strong>demagnetisation</strong>.</p>'},
{id:'bal-c9-phy-ch13-l3', title:'Electromagnets, Earth’s Magnetism and Uses', html:'<h3>Electromagnets</h3><p>A coil of wire around soft iron becomes a magnet when current flows — an <strong>electromagnet</strong>. Its strength grows with more turns and more current. Uses: electric bells, cranes lifting scrap iron, relays.</p><p><strong>Earth</strong> itself is a giant magnet; a compass needle points north–south along Earth’s field. <strong>Ferromagnetic</strong> materials (iron) are strongly attracted; <strong>paramagnetic</strong> weakly; <strong>diamagnetic</strong> (copper, bismuth) are weakly repelled. Magnets are used in recording (hard disks), motors and MRI scanners.</p>'}],
quiz:[
{q:'Which metal is attracted by a magnet?', options:['copper','aluminium','iron','plastic'], answer:2, explain:'Iron is a magnetic material; copper, aluminium and plastic are not.'},
{q:'Like magnetic poles', options:['attract','repel','have no effect','cancel out'], answer:1, explain:'Like poles repel; unlike poles attract.'},
{q:'A magnet’s force is strongest at its', options:['middle','poles','edges','top'], answer:1, explain:'The poles have the greatest concentration of field lines.'},
{q:'Magnetic field lines outside a magnet go', options:['south to north','north to south','in circles','nowhere'], answer:1, explain:'By convention, field lines leave the north pole and enter the south pole.'},
{q:'According to domain theory, an iron bar becomes magnetic when', options:['heated','its domains align in one direction','hammered','cooled'], answer:1, explain:'Aligned domains add up to a net magnetic field.'},
{q:'Demagnetisation can be caused by', options:['stroking with a magnet','heating or hammering','cooling','painting'], answer:1, explain:'Heat and hammering randomise the aligned domains.'},
{q:'An electromagnet needs', options:['a permanent magnet','current through a coil around soft iron','gravity','light'], answer:1, explain:'Current in the coil magnetises the soft-iron core temporarily.'},
{q:'A compass needle points north because', options:['of gravity','Earth acts as a giant magnet','of wind','of friction'], answer:1, explain:'Earth’s magnetic field aligns the compass needle north–south.'},
{q:'Which material is diamagnetic?', options:['iron','nickel','copper','cobalt'], answer:2, explain:'Copper is weakly repelled by magnets — diamagnetic.'},
{q:'Temporary magnets are made of', options:['steel','soft iron','copper','aluminium'], answer:1, explain:'Soft iron magnetises easily and loses it quickly — ideal for electromagnets.'}]},
{id:'bal-c9-phy-ch14', title:'Space Physics', urdu:'خلائی طبیعیات', comingSoon:false, lessons:[
{id:'bal-c9-phy-ch14-l1', title:'The Solar System', html:'<h3>Our Solar System</h3><p>The <strong>Sun</strong> is a star at the centre; eight planets orbit it.</p><ul><li><strong>Inner (terrestrial) planets:</strong> Mercury, Venus, Earth, Mars — small and rocky.</li><li><strong>Outer planets:</strong> Jupiter, Saturn, Uranus, Neptune — giant gas planets.</li></ul><p>Earth is the only known planet with life, with liquid water and a protective atmosphere.</p>'},
{id:'bal-c9-phy-ch14-l2', title:'Orbits and Orbital Speed', html:'<h3>Orbital Motion</h3><p>Planets stay in orbit because the Sun’s <strong>gravity</strong> provides the centripetal force. The <strong>orbital speed</strong> of a planet depends on its distance: nearer planets move faster (Mercury ≈ 47 km/s; Neptune ≈ 5.4 km/s).</p><p>Earth orbits the Sun once a year (≈ 365 days) at about 30 km/s, while spinning on its axis once a day — giving day and night.</p>'},
{id:'bal-c9-phy-ch14-l3', title:'Satellites and Space Exploration', html:'<h3>Satellites</h3><p><strong>Natural satellites:</strong> the Moon orbits Earth. <strong>Artificial satellites</strong> are human-made: <strong>geostationary</strong> satellites hover over one spot (TV, weather), while <strong>polar</strong> satellites scan the whole Earth.</p><p>Pakistan’s space agency <strong>SUPARCO</strong> operates satellites such as PAKSAT. A satellite stays up because its forward speed balances Earth’s gravitational pull — it is in continuous free fall around Earth.</p>'}],
quiz:[
{q:'The Sun is a', options:['planet','star','moon','comet'], answer:1, explain:'The Sun is a star — a glowing ball of hot plasma.'},
{q:'Which are the inner (terrestrial) planets?', options:['Jupiter, Saturn, Uranus, Neptune','Mercury, Venus, Earth, Mars','Earth, Mars, Jupiter, Saturn','Venus, Earth, Jupiter, Mars'], answer:1, explain:'Mercury, Venus, Earth and Mars are small rocky inner planets.'},
{q:'The largest planet is', options:['Saturn','Earth','Jupiter','Neptune'], answer:2, explain:'Jupiter is the largest planet in the solar system.'},
{q:'Planets stay in orbit because', options:['of air pressure','the Sun’s gravity provides centripetal force','of magnetism','they have engines'], answer:1, explain:'Gravity pulls inward, acting as the centripetal force for orbital motion.'},
{q:'Which planet orbits the Sun fastest?', options:['Neptune','Earth','Mars','Mercury'], answer:3, explain:'Mercury is nearest the Sun and has the highest orbital speed (≈ 47 km/s).'},
{q:'Earth spins on its axis once in about', options:['1 hour','24 hours','1 month','1 year'], answer:1, explain:'One rotation takes about 24 hours, giving day and night.'},
{q:'Geostationary satellites are used for', options:['deep space travel','TV and weather over one region','moon landing','mining'], answer:1, explain:'They stay fixed over one spot on the equator — ideal for TV and weather.'},
{q:'Pakistan’s space agency is', options:['NASA','SUPARCO','ESA','ISRO'], answer:1, explain:'SUPARCO (Space and Upper Atmosphere Research Commission) is Pakistan’s space agency.'},
{q:'A satellite stays in orbit because', options:['rockets push it constantly','its speed balances Earth’s gravity in continuous free fall','air holds it up','of magnetism'], answer:1, explain:'Orbital motion is a balance between forward speed and gravitational pull.'},
{q:'The Moon is Earth’s', options:['artificial satellite','natural satellite','planet','star'], answer:1, explain:'The Moon is a natural satellite orbiting Earth.'}]}
]});
