window.__saMergeCourse({id:'bal-class9-chemistry', board:'balochistan', title:'Chemistry', urdu:'کیمسٹری', class:'Class 9', icon:'🧪', desc:'Balochistan Board Class 9 Chemistry — full syllabus with lessons and quizzes.', chapters:[
{id:'bal-c9-che-ch1', title:'Nature of Science in Chemistry', urdu:'کیمسٹری میں سائنس کی نوعیت', comingSoon:false, lessons:[
{id:'bal-c9-che-ch1-l1', title:'What is Chemistry?', html:'<h3>Chemistry — the Central Science</h3><p><strong>Chemistry</strong> is the branch of science that studies matter — its composition, properties and the changes it undergoes. It links physics, biology, geology and environmental science, which is why it is called the <strong>central science</strong>.</p><p>From the soap you use to the medicines you take, chemistry explains how substances behave and how new materials are made.</p>'},
{id:'bal-c9-che-ch1-l2', title:'Branches of Chemistry', html:'<h3>Subfields of Chemistry</h3><ul><li><strong>Physical chemistry</strong> — energy and physical behaviour of matter.</li><li><strong>Organic chemistry</strong> — carbon compounds.</li><li><strong>Inorganic chemistry</strong> — all other elements and compounds.</li><li><strong>Analytical chemistry</strong> — identifying and measuring substances.</li><li><strong>Biochemistry</strong> — chemistry of living things.</li><li><strong>Environmental chemistry</strong> — chemistry of air, water and soil.</li></ul><p>Interdisciplinary fields include <strong>medicinal chemistry</strong>, <strong>polymer chemistry</strong> and <strong>geochemistry</strong>.</p>'},
{id:'bal-c9-che-ch1-l3', title:'Science, Technology and Engineering in Chemistry', html:'<h3>Science, Technology and Engineering</h3><p><strong>Science</strong> (chemistry) discovers principles, <strong>technology</strong> turns them into products like fertilisers and plastics, and <strong>engineering</strong> (chemical engineering) designs the plants that make them safely and cheaply.</p><p>Chemists work scientifically: observe, hypothesise, experiment and conclude — for example, testing which fertiliser dose gives the best wheat yield.</p>'}],
quiz:[
{q:'Chemistry is called the central science because it', options:['is the oldest science','links physics, biology and other sciences','is studied in the centre of books','has no branches'], answer:1, explain:'Chemistry connects physics, biology, geology and environmental science.'},
{q:'The study of carbon compounds is', options:['inorganic chemistry','organic chemistry','physical chemistry','analytical chemistry'], answer:1, explain:'Organic chemistry deals with compounds of carbon.'},
{q:'Identifying unknown substances in a sample is the job of', options:['biochemistry','analytical chemistry','polymer chemistry','geochemistry'], answer:1, explain:'Analytical chemistry identifies and measures substances.'},
{q:'Chemistry of living organisms is studied in', options:['biochemistry','inorganic chemistry','physical chemistry','environmental chemistry'], answer:0, explain:'Biochemistry is the chemistry of life processes.'},
{q:'Chemical engineering mainly deals with', options:['discovering new elements','designing plants to make chemicals safely and cheaply','writing textbooks','testing water only'], answer:1, explain:'Chemical engineers scale up chemical processes into working plants.'},
{q:'Which is an interdisciplinary field of chemistry?', options:['pure mathematics','medicinal chemistry','classical mechanics','astronomy'], answer:1, explain:'Medicinal chemistry combines chemistry with medicine and biology.'},
{q:'Technology in chemistry means', options:['doing experiments','applying chemical knowledge to make useful products','memorising formulas','observing nature'], answer:1, explain:'Technology applies scientific knowledge to create products like plastics and medicines.'},
{q:'The first step of the scientific method is', options:['conclusion','experiment','observation','hypothesis'], answer:2, explain:'Science begins with careful observation of a phenomenon.'},
{q:'Environmental chemistry studies', options:['only air','air, water and soil chemistry','rocks only','space'], answer:1, explain:'It covers the chemistry of the atmosphere, hydrosphere and soil.'},
{q:'Which pair is correct?', options:['organic — metals','inorganic — carbon compounds','physical — energy changes in matter','analytical — living cells'], answer:2, explain:'Physical chemistry studies energy and physical behaviour of matter.'}]},
{id:'bal-c9-che-ch2', title:'Matter', urdu:'مادہ', comingSoon:false, lessons:[
{id:'bal-c9-che-ch2-l1', title:'States of Matter and their Properties', html:'<h3>States of Matter</h3><table><tr><th>State</th><th>Shape</th><th>Volume</th><th>Particle arrangement</th></tr><tr><td>Solid</td><td>fixed</td><td>fixed</td><td>tightly packed, vibrate</td></tr><tr><td>Liquid</td><td>takes container’s</td><td>fixed</td><td>close, slide past each other</td></tr><tr><td>Gas</td><td>fills container</td><td>fills container</td><td>far apart, move freely</td></tr></table><p><strong>Exotic states:</strong> <strong>plasma</strong> (ionised gas in stars and lightning) and <strong>Bose–Einstein condensate</strong> (near absolute zero).</p>'},
{id:'bal-c9-che-ch2-l2', title:'Elements, Compounds and Mixtures', html:'<h3>Classification of Matter</h3><ul><li><strong>Element</strong> — pure substance of one kind of atom (iron, oxygen). Cannot be broken down chemically.</li><li><strong>Compound</strong> — two or more elements chemically combined in fixed ratio (water H₂O). New properties; separated only chemically.</li><li><strong>Mixture</strong> — physically mixed substances (air, salt solution). Variable composition; separated physically.</li></ul><p><strong>Allotropic forms</strong> of carbon: <strong>diamond</strong> (hardest, tetrahedral network), <strong>graphite</strong> (soft, layered, conducts electricity), <strong>fullerene</strong> (cage-like C₆₀).</p>'},
{id:'bal-c9-che-ch2-l3', title:'Solutions, Colloids and Suspensions', html:'<h3>Types of Mixtures</h3><table><tr><th>Type</th><th>Particle size</th><th>Example</th></tr><tr><td><strong>Solution</strong></td><td>&lt; 1 nm</td><td>salt in water</td></tr><tr><td><strong>Colloid</strong></td><td>1–1000 nm</td><td>milk, fog</td></tr><tr><td><strong>Suspension</strong></td><td>&gt; 1000 nm</td><td>muddy water</td></tr></table><p>Solutions are <strong>homogeneous</strong> (uniform); suspensions settle on standing and can be filtered. Colloids scatter light — the <strong>Tyndall effect</strong> (seen in foggy headlight beams).</p>'}],
quiz:[
{q:'Which statement about liquids is correct?', options:['fixed shape and volume','no fixed shape but fixed volume','no fixed shape or volume','particles do not move'], answer:1, explain:'Liquids take the container’s shape but keep a fixed volume.'},
{q:'Plasma is', options:['frozen gas','ionised gas at very high temperature','a liquid metal','solidified air'], answer:1, explain:'Plasma is ionised gas found in stars and lightning.'},
{q:'Water (H₂O) is a', options:['element','compound','mixture','colloid'], answer:1, explain:'Water is hydrogen and oxygen chemically combined in a fixed ratio.'},
{q:'Air is best classified as', options:['compound','element','homogeneous mixture','colloid'], answer:2, explain:'Air is a uniform physical mixture of gases.'},
{q:'Which is an allotrope of carbon?', options:['ozone','graphite','quartz','steel'], answer:1, explain:'Diamond, graphite and fullerene are allotropes of carbon.'},
{q:'Graphite conducts electricity because', options:['it is a metal','it has free electrons between layers','it is hard','it is transparent'], answer:1, explain:'Delocalised electrons between graphite’s layers carry current.'},
{q:'The Tyndall effect is shown by', options:['true solutions','colloids','pure water','suspensions after settling'], answer:1, explain:'Colloid particles scatter a light beam — the Tyndall effect.'},
{q:'Muddy water is a', options:['solution','colloid','suspension','compound'], answer:2, explain:'Mud particles are large, settle on standing and can be filtered.'},
{q:'Particle size in a true solution is', options:['less than 1 nm','1–1000 nm','more than 1000 nm','exactly 1 cm'], answer:0, explain:'True solution particles are smaller than 1 nm (molecular level).'},
{q:'A compound differs from a mixture because it', options:['has variable composition','is formed by a chemical change in fixed ratio','can be separated by filtration','keeps the properties of its parts'], answer:1, explain:'Compounds form by chemical combination in a fixed ratio with new properties.'}]},
{id:'bal-c9-che-ch3', title:'Atomic Structure', urdu:'ایٹم کی ساخت', comingSoon:false, lessons:[
{id:'bal-c9-che-ch3-l1', title:'Subatomic Particles', html:'<h3>Inside the Atom</h3><table><tr><th>Particle</th><th>Charge</th><th>Mass</th><th>Location</th></tr><tr><td><strong>Proton</strong></td><td>+1</td><td>1 amu</td><td>nucleus</td></tr><tr><td><strong>Neutron</strong></td><td>0</td><td>1 amu</td><td>nucleus</td></tr><tr><td><strong>Electron</strong></td><td>−1</td><td>≈ 1/1836 amu</td><td>shells around nucleus</td></tr></table><p>Discovered by: electron — <strong>J.J. Thomson</strong> (cathode rays); proton — <strong>Rutherford</strong>; neutron — <strong>Chadwick</strong>.</p>'},
{id:'bal-c9-che-ch3-l2', title:'Atomic Models', html:'<h3>Models of the Atom</h3><ul><li><strong>Dalton:</strong> atom is an indivisible solid sphere.</li><li><strong>Thomson (plum pudding):</strong> electrons embedded in positive charge.</li><li><strong>Rutherford:</strong> tiny dense positive nucleus with electrons around it (from the gold-foil experiment).</li><li><strong>Bohr:</strong> electrons orbit in fixed energy shells (K, L, M, N) without radiating energy.</li></ul><p>Rutherford’s experiment: most alpha particles passed straight through gold foil — so the atom is mostly empty space.</p>'},
{id:'bal-c9-che-ch3-l3', title:'Isotopes and Electronic Configuration', html:'<h3>Isotopes</h3><p><strong>Isotopes</strong> are atoms of the same element with different numbers of neutrons (e.g. carbon-12, carbon-14). They have the same chemical properties.</p><p><strong>Electronic configuration</strong> — distribution of electrons in shells (capacity 2, 8, 18…): sodium (11) = 2, 8, 1; chlorine (17) = 2, 8, 7. The <strong>atomic number</strong> = number of protons; <strong>mass number</strong> = protons + neutrons.</p>'}],
quiz:[
{q:'The particle with no charge in the nucleus is the', options:['proton','electron','neutron','photon'], answer:2, explain:'The neutron is neutral and sits in the nucleus with protons.'},
{q:'The electron was discovered by', options:['Rutherford','Chadwick','J.J. Thomson','Bohr'], answer:2, explain:'Thomson discovered the electron using cathode rays.'},
{q:'The neutron was discovered by', options:['Dalton','Chadwick','Thomson','Mendeleev'], answer:1, explain:'James Chadwick discovered the neutron in 1932.'},
{q:'Rutherford’s gold-foil experiment showed that', options:['atoms are solid spheres','the atom is mostly empty space with a dense nucleus','electrons are in fixed orbits','atoms cannot be divided'], answer:1, explain:'Most alpha particles passed straight through, so the atom is largely empty.'},
{q:'Bohr’s model states that electrons', options:['are embedded in positive charge','move in fixed energy shells','are in the nucleus','have no energy'], answer:1, explain:'Bohr placed electrons in fixed orbits (K, L, M, N) of definite energy.'},
{q:'Isotopes of an element differ in the number of', options:['protons','electrons','neutrons','shells'], answer:2, explain:'Isotopes have the same protons but different neutrons.'},
{q:'The electronic configuration of sodium (atomic number 11) is', options:['2, 8','2, 8, 1','2, 8, 7','2, 7, 2'], answer:1, explain:'11 electrons fill as 2 in K, 8 in L, 1 in M.'},
{q:'Mass number equals', options:['protons only','neutrons only','protons + neutrons','protons + electrons'], answer:2, explain:'Mass number A = number of protons + number of neutrons.'},
{q:'Carbon-14 has how many neutrons? (atomic number 6)', options:['6','8','12','14'], answer:1, explain:'Neutrons = mass number − atomic number = 14 − 6 = 8.'},
{q:'The nucleus is held together against proton repulsion by the', options:['electromagnetic force','gravitational force','nuclear force','frictional force'], answer:2, explain:'The strong nuclear force binds protons and neutrons in the nucleus.'}]},
{id:'bal-c9-che-ch4', title:'Chemical Bonding', urdu:'کیمیائی بانڈ', comingSoon:false, lessons:[
{id:'bal-c9-che-ch4-l1', title:'Octet Rule and Ion Formation', html:'<h3>Why Atoms Bond</h3><p>Atoms bond to achieve a <strong>stable noble-gas configuration</strong> — usually <strong>8 electrons in the outer shell</strong> (the <strong>octet rule</strong>; hydrogen and helium follow the <strong>duplet rule</strong> of 2).</p><p>Metals <strong>lose</strong> electrons to form positive <strong>cations</strong> (Na → Na⁺); non-metals <strong>gain</strong> electrons to form negative <strong>anions</strong> (Cl → Cl⁻).</p>'},
{id:'bal-c9-che-ch4-l2', title:'Ionic, Covalent and Metallic Bonds', html:'<h3>Types of Bonds</h3><ul><li><strong>Ionic:</strong> transfer of electrons from metal to non-metal (NaCl). Forms crystal lattices; conducts electricity when molten or in solution.</li><li><strong>Covalent:</strong> sharing of electron pairs between non-metals (H₂, CH₄). Can be single, double or triple bonds.</li><li><strong>Metallic:</strong> sea of delocalised electrons around positive ions — explains conductivity and malleability of metals.</li></ul>'},
{id:'bal-c9-che-ch4-l3', title:'Properties of Ionic and Covalent Compounds', html:'<h3>Comparing Compounds</h3><table><tr><th>Property</th><th>Ionic</th><th>Covalent</th></tr><tr><td>Melting/boiling point</td><td>high</td><td>low</td></tr><tr><td>Conductivity</td><td>when molten/in solution</td><td>poor (except graphite)</td></tr><tr><td>Solubility</td><td>in water</td><td>in organic solvents</td></tr><tr><td>State</td><td>crystalline solids</td><td>gases, liquids or soft solids</td></tr></table><p><strong>Polarity:</strong> unequal sharing gives <strong>polar</strong> molecules (H₂O); equal sharing gives <strong>non-polar</strong> (H₂).</p>'}],
quiz:[
{q:'The octet rule states that atoms tend to have', options:['2 electrons total','8 electrons in the outer shell','8 protons','full nucleus'], answer:1, explain:'Atoms bond to complete 8 electrons in their valence shell.'},
{q:'Hydrogen follows the', options:['octet rule','duplet rule','triplet rule','no rule'], answer:1, explain:'Hydrogen is stable with 2 electrons — the duplet rule.'},
{q:'A cation is formed when an atom', options:['gains electrons','loses electrons','gains protons','loses neutrons'], answer:1, explain:'Losing electrons leaves more protons than electrons — a positive ion.'},
{q:'NaCl is an example of', options:['covalent bond','ionic bond','metallic bond','hydrogen bond'], answer:1, explain:'Sodium transfers an electron to chlorine — an ionic bond.'},
{q:'A covalent bond is formed by', options:['transfer of electrons','sharing of electron pairs','sea of electrons','magnetic attraction'], answer:1, explain:'Non-metals share electron pairs to complete their octets.'},
{q:'Metallic bonding is best described as', options:['positive ions in a sea of delocalised electrons','sharing one pair of electrons','transfer of protons','fixed electron pairs'], answer:0, explain:'Delocalised electrons explain metal conductivity and malleability.'},
{q:'Ionic compounds conduct electricity', options:['as solids','when molten or dissolved','never','only as gases'], answer:1, explain:'Ions must be free to move — possible in melt or solution, not in the solid lattice.'},
{q:'Water is a polar molecule because', options:['it is a liquid','oxygen attracts shared electrons more strongly','it has ionic bonds','it is neutral'], answer:1, explain:'Unequal sharing creates partial charges — polarity.'},
{q:'Which has the highest melting point?', options:['methane','sodium chloride','oxygen','wax'], answer:1, explain:'Ionic lattice NaCl has strong electrostatic forces — very high melting point.'},
{q:'Electropositive character means the tendency to', options:['gain electrons','lose electrons','share electrons','repel electrons'], answer:1, explain:'Electropositive elements (metals) readily lose electrons.'}]},
{id:'bal-c9-che-ch5', title:'Stoichiometry', urdu:'اسٹائیکیومیٹری', comingSoon:false, lessons:[
{id:'bal-c9-che-ch5-l1', title:'Chemical Formulae', html:'<h3>Chemical Formula</h3><p>A <strong>chemical formula</strong> shows the elements and their numbers in a compound (H₂O, CO₂, NaCl).</p><ul><li><strong>Empirical formula:</strong> simplest whole-number ratio (CH₂ for C₂H₄).</li><li><strong>Molecular formula:</strong> actual numbers of atoms (C₂H₄).</li></ul><p>Write formulae by the <strong>criss-cross method</strong>: Al³⁺ and O²⁻ → Al₂O₃.</p>'},
{id:'bal-c9-che-ch5-l2', title:'Mole and Avogadro’s Number', html:'<h3>The Mole</h3><p>A <strong>mole</strong> is the chemist’s counting unit: 1 mole = <strong>6.022 × 10²³</strong> particles (<strong>Avogadro’s number</strong>).</p><p><strong>Molar mass</strong> = mass of 1 mole (g/mol): H₂O = 18 g/mol, NaCl = 58.5 g/mol.</p><p>Moles = mass ÷ molar mass. So 36 g of water = 36 ÷ 18 = 2 moles.</p>'},
{id:'bal-c9-che-ch5-l3', title:'Balanced Equations and Calculations', html:'<h3>Chemical Equations</h3><p>Equations must be <strong>balanced</strong> — atoms are conserved: 2H₂ + O₂ → 2H₂O.</p><p><strong>Stoichiometric calculations:</strong> use mole ratios from the balanced equation. Example: 2H₂ + O₂ → 2H₂O — 2 moles of H₂ need 1 mole of O₂ and make 2 moles of water. Always convert masses to moles first, apply the ratio, then convert back.</p>'}],
quiz:[
{q:'The empirical formula of C₂H₄ is', options:['C₂H₄','CH₂','C₄H₈','CH₄'], answer:1, explain:'Simplest whole-number ratio of C₂H₄ is CH₂.'},
{q:'Avogadro’s number is', options:['6.022 × 10²³','3.00 × 10⁸','1.6 × 10⁻¹⁹','9.8'], answer:0, explain:'One mole contains 6.022 × 10²³ particles.'},
{q:'Molar mass of water (H₂O) is', options:['16 g/mol','17 g/mol','18 g/mol','20 g/mol'], answer:2, explain:'2(1) + 16 = 18 g/mol.'},
{q:'36 g of water equals how many moles?', options:['1','2','3','36'], answer:1, explain:'Moles = 36 ÷ 18 = 2.'},
{q:'The formula of aluminium oxide by criss-cross (Al³⁺, O²⁻) is', options:['AlO','Al₂O₃','Al₃O₂','AlO₂'], answer:1, explain:'Crossing the charges: Al₂O₃.'},
{q:'A balanced equation must have', options:['equal molecules both sides','equal atoms of each element both sides','equal volumes','equal masses of each compound'], answer:1, explain:'Atoms are conserved — balancing equalises each element’s atoms.'},
{q:'Balance: H₂ + O₂ → H₂O. The balanced form is', options:['H₂ + O₂ → H₂O','2H₂ + O₂ → 2H₂O','H₂ + 2O₂ → 2H₂O','2H₂ + 2O₂ → 2H₂O'], answer:1, explain:'2H₂ + O₂ → 2H₂O gives 4 H and 2 O on both sides.'},
{q:'In 2H₂ + O₂ → 2H₂O, 4 moles of H₂ produce', options:['2 moles H₂O','4 moles H₂O','8 moles H₂O','1 mole H₂O'], answer:1, explain:'Mole ratio H₂:H₂O is 2:2, so 4 moles H₂ → 4 moles H₂O.'},
{q:'One mole of any gas at STP occupies', options:['1 L','11.2 L','22.4 L','44.8 L'], answer:2, explain:'Molar volume of a gas at STP is 22.4 dm³ (L).'},
{q:'Stoichiometry is the study of', options:['colours of compounds','quantitative relations in chemical reactions','shapes of molecules','smells of gases'], answer:1, explain:'Stoichiometry calculates amounts of reactants and products from balanced equations.'}]},
{id:'bal-c9-che-ch6', title:'Electrochemistry', urdu:'الیکٹرو کیمسٹری', comingSoon:false, lessons:[
{id:'bal-c9-che-ch6-l1', title:'Redox Reactions', html:'<h3>Oxidation and Reduction</h3><ul><li><strong>Oxidation:</strong> loss of electrons (OIL) — also gain of oxygen or loss of hydrogen.</li><li><strong>Reduction:</strong> gain of electrons (RIG) — also loss of oxygen or gain of hydrogen.</li></ul><p>They always occur together (<strong>redox</strong>). The substance oxidised is the <strong>reducing agent</strong>; the substance reduced is the <strong>oxidising agent</strong>. In Zn + Cu²⁺ → Zn²⁺ + Cu, zinc is oxidised (reducing agent).</p>'},
{id:'bal-c9-che-ch6-l2', title:'Oxidation Numbers', html:'<h3>Oxidation Number</h3><p>The <strong>oxidation number</strong> tracks electron control in compounds. Rules: free elements = 0; Group 1 = +1; Group 2 = +2; oxygen usually −2; hydrogen usually +1; sum in a neutral compound = 0.</p><p>Example: in H₂SO₄, 2(+1) + S + 4(−2) = 0 → S = +6. Roman numerals show it: iron(II) means Fe²⁺.</p>'},
{id:'bal-c9-che-ch6-l3', title:'Electrolysis and its Uses', html:'<h3>Electrolysis</h3><p><strong>Electrolysis</strong> uses electricity to split a compound: cations move to the <strong>cathode</strong> (negative), anions to the <strong>anode</strong> (positive). Electrolysing water gives H₂ at the cathode and O₂ at the anode.</p><p><strong>Uses:</strong> <strong>electroplating</strong> (coating iron with chromium/nickel to prevent rust), refining of copper, and extraction of reactive metals like aluminium.</p>'}],
quiz:[
{q:'Oxidation is', options:['gain of electrons','loss of electrons','gain of protons','loss of neutrons'], answer:1, explain:'OIL — Oxidation Is Loss of electrons.'},
{q:'In Zn + Cu²⁺ → Zn²⁺ + Cu, the reducing agent is', options:['Cu²⁺','Zn','Cu','Zn²⁺'], answer:1, explain:'Zinc is oxidised (loses electrons), so it reduces Cu²⁺ — the reducing agent.'},
{q:'The oxidation number of sulphur in H₂SO₄ is', options:['+2','+4','+6','−2'], answer:2, explain:'2(+1) + S + 4(−2) = 0 gives S = +6.'},
{q:'Oxidation number of oxygen is usually', options:['+2','−2','0','+1'], answer:1, explain:'Oxygen is −2 in most compounds (except peroxides and OF₂).'},
{q:'In electrolysis, cations move to the', options:['anode','cathode','battery','salt bridge'], answer:1, explain:'Positive cations are attracted to the negative cathode.'},
{q:'During electrolysis of water, hydrogen is collected at the', options:['anode','cathode','both electrodes','neither'], answer:1, explain:'H⁺ ions gain electrons at the cathode to form H₂.'},
{q:'Electroplating is used to', options:['make alloys','coat metals to prevent corrosion and improve appearance','melt metals','separate isotopes'], answer:1, explain:'A thin layer of chromium or nickel protects iron from rusting.'},
{q:'An oxidising agent', options:['is itself oxidised','is itself reduced','gains mass','loses protons'], answer:1, explain:'It oxidises another substance while being reduced itself.'},
{q:'Iron(II) means iron with oxidation number', options:['+1','+2','+3','−2'], answer:1, explain:'Roman numeral II indicates oxidation state +2 (Fe²⁺).'},
{q:'Which is a redox reaction?', options:['NaCl dissolving','Zn + CuSO₄ → ZnSO₄ + Cu','ice melting','sugar dissolving'], answer:1, explain:'Zinc is oxidised and copper ions reduced — electron transfer occurs.'}]},
{id:'bal-c9-che-ch7', title:'Chemical Energetics', urdu:'کیمیائی توانائیات', comingSoon:false, lessons:[
{id:'bal-c9-che-ch7-l1', title:'System, Surroundings and Energy', html:'<h3>Chemical Systems</h3><p>The <strong>system</strong> is the part under study (the reacting chemicals); the <strong>surroundings</strong> are everything else. An <strong>open system</strong> exchanges matter and energy; a <strong>closed system</strong> exchanges only energy.</p><p><strong>Enthalpy (H)</strong> is the heat content of a system; the <strong>enthalpy change (ΔH)</strong> is the heat absorbed or released in a reaction.</p>'},
{id:'bal-c9-che-ch7-l2', title:'Exothermic and Endothermic Reactions', html:'<h3>Energy Changes</h3><ul><li><strong>Exothermic:</strong> releases heat to surroundings (ΔH negative). Example: burning methane CH₄ + 2O₂ → CO₂ + 2H₂O; the test tube feels hot.</li><li><strong>Endothermic:</strong> absorbs heat from surroundings (ΔH positive). Example: photosynthesis; thermal decomposition of limestone.</li></ul><p>Energy-level diagrams show reactants higher than products for exothermic reactions.</p>'},
{id:'bal-c9-che-ch7-l3', title:'Activation Energy', html:'<h3>Activation Energy</h3><p><strong>Activation energy</strong> is the minimum energy reacting particles need before they can react — the “energy hill” to climb. Even exothermic reactions need it (a match to light a fire).</p><p><strong>Catalysts</strong> speed up reactions by providing an alternative path with <strong>lower</strong> activation energy, without being used up.</p>'}],
quiz:[
{q:'The surroundings in energetics means', options:['the laboratory','everything outside the system','the chemist','the products'], answer:1, explain:'System = chemicals under study; surroundings = everything else.'},
{q:'An exothermic reaction', options:['absorbs heat','releases heat','has ΔH = 0','needs no activation energy'], answer:1, explain:'Exothermic reactions give out heat; ΔH is negative.'},
{q:'Which is an exothermic process?', options:['melting ice','burning methane','photosynthesis','boiling water'], answer:1, explain:'Combustion of methane releases large amounts of heat.'},
{q:'Photosynthesis is', options:['exothermic','endothermic','neutral','explosive'], answer:1, explain:'It absorbs light energy to build glucose — endothermic.'},
{q:'Activation energy is', options:['the total energy released','minimum energy needed to start a reaction','energy of products','heat of the surroundings'], answer:1, explain:'Particles must overcome the activation-energy barrier to react.'},
{q:'A catalyst works by', options:['increasing activation energy','providing a path of lower activation energy','being used up','cooling the mixture'], answer:1, explain:'Catalysts lower the activation-energy barrier and are not consumed.'},
{q:'In an energy diagram for an exothermic reaction, products are', options:['higher than reactants','lower than reactants','at the same level','at zero'], answer:1, explain:'Energy is released, so products sit lower than reactants.'},
{q:'ΔH for an endothermic reaction is', options:['negative','positive','zero','infinite'], answer:1, explain:'Heat is absorbed, so enthalpy change is positive.'},
{q:'A closed system exchanges with surroundings', options:['matter only','energy only','both matter and energy','nothing'], answer:1, explain:'Closed systems exchange energy but not matter.'},
{q:'Burning of natural gas in a stove is an example of', options:['endothermic reaction','exothermic reaction','physical change','nuclear reaction'], answer:1, explain:'Combustion releases heat — exothermic.'}]},
{id:'bal-c9-che-ch8', title:'Chemical Equilibrium', urdu:'کیمیائی توازن', comingSoon:false, lessons:[
{id:'bal-c9-che-ch8-l1', title:'Reversible and Irreversible Reactions', html:'<h3>Types of Reactions</h3><ul><li><strong>Irreversible:</strong> go to completion in one direction (burning paper, →).</li><li><strong>Reversible:</strong> products can reform reactants (⇌). Example: N₂ + 3H₂ ⇌ 2NH₃ (Haber process); heating blue CuSO₄·5H₂O gives white anhydrous salt, and adding water reverses it.</li></ul><p>Reversible reactions in a <strong>closed system</strong> can reach equilibrium.</p>'},
{id:'bal-c9-che-ch8-l2', title:'Dynamic Equilibrium', html:'<h3>Dynamic Equilibrium</h3><p><strong>Dynamic equilibrium</strong> is reached when the <strong>forward and reverse reactions occur at equal rates</strong> — concentrations stay constant, but the reactions have not stopped.</p><p>It is <strong>dynamic</strong> (both reactions continue) and can only exist in a closed system where nothing escapes.</p>'},
{id:'bal-c9-che-ch8-l3', title:'Effect of Conditions — Le Chatelier’s Principle', html:'<h3>Le Chatelier’s Principle</h3><p>If a change is applied to a system at equilibrium, the system shifts to <strong>oppose the change</strong>.</p><ul><li><strong>Concentration:</strong> adding reactant shifts right.</li><li><strong>Pressure:</strong> increasing pressure shifts toward fewer gas molecules.</li><li><strong>Temperature:</strong> increasing temperature shifts toward the endothermic direction.</li></ul><p>Haber process uses high pressure (fewer gas moles on the product side) and moderate temperature to maximise ammonia.</p>'}],
quiz:[
{q:'A reversible reaction is shown by', options:['→','⇌','=','⇒'], answer:1, explain:'The double half-arrow ⇌ denotes reversibility.'},
{q:'Dynamic equilibrium means', options:['reactions have stopped','forward and reverse rates are equal','only forward reaction occurs','concentrations are zero'], answer:1, explain:'Both reactions continue at equal rates; concentrations stay constant.'},
{q:'Equilibrium can only be reached in a', options:['open system','closed system','hot system','large system'], answer:1, explain:'Reactants and products must not escape — a closed system.'},
{q:'According to Le Chatelier, increasing pressure shifts equilibrium toward', options:['more gas molecules','fewer gas molecules','no change','higher temperature'], answer:1, explain:'The system opposes pressure rise by reducing gas molecules.'},
{q:'In N₂ + 3H₂ ⇌ 2NH₃, 4 gas moles become 2. High pressure', options:['reduces ammonia','favours ammonia formation','has no effect','stops the reaction'], answer:1, explain:'Fewer product gas moles, so high pressure shifts right toward NH₃.'},
{q:'Raising temperature favours the', options:['exothermic direction','endothermic direction','forward direction always','reverse direction always'], answer:1, explain:'The system absorbs the added heat by shifting endothermically.'},
{q:'Which is a reversible change?', options:['burning wood','heating hydrated copper sulphate','frying an egg','rusting'], answer:1, explain:'Blue CuSO₄·5H₂O ⇄ white CuSO₄ + water is reversible.'},
{q:'A catalyst affects equilibrium by', options:['shifting it right','shifting it left','reaching it faster, position unchanged','destroying products'], answer:2, explain:'Catalysts speed both directions equally; equilibrium position is unchanged.'},
{q:'At equilibrium, the concentrations of reactants and products', options:['are equal','are zero','remain constant','keep changing'], answer:2, explain:'Constant (not necessarily equal) concentrations mark equilibrium.'},
{q:'Adding more reactant to an equilibrium mixture', options:['shifts left','shifts right','does nothing','precipitates'], answer:1, explain:'The system uses up added reactant by shifting toward products.'}]}
,
{id:'bal-c9-che-ch9', title:'Acids and Bases', urdu:'تیزاب اور اساس', comingSoon:false, lessons:[
{id:'bal-c9-che-ch9-l1', title:'Concepts of Acids and Bases', html:'<h3>Acids and Bases</h3><ul><li><strong>Arrhenius:</strong> acid gives H⁺ in water; base gives OH⁻ in water.</li><li><strong>Brønsted–Lowry:</strong> acid is a <strong>proton (H⁺) donor</strong>; base is a <strong>proton acceptor</strong>.</li></ul><p>Example: HCl + H₂O → H₃O⁺ + Cl⁻ — HCl donates a proton (acid); H₂O accepts it (base). The pair HCl/Cl⁻ is a <strong>conjugate acid–base pair</strong>.</p>'},
{id:'bal-c9-che-ch9-l2', title:'Properties and the pH Scale', html:'<h3>Properties</h3><table><tr><th>Acids</th><th>Bases</th></tr><tr><td>sour taste</td><td>bitter taste, soapy feel</td></tr><tr><td>turn blue litmus red</td><td>turn red litmus blue</td></tr><tr><td>react with metals giving H₂</td><td>react with acids (neutralisation)</td></tr></table><p><strong>pH scale</strong> (0–14): below 7 acidic, 7 neutral, above 7 basic. <strong>Strong</strong> acids/bases ionise completely (HCl, NaOH); <strong>weak</strong> ones partially (CH₃COOH, NH₃).</p>'},
{id:'bal-c9-che-ch9-l3', title:'Uses and Neutralisation', html:'<h3>Neutralisation and Uses</h3><p><strong>Neutralisation:</strong> acid + base → salt + water. Example: HCl + NaOH → NaCl + H₂O. Farmers add lime (base) to neutralise acidic soil.</p><p><strong>Uses:</strong> sulphuric acid in car batteries and fertilisers; hydrochloric acid cleans steel; citric acid in foods; sodium hydroxide in soap; ammonia in cleaners.</p>'}],
quiz:[
{q:'According to Brønsted–Lowry, an acid is a', options:['proton acceptor','proton donor','electron donor','hydroxide donor'], answer:1, explain:'Brønsted–Lowry acids donate H⁺ (protons).'},
{q:'In HCl + H₂O → H₃O⁺ + Cl⁻, the base is', options:['HCl','H₂O','H₃O⁺','Cl⁻'], answer:1, explain:'Water accepts the proton, so it acts as the base.'},
{q:'The conjugate base of HCl is', options:['H₂Cl⁺','Cl⁻','H₃O⁺','NaCl'], answer:1, explain:'Removing H⁺ from HCl leaves Cl⁻ — its conjugate base.'},
{q:'Blue litmus turns red in', options:['a base','an acid','a salt solution','pure water'], answer:1, explain:'Acids turn blue litmus paper red.'},
{q:'A solution with pH 3 is', options:['basic','neutral','acidic','a salt'], answer:2, explain:'pH below 7 is acidic.'},
{q:'Which is a strong base?', options:['ammonia','sodium hydroxide','acetic acid','water'], answer:1, explain:'NaOH ionises completely in water — a strong base.'},
{q:'Neutralisation produces', options:['acid + water','salt + water','base + gas','salt + hydrogen'], answer:1, explain:'Acid + base → salt + water.'},
{q:'Farmers add lime to soil to', options:['make it acidic','neutralise excess acidity','add water','kill plants'], answer:1, explain:'Lime (a base) neutralises acidic soil for better crops.'},
{q:'Sulphuric acid is used in', options:['car batteries','cooking','drinking water','perfumes'], answer:0, explain:'Dilute sulphuric acid is the electrolyte in lead-acid car batteries.'},
{q:'Acids react with active metals to give', options:['oxygen','hydrogen gas','carbon dioxide','chlorine'], answer:1, explain:'Metal + acid → salt + hydrogen, e.g. Zn + 2HCl → ZnCl₂ + H₂.'}]},
{id:'bal-c9-che-ch10', title:'Periodic Table and Group Properties', urdu:'پیریاڈک ٹیبل اور گروہی خصوصیات', comingSoon:false, lessons:[
{id:'bal-c9-che-ch10-l1', title:'Groups, Periods and Blocks', html:'<h3>Modern Periodic Table</h3><p>Elements are arranged by <strong>increasing atomic number</strong>. <strong>Groups</strong> (1–18) are vertical columns with similar properties; <strong>periods</strong> (1–7) are horizontal rows.</p><p><strong>Blocks:</strong> s-block (groups 1–2), p-block (13–18), d-block (transition metals), f-block (lanthanides/actinides below the table).</p>'},
{id:'bal-c9-che-ch10-l2', title:'Periodic Trends', html:'<h3>Trends in the Table</h3><ul><li><strong>Atomic size:</strong> decreases across a period, increases down a group.</li><li><strong>Ionisation energy:</strong> increases across a period, decreases down a group.</li><li><strong>Electronegativity:</strong> increases across a period, decreases down a group.</li><li><strong>Metallic character:</strong> decreases across a period, increases down a group.</li></ul>'},
{id:'bal-c9-che-ch10-l3', title:'Group Properties', html:'<h3>Important Groups</h3><ul><li><strong>Group 1 (alkali metals):</strong> soft, very reactive; reactivity increases down the group (Li &lt; Na &lt; K).</li><li><strong>Group 17 (halogens):</strong> reactive non-metals; reactivity decreases down the group.</li><li><strong>Group 18 (noble gases):</strong> inert — full outer shells.</li><li><strong>Transition metals:</strong> coloured compounds, good catalysts (iron in Haber process).</li></ul>'}],
quiz:[
{q:'Modern periodic table arranges elements by', options:['atomic mass','atomic number','density','discovery date'], answer:1, explain:'The modern law orders elements by increasing atomic number.'},
{q:'Elements in the same group have similar', options:['masses','chemical properties','colours','densities'], answer:1, explain:'Same outer-shell electron arrangement gives similar chemistry.'},
{q:'The d-block contains', options:['alkali metals','halogens','transition metals','noble gases'], answer:2, explain:'The d-block (groups 3–12) holds the transition metals.'},
{q:'Atomic size across a period (left to right)', options:['increases','decreases','stays same','doubles'], answer:1, explain:'Greater nuclear pull draws shells closer across a period.'},
{q:'Ionisation energy down a group', options:['increases','decreases','stays same','becomes zero'], answer:1, explain:'Outer electrons are farther and more shielded, so easier to remove.'},
{q:'The most electronegative element is', options:['sodium','chlorine','fluorine','oxygen'], answer:2, explain:'Fluorine tops the electronegativity scale.'},
{q:'Reactivity of alkali metals down the group', options:['decreases','increases','stays same','becomes zero'], answer:1, explain:'Larger atoms lose the outer electron more easily.'},
{q:'Noble gases are inert because they', options:['are heavy','have full outer shells','are gases','are rare'], answer:1, explain:'Complete octets make them reluctant to gain, lose or share electrons.'},
{q:'Halogens are in group', options:['1','2','17','18'], answer:2, explain:'Group 17 elements (F, Cl, Br, I) are the halogens.'},
{q:'Transition metals are good catalysts because of', options:['low density','variable oxidation states and surface area','bright colours','magnetism'], answer:1, explain:'Variable oxidation states let them provide alternative reaction paths.'}]},
{id:'bal-c9-che-ch11', title:'Environmental Chemistry', urdu:'ماحولیاتی کیمسٹری', comingSoon:false, lessons:[
{id:'bal-c9-che-ch11-l1', title:'Composition of the Atmosphere', html:'<h3>Our Atmosphere</h3><p>Air is about <strong>78% nitrogen, 21% oxygen, 0.04% carbon dioxide</strong>, plus argon, water vapour and traces of other gases.</p><p>The <strong>ozone layer</strong> (in the stratosphere) absorbs harmful ultraviolet (UV) radiation from the Sun, protecting life.</p>'},
{id:'bal-c9-che-ch11-l2', title:'Air Pollutants', html:'<h3>Major Air Pollutants</h3><ul><li><strong>Carbon monoxide (CO):</strong> poisonous; from incomplete fuel burning.</li><li><strong>Sulphur dioxide (SO₂) and nitrogen oxides (NOₓ):</strong> cause <strong>acid rain</strong> and smog.</li><li><strong>CFCs:</strong> destroy the ozone layer.</li><li><strong>Particulates/smoke:</strong> cause respiratory problems and smog.</li></ul>'},
{id:'bal-c9-che-ch11-l3', title:'Greenhouse Effect and Global Warming', html:'<h3>Greenhouse Effect</h3><p><strong>Greenhouse gases</strong> (CO₂, methane, water vapour) trap heat radiated from Earth — necessary for a warm planet, but excess causes <strong>global warming</strong>.</p><p><strong>Acid rain</strong> (pH &lt; 5.6) damages buildings, crops and aquatic life. Solutions: cleaner fuels, filters on chimneys, catalytic converters, planting trees and reducing CFC use.</p>'}],
quiz:[
{q:'Nitrogen makes up about what percentage of air?', options:['21%','50%','78%','1%'], answer:2, explain:'Air is roughly 78% nitrogen and 21% oxygen.'},
{q:'The ozone layer protects us from', options:['acid rain','ultraviolet radiation','noise','floods'], answer:1, explain:'Ozone absorbs harmful UV rays from the Sun.'},
{q:'Carbon monoxide is dangerous because it', options:['smells bad','binds haemoglobin, blocking oxygen transport','causes acid rain','destroys ozone'], answer:1, explain:'CO binds haemoglobin far more strongly than oxygen does.'},
{q:'Acid rain is mainly caused by', options:['CO₂ only','SO₂ and NOₓ','oxygen','nitrogen'], answer:1, explain:'Sulphur and nitrogen oxides dissolve in rain to form acids.'},
{q:'CFCs damage the', options:['ozone layer','water table','soil','crops directly'], answer:0, explain:'Chlorofluorocarbons break down ozone molecules.'},
{q:'Which is a greenhouse gas?', options:['oxygen','nitrogen','carbon dioxide','hydrogen'], answer:2, explain:'CO₂ traps outgoing heat radiation, warming the planet.'},
{q:'Acid rain has pH', options:['above 7','equal to 7','below 5.6','exactly 5.6'], answer:2, explain:'Rain below pH 5.6 is considered acid rain.'},
{q:'A catalytic converter in cars reduces', options:['fuel use','harmful exhaust gases','engine noise','speed'], answer:1, explain:'It converts CO, NOₓ and unburnt fuel into less harmful gases.'},
{q:'Global warming is mainly driven by excess', options:['oxygen','greenhouse gases','nitrogen','helium'], answer:1, explain:'Extra CO₂ and methane trap more heat than normal.'},
{q:'Planting trees helps the environment because trees', options:['produce oxygen only','absorb CO₂ during photosynthesis','make soil acidic','block wind'], answer:1, explain:'Trees remove carbon dioxide, a key greenhouse gas.'}]},
{id:'bal-c9-che-ch12', title:'Organic Chemistry', urdu:'نامیاتی کیمسٹری', comingSoon:false, lessons:[
{id:'bal-c9-che-ch12-l1', title:'Organic Compounds', html:'<h3>Organic Chemistry</h3><p><strong>Organic compounds</strong> contain carbon (with hydrogen), forming the basis of fuels, plastics, medicines and life itself. Carbon’s ability to form <strong>four covalent bonds</strong> and long chains (<strong>catenation</strong>) creates millions of compounds.</p><p><strong>Structural formula</strong> shows how atoms are arranged, e.g. methane CH₄ as C with four H atoms around it.</p>'},
{id:'bal-c9-che-ch12-l2', title:'Saturated and Unsaturated Hydrocarbons', html:'<h3>Hydrocarbons</h3><ul><li><strong>Alkanes</strong> (saturated): single bonds only, e.g. methane CH₄, ethane C₂H₆. General formula CₙH₂ₙ₊₂.</li><li><strong>Alkenes</strong> (unsaturated): contain C=C double bond, e.g. ethene C₂H₄. CₙH₂ₙ.</li><li><strong>Alkynes</strong>: contain C≡C triple bond, e.g. ethyne C₂H₂. CₙH₂ₙ₋₂.</li></ul><p>A <strong>homologous series</strong> is a family differing by CH₂, with similar chemical properties (e.g. all alkanes).</p>'},
{id:'bal-c9-che-ch12-l3', title:'Functional Groups', html:'<h3>Functional Groups</h3><p>The <strong>functional group</strong> is the reactive part of a molecule that decides its chemistry:</p><table><tr><th>Group</th><th>Formula</th><th>Family</th></tr><tr><td>Hydroxyl</td><td>–OH</td><td>alcohols</td></tr><tr><td>Carboxyl</td><td>–COOH</td><td>carboxylic acids</td></tr><tr><td>Carbonyl</td><td>–CHO / &gt;C=O</td><td>aldehydes/ketones</td></tr><tr><td>Amino</td><td>–NH₂</td><td>amines</td></tr></table>'}],
quiz:[
{q:'Organic compounds must contain', options:['oxygen','carbon','nitrogen','sulphur'], answer:1, explain:'Organic chemistry is the chemistry of carbon compounds.'},
{q:'Carbon forms four bonds because it has', options:['4 protons','4 valence electrons','4 neutrons','4 shells'], answer:1, explain:'With 4 outer electrons, carbon forms 4 covalent bonds.'},
{q:'Catenation is the ability of carbon to', options:['form ionic bonds','form long chains with itself','dissolve in water','conduct electricity'], answer:1, explain:'Catenation — self-linking into chains and rings — creates huge variety.'},
{q:'The general formula of alkanes is', options:['CₙH₂ₙ','CₙH₂ₙ₊₂','CₙH₂ₙ₋₂','CₙHₙ'], answer:1, explain:'Alkanes follow CₙH₂ₙ₊₂ (e.g. CH₄, C₂H₆).'},
{q:'Ethene (C₂H₄) is an', options:['alkane','alkene','alkyne','alcohol'], answer:1, explain:'C₂H₄ has a C=C double bond — an alkene.'},
{q:'A homologous series differs by', options:['CH₄','CH₂','H₂','O'], answer:1, explain:'Successive members differ by a CH₂ unit.'},
{q:'The functional group –COOH belongs to', options:['alcohols','carboxylic acids','amines','alkanes'], answer:1, explain:'–COOH is the carboxyl group of carboxylic acids like vinegar.'},
{q:'The –OH group is found in', options:['alkanes','alcohols','acids','alkenes'], answer:1, explain:'Hydroxyl (–OH) defines the alcohol family.'},
{q:'Methane’s structural formula shows', options:['C with 4 H atoms bonded','C with 2 O atoms','4 C atoms in a ring','ionic bonds'], answer:0, explain:'CH₄: carbon bonded to four hydrogen atoms.'},
{q:'Unsaturated hydrocarbons contain', options:['only single bonds','double or triple bonds','ionic bonds','no carbon'], answer:1, explain:'Multiple bonds make them unsaturated (fewer hydrogens).'}]},
{id:'bal-c9-che-ch13', title:'Biochemistry', urdu:'بائیو کیمسٹری', comingSoon:false, lessons:[
{id:'bal-c9-che-ch13-l1', title:'Carbohydrates', html:'<h3>Carbohydrates</h3><p><strong>Carbohydrates</strong> are the body’s main <strong>energy source</strong> (4 kcal/g). Made of C, H and O.</p><ul><li><strong>Monosaccharides:</strong> glucose, fructose (single sugars).</li><li><strong>Disaccharides:</strong> sucrose (glucose + fructose), maltose.</li><li><strong>Polysaccharides:</strong> starch (plants store energy), glycogen (animals store energy), cellulose (plant cell walls).</li></ul>'},
{id:'bal-c9-che-ch13-l2', title:'Proteins and Lipids', html:'<h3>Proteins</h3><p><strong>Proteins</strong> are built from <strong>amino acids</strong> — needed for growth, repair, enzymes and hormones. Sources: meat, eggs, pulses, milk.</p><h3>Lipids</h3><p><strong>Lipids</strong> (fats and oils) give <strong>concentrated energy</strong> (9 kcal/g), insulate the body and carry vitamins A, D, E, K. Saturated fats (ghee) are solid; unsaturated (oils) are liquid.</p>'},
{id:'bal-c9-che-ch13-l3', title:'Nucleic Acids, Vitamins and Balanced Diet', html:'<h3>Nucleic Acids</h3><p><strong>DNA</strong> (double helix) stores hereditary information; <strong>RNA</strong> helps build proteins. Both are made of nucleotides.</p><p><strong>Recommended daily intake:</strong> a balanced diet needs carbohydrates (~55–60%), proteins, fats, plus <strong>vitamins</strong> (e.g. C for immunity, D for bones) and <strong>minerals</strong> (iron, calcium) in small amounts, with plenty of water and fibre.</p>'}],
quiz:[
{q:'The body’s main quick energy source is', options:['proteins','carbohydrates','vitamins','water'], answer:1, explain:'Carbohydrates are broken down to glucose for energy.'},
{q:'Sucrose is made of', options:['two glucose units','glucose + fructose','two fructose units','glucose + galactose only'], answer:1, explain:'Table sugar (sucrose) = glucose + fructose.'},
{q:'Plants store energy as', options:['glycogen','starch','cellulose','sucrose only'], answer:1, explain:'Starch is the storage polysaccharide in plants.'},
{q:'Proteins are made of', options:['fatty acids','amino acids','glucose units','nucleotides'], answer:1, explain:'Amino acids link to form proteins.'},
{q:'One gram of fat gives about', options:['4 kcal','9 kcal','2 kcal','12 kcal'], answer:1, explain:'Fats provide ~9 kcal/g — more than double carbohydrates.'},
{q:'DNA is shaped like a', options:['single strand','double helix','flat sheet','ring'], answer:1, explain:'DNA’s double-helix stores genetic information.'},
{q:'RNA’s main role is to', options:['store fat','help build proteins','carry oxygen','digest food'], answer:1, explain:'RNA carries instructions from DNA to make proteins.'},
{q:'Vitamin D is needed for', options:['vision','strong bones','blood clotting','immunity'], answer:1, explain:'Vitamin D helps absorb calcium for bones and teeth.'},
{q:'Which vitamin prevents scurvy?', options:['vitamin A','vitamin C','vitamin D','vitamin K'], answer:1, explain:'Vitamin C (citrus fruits) prevents scurvy.'},
{q:'Cellulose is important in diet as', options:['energy','fibre','protein','fat'], answer:1, explain:'Humans cannot digest cellulose; it acts as dietary fibre.'}]},
{id:'bal-c9-che-ch14', title:'Empirical Data Collection and Analysis', urdu:'تجرباتی ڈیٹا کا حصول و تجزیہ', comingSoon:false, lessons:[
{id:'bal-c9-che-ch14-l1', title:'Standard Units and SI', html:'<h3>Why Standard Units?</h3><p>Science needs <strong>standard units</strong> so measurements agree worldwide. The <strong>SI system</strong> gives base units: metre (length), kilogram (mass), second (time), kelvin (temperature), mole (amount).</p><p><strong>Practical units</strong> in the lab: chemists use <strong>cm³</strong> for small volumes, <strong>g</strong> for small masses and <strong>s</strong> for time — convenient sizes for bench work.</p>'},
{id:'bal-c9-che-ch14-l2', title:'Combining Units with Magnitudes', html:'<h3>Units and Magnitude Terms</h3><p>Combine units with <strong>prefixes</strong>: 1 km = 1000 m; 1 mg = 10⁻³ g; 1 µs = 10⁻⁶ s. Always convert to consistent units before calculating.</p><p><strong>Derived units:</strong> density = g/cm³, concentration = mol/dm³, pressure = Pa. Writing the unit with every number prevents costly mistakes.</p>'},
{id:'bal-c9-che-ch14-l3', title:'Accuracy and Precision in the Lab', html:'<h3>Tools for Accuracy</h3><ul><li>Use a <strong>burette</strong> (±0.05 cm³) not a measuring cylinder for titrations.</li><li>Weigh with an <strong>electronic balance</strong> (±0.01 g).</li><li>Repeat readings and take the <strong>mean</strong> to reduce random error.</li><li>Record to the instrument’s precision — never invent extra digits.</li></ul><p><strong>Accuracy</strong> = closeness to the true value; <strong>precision</strong> = closeness of repeats to each other.</p>'}],
quiz:[
{q:'The SI unit of amount of substance is', options:['gram','mole','litre','kilogram'], answer:1, explain:'Amount of substance is measured in moles.'},
{q:'A practical lab unit for small volumes is', options:['m³','cm³','km³','mm'], answer:1, explain:'cm³ is the convenient bench unit for small volumes.'},
{q:'1 mg equals', options:['10⁻³ g','10³ g','10⁻⁶ g','1 g'], answer:0, explain:'Milli (m) = 10⁻³.'},
{q:'The unit of concentration mol/dm³ is a', options:['base unit','derived unit','prefix','constant'], answer:1, explain:'It combines mole and volume units — derived.'},
{q:'For accurate titration volumes, use a', options:['measuring cylinder','burette','beaker','conical flask'], answer:1, explain:'A burette reads to ±0.05 cm³ — far more precise.'},
{q:'Repeating readings and averaging reduces', options:['systematic error','random error','human bias fully','cost'], answer:1, explain:'Random errors cancel out when averaged.'},
{q:'Precision means', options:['closeness to true value','closeness of repeated readings to each other','large instruments','expensive equipment'], answer:1, explain:'Precision is repeatability; accuracy is closeness to truth.'},
{q:'An electronic balance typically reads to', options:['±1 g','±0.01 g','±1 kg','±0.000001 g'], answer:1, explain:'School lab balances read to 0.01 g.'},
{q:'Which is a base SI unit?', options:['newton','joule','kelvin','pascal'], answer:2, explain:'Kelvin (temperature) is a base unit; the others are derived.'},
{q:'Recording more digits than the instrument allows is', options:['good practice','false precision','required','harmless'], answer:1, explain:'Reported digits must match the instrument’s real precision.'}]},
{id:'bal-c9-che-ch15', title:'Separation Techniques', urdu:'علیحدگی کی تکنیکیں', comingSoon:false, lessons:[
{id:'bal-c9-che-ch15-l1', title:'Basic Terms: Solution Vocabulary', html:'<h3>Solution Terms</h3><ul><li><strong>Solute</strong> — dissolved substance (salt); <strong>solvent</strong> — dissolves it (water).</li><li><strong>Saturated solution</strong> — holds maximum dissolved solute at that temperature.</li><li><strong>Filtrate</strong> — liquid passing through filter; <strong>residue</strong> — solid left behind.</li><li><strong>Pure substance</strong> — single substance with sharp melting/boiling point.</li></ul>'},
{id:'bal-c9-che-ch15-l2', title:'Common Separation Methods', html:'<h3>Separation and Purification</h3><ul><li><strong>Filtration</strong> — separates insoluble solid from liquid (sand from water).</li><li><strong>Evaporation/Crystallisation</strong> — gets dissolved solid back (salt from seawater).</li><li><strong>Distillation</strong> — separates liquids by boiling point (water from salt solution).</li><li><strong>Fractional distillation</strong> — separates miscible liquids (petroleum refining).</li><li><strong>Sublimation</strong> — for solids that turn directly to vapour (naphthalene, ammonium chloride).</li></ul>'},
{id:'bal-c9-che-ch15-l3', title:'Testing Purity', html:'<h3>Assessing Purity</h3><p><strong>Melting and boiling points</strong> test purity: a <strong>pure substance</strong> melts/boils sharply at a fixed temperature; impurities <strong>lower the melting point</strong> and widen the range.</p><p>Pure water boils at exactly 100 °C; salty water boils higher and over a range.</p>'}],
quiz:[
{q:'In a salt solution, the solute is', options:['water','salt','the beaker','air'], answer:1, explain:'Solute = dissolved substance (salt); solvent = water.'},
{q:'A saturated solution', options:['has no solute','holds the maximum dissolved solute','is always hot','cannot be stirred'], answer:1, explain:'At saturation, no more solute can dissolve at that temperature.'},
{q:'Filtration separates', options:['two liquids','an insoluble solid from a liquid','dissolved salt from water','gases'], answer:1, explain:'The filter holds back solid residue; liquid filtrate passes through.'},
{q:'Salt is recovered from seawater by', options:['filtration','evaporation/crystallisation','distillation','sublimation'], answer:1, explain:'Evaporating water leaves salt crystals behind.'},
{q:'Fractional distillation is used in', options:['making salt','petroleum refining','filtering mud','freezing water'], answer:1, explain:'It separates miscible liquids with close boiling points, like crude oil fractions.'},
{q:'Which solid can be purified by sublimation?', options:['salt','naphthalene','sand','sugar'], answer:1, explain:'Naphthalene sublimes — turns directly from solid to vapour.'},
{q:'A pure substance has', options:['a range of melting points','a sharp fixed melting point','no melting point','variable colour'], answer:1, explain:'Purity shows as a sharp, fixed melting/boiling point.'},
{q:'Impurities in a solid cause its melting point to', options:['rise sharply','lower and spread over a range','stay exactly the same','disappear'], answer:1, explain:'Impurities depress and broaden the melting point.'},
{q:'The liquid passing through filter paper is the', options:['residue','filtrate','solute','solvent'], answer:1, explain:'Filtrate passes through; residue stays on the paper.'},
{q:'To get pure water from salty water, use', options:['filtration','simple distillation','decanting','sieving'], answer:1, explain:'Distillation boils water off and condenses pure vapour.'}]},
{id:'bal-c9-che-ch16', title:'Qualitative Analysis', urdu:'معیاری تجزیہ', comingSoon:false, lessons:[
{id:'bal-c9-che-ch16-l1', title:'Tests for Gases', html:'<h3>Identifying Gases</h3><ul><li><strong>Hydrogen:</strong> squeaky pop with a lit splint.</li><li><strong>Oxygen:</strong> relights a glowing splint.</li><li><strong>Carbon dioxide:</strong> turns limewater milky.</li><li><strong>Chlorine:</strong> bleaches damp litmus paper.</li><li><strong>Ammonia:</strong> turns damp red litmus blue; dense white fumes with HCl.</li></ul>'},
{id:'bal-c9-che-ch16-l2', title:'Flame Test', html:'<h3>Flame Test for Metal Ions</h3><p>Heat a clean wire dipped in the sample in a blue flame and observe the colour:</p><table><tr><th>Ion</th><th>Flame colour</th></tr><tr><td>Sodium (Na⁺)</td><td>golden yellow</td></tr><tr><td>Potassium (K⁺)</td><td>lilac</td></tr><tr><td>Calcium (Ca²⁺)</td><td>brick red</td></tr><tr><td>Copper (Cu²⁺)</td><td>blue-green</td></tr></table>'},
{id:'bal-c9-che-ch16-l3', title:'Paper Chromatography', html:'<h3>Chromatography</h3><p><strong>Paper chromatography</strong> separates mixtures of soluble substances (e.g. ink dyes). Spots are placed on a pencil baseline; solvent rises, carrying components at different speeds.</p><p><strong>Rf value</strong> = distance moved by substance ÷ distance moved by solvent. Each substance has a characteristic Rf, used to <strong>identify</strong> it by comparison with known samples.</p>'}],
quiz:[
{q:'Hydrogen is tested with', options:['a glowing splint','a lit splint — squeaky pop','limewater','litmus'], answer:1, explain:'H₂ burns with a squeaky pop.'},
{q:'Oxygen is identified by', options:['squeaky pop','relighting a glowing splint','milky limewater','blue litmus'], answer:1, explain:'O₂ relights a glowing splint.'},
{q:'Carbon dioxide turns limewater', options:['blue','milky','red','green'], answer:1, explain:'CO₂ forms white calcium carbonate — milky limewater.'},
{q:'In the flame test, sodium gives', options:['lilac','golden yellow','brick red','blue-green'], answer:1, explain:'Na⁺ gives a strong golden-yellow flame.'},
{q:'Potassium gives a', options:['golden yellow','lilac','brick red','green'], answer:1, explain:'K⁺ gives a lilac (pale purple) flame.'},
{q:'Calcium ions give a', options:['lilac flame','brick-red flame','yellow flame','no colour'], answer:1, explain:'Ca²⁺ gives a brick-red flame colour.'},
{q:'Rf value equals', options:['solvent distance ÷ spot distance','spot distance ÷ solvent distance','spot × solvent distance','solvent − spot'], answer:1, explain:'Rf = distance moved by substance ÷ distance moved by solvent.'},
{q:'Chromatography separates mixtures based on', options:['density','different speeds of components in a solvent','melting point','magnetism'], answer:1, explain:'Components travel at different rates and separate into spots.'},
{q:'Ammonia turns damp red litmus', options:['blue','white','green','colourless'], answer:0, explain:'NH₃ is basic — turns red litmus blue.'},
{q:'Qualitative analysis determines', options:['how much substance is present','what substances are present','the temperature','the mass'], answer:1, explain:'Qualitative = identity; quantitative = amount.'}]}
]});
/* ================= BALOCHISTAN BOARD — CLASS 9 BIOLOGY ================= */
window.__saMergeCourse({id:'bal-class9-biology', board:'balochistan', title:'Biology', urdu:'حیاتیات', class:'Class 9', icon:'🧬', desc:'Balochistan Board Class 9 Biology — full syllabus with lessons and quizzes.', chapters:[
{id:'bal-c9-bio-ch1', title:'Nature of Science in Biology', urdu:'حیاتیات میں سائنس کی نوعیت', comingSoon:false, lessons:[
{id:'bal-c9-bio-ch1-l1', title:'What is Biology?', html:'<h3>Definition of Biology</h3><p><strong>Biology</strong> is the scientific study of life and living organisms — their structure, function, growth and evolution. The word comes from Greek <em>bios</em> (life) and <em>logos</em> (study).</p><p>The Holy Quran repeatedly invites humans to observe living things — camels, birds, plants and their own creation — as signs (Ayat) of Allah, making the study of life both a scientific and spiritual pursuit.</p>'},
{id:'bal-c9-bio-ch1-l2', title:'Major Fields and Branches of Biology', html:'<h3>Branches of Biology</h3><ul><li><strong>Zoology</strong> — animals; <strong>Botany</strong> — plants; <strong>Microbiology</strong> — microbes.</li><li><strong>Genetics</strong> — heredity; <strong>Ecology</strong> — organisms and environment.</li><li><strong>Anatomy</strong> — structure; <strong>Physiology</strong> — function.</li><li><strong>Cell biology, Molecular biology, Biotechnology, Marine biology, Entomology</strong> (insects).</li></ul>'},
{id:'bal-c9-bio-ch1-l3', title:'Biology, Other Sciences and Careers', html:'<h3>Biology and Other Sciences</h3><p>Biology links with <strong>chemistry</strong> (biochemistry), <strong>physics</strong> (biophysics), <strong>geography</strong> (biogeography) and <strong>mathematics</strong> (biostatistics).</p><p><strong>Careers:</strong> doctor, veterinarian, pharmacist, agriculturist, environmentalist, researcher, teacher. Biology solves real problems — new crops, medicines and disease control.</p>'}],
quiz:[
{q:'Biology is the study of', options:['rocks','living organisms','chemicals','stars'], answer:1, explain:'Biology (bios = life, logos = study) studies life.'},
{q:'The study of insects is called', options:['ornithology','entomology','ichthyology','herpetology'], answer:1, explain:'Entomology is the branch studying insects.'},
{q:'Genetics deals with', options:['fossils','heredity and variation','animal behaviour','plant diseases'], answer:1, explain:'Genetics studies how traits pass from parents to offspring.'},
{q:'The branch studying the function of body parts is', options:['anatomy','physiology','morphology','taxonomy'], answer:1, explain:'Physiology = function; anatomy = structure.'},
{q:'Biochemistry is the link between biology and', options:['physics','chemistry','mathematics','history'], answer:1, explain:'Biochemistry applies chemistry to living systems.'},
{q:'Which is a career in biology?', options:['accountant','veterinarian','pilot','judge'], answer:1, explain:'Veterinarians treat animals — an applied biology career.'},
{q:'Ecology studies', options:['cells','organisms and their environment','genes','fossils'], answer:1, explain:'Ecology examines interactions between organisms and surroundings.'},
{q:'Botany is the study of', options:['animals','plants','microbes','humans'], answer:1, explain:'Botany deals with plant life.'},
{q:'The Quran encourages the study of life by inviting observation of', options:['only humans','camels, birds, plants and creation','stars only','angels'], answer:1, explain:'Many verses point to living things as signs (Ayat) for reflection.'},
{q:'Marine biology studies', options:['desert animals','ocean life','birds','insects'], answer:1, explain:'Marine biology covers life in seas and oceans.'}]},
{id:'bal-c9-bio-ch2', title:'Molecular Biology', urdu:'سالماتی حیاتیات', comingSoon:false, lessons:[
{id:'bal-c9-bio-ch2-l1', title:'Biochemistry and Biomolecules', html:'<h3>Biochemistry</h3><p><strong>Biochemistry</strong> studies the chemical substances in living things. The main <strong>biomolecules</strong> are <strong>carbohydrates, proteins, lipids and nucleic acids</strong> — all built mostly from carbon, hydrogen, oxygen, nitrogen and phosphorus.</p>'},
{id:'bal-c9-bio-ch2-l2', title:'Carbohydrates and Lipids', html:'<h3>Carbohydrates</h3><p>Quick <strong>energy source</strong>: monosaccharides (glucose), disaccharides (sucrose), polysaccharides (starch, glycogen, cellulose).</p><h3>Lipids</h3><p><strong>Concentrated energy</strong> store (fats/oils), insulation and membrane structure. Built from <strong>fatty acids and glycerol</strong>. Saturated fats are solid (ghee); unsaturated are liquid (oils).</p>'},
{id:'bal-c9-bio-ch2-l3', title:'Proteins and Nucleic Acids', html:'<h3>Proteins</h3><p>Made of <strong>amino acids</strong> (20 types); do most cell work — enzymes, muscles, antibodies, hormones like insulin.</p><h3>Nucleic Acids</h3><p><strong>DNA</strong> (double helix) carries hereditary information; <strong>RNA</strong> helps make proteins. The sequence DNA → RNA → protein is the <strong>central dogma</strong> of molecular biology.</p>'}],
quiz:[
{q:'Biomolecules are mainly built from', options:['only carbon','C, H, O, N and P','metals','silicon'], answer:1, explain:'Living molecules are carbon-based with H, O, N and P.'},
{q:'Glucose is a', options:['disaccharide','monosaccharide','polysaccharide','lipid'], answer:1, explain:'Glucose is a single-sugar monosaccharide.'},
{q:'Starch is a', options:['protein','polysaccharide','lipid','nucleic acid'], answer:1, explain:'Starch is a polymer of glucose — a polysaccharide.'},
{q:'Lipids are made of', options:['amino acids','fatty acids and glycerol','nucleotides','glucose'], answer:1, explain:'Fats/oils = glycerol + fatty acids.'},
{q:'Proteins are polymers of', options:['glucose','amino acids','nucleotides','fatty acids'], answer:1, explain:'Chains of amino acids fold into proteins.'},
{q:'How many types of amino acids build proteins?', options:['4','10','20','64'], answer:2, explain:'20 standard amino acids make all proteins.'},
{q:'DNA carries', options:['energy','hereditary information','oxygen','water'], answer:1, explain:'DNA stores the genetic instructions of the cell.'},
{q:'The central dogma is', options:['DNA → RNA → protein','protein → DNA → RNA','RNA → DNA → lipid','fat → protein → DNA'], answer:0, explain:'Genetic information flows from DNA to RNA to protein.'},
{q:'Insulin is an example of a protein that acts as a', options:['enzyme','hormone','antibody','fibre'], answer:1, explain:'Insulin is a protein hormone controlling blood sugar.'},
{q:'Which gives the most energy per gram?', options:['carbohydrate','protein','lipid','nucleic acid'], answer:2, explain:'Lipids give ~9 kcal/g, double carbohydrates/proteins.'}]},
{id:'bal-c9-bio-ch3', title:'Cell and Subcellular Organelles', urdu:'خلیہ اور ذیلی خلوی عضویے', comingSoon:false, lessons:[
{id:'bal-c9-bio-ch3-l1', title:'The Cell — Basic Unit of Life', html:'<h3>Cell Theory</h3><ul><li>All living things are made of <strong>cells</strong>.</li><li>The cell is the <strong>basic structural and functional unit</strong> of life.</li><li>All cells arise from <strong>pre-existing cells</strong> (Virchow).</li></ul><p>Discovered by <strong>Robert Hooke</strong> (1665) in cork; <strong>Schleiden and Schwann</strong> proposed the theory. <strong>Prokaryotic</strong> cells lack a nucleus (bacteria); <strong>eukaryotic</strong> cells have one.</p>'},
{id:'bal-c9-bio-ch3-l2', title:'Animal and Plant Cells', html:'<h3>Comparing Cells</h3><table><tr><th>Feature</th><th>Animal cell</th><th>Plant cell</th></tr><tr><td>Cell wall</td><td>absent</td><td>present (cellulose)</td></tr><tr><td>Chloroplast</td><td>absent</td><td>present</td></tr><tr><td>Large vacuole</td><td>absent/small</td><td>present</td></tr><tr><td>Shape</td><td>irregular</td><td>fixed</td></tr></table>'},
{id:'bal-c9-bio-ch3-l3', title:'Subcellular Organelles', html:'<h3>Organelles and Jobs</h3><ul><li><strong>Nucleus</strong> — controls the cell; holds DNA.</li><li><strong>Mitochondria</strong> — release energy (powerhouse).</li><li><strong>Ribosomes</strong> — make proteins.</li><li><strong>Endoplasmic reticulum</strong> — transports materials.</li><li><strong>Golgi body</strong> — packages secretions.</li><li><strong>Cell membrane</strong> — controls entry/exit (selectively permeable).</li><li><strong>Chloroplast</strong> — photosynthesis in plants.</li></ul>'}],
quiz:[
{q:'Who discovered the cell?', options:['Schleiden','Robert Hooke','Virchow','Leeuwenhoek'], answer:1, explain:'Hooke saw cork cells in 1665 and coined “cell”.'},
{q:'“All cells arise from pre-existing cells” was stated by', options:['Hooke','Schleiden','Virchow','Brown'], answer:2, explain:'Rudolf Virchow added this to cell theory.'},
{q:'Bacteria are prokaryotic because they', options:['are small','lack a true nucleus','have no cell wall','cannot move'], answer:1, explain:'Prokaryotes have no membrane-bound nucleus.'},
{q:'Which organelle is called the powerhouse of the cell?', options:['nucleus','ribosome','mitochondria','Golgi body'], answer:2, explain:'Mitochondria release energy from glucose (respiration).'},
{q:'Proteins are made by', options:['lysosomes','ribosomes','vacuoles','chloroplasts'], answer:1, explain:'Ribosomes are the sites of protein synthesis.'},
{q:'Photosynthesis occurs in the', options:['mitochondria','chloroplast','nucleus','cell wall'], answer:1, explain:'Chloroplasts contain chlorophyll for photosynthesis.'},
{q:'The cell membrane is', options:['fully permeable','selectively permeable','impermeable','rigid'], answer:1, explain:'It controls which substances enter or leave.'},
{q:'Which structure is found in plant cells but not animal cells?', options:['nucleus','cell wall','ribosome','mitochondria'], answer:1, explain:'Plant cells have a cellulose cell wall; animal cells do not.'},
{q:'The control centre of the cell is the', options:['cytoplasm','nucleus','vacuole','membrane'], answer:1, explain:'The nucleus holds DNA and directs cell activities.'},
{q:'Different cell types (muscle, nerve, leaf) show', options:['cell theory','division of labour through specialisation','no organisation','random structure'], answer:1, explain:'Specialised cells divide labour in multicellular organisms.'}]},
{id:'bal-c9-bio-ch4', title:'Tissues, Organs and Systems', urdu:'نسیجیں، اعضا اور نظام', comingSoon:false, lessons:[
{id:'bal-c9-bio-ch4-l1', title:'Levels of Organisation', html:'<h3>From Cells to Organisms</h3><p><strong>Cell → tissue → organ → organ system → organism.</strong> A <strong>tissue</strong> is a group of similar cells doing one job (muscle tissue); an <strong>organ</strong> is tissues working together (heart); an <strong>organ system</strong> is organs cooperating (circulatory system).</p>'},
{id:'bal-c9-bio-ch4-l2', title:'Tissues in Plants and Animals', html:'<h3>Plant Tissues</h3><p><strong>Meristematic</strong> (dividing, at tips) and <strong>permanent</strong> (xylem transports water, phloem transports food).</p><h3>Animal Tissues</h3><p><strong>Epithelial</strong> (covering), <strong>muscular</strong> (movement), <strong>nervous</strong> (messages), <strong>connective</strong> (blood, bone — support).</p>'},
{id:'bal-c9-bio-ch4-l3', title:'Organs, Systems and Homeostasis', html:'<h3>Examples</h3><ul><li><strong>Leaf:</strong> epidermis, mesophyll and veins work together for photosynthesis.</li><li><strong>Human stomach:</strong> muscle churns, glands secrete acid/enzymes — digestion.</li></ul><p><strong>Human body systems:</strong> digestive, respiratory, circulatory, nervous, excretory, skeletal, muscular, reproductive. <strong>Homeostasis</strong> keeps internal conditions (temperature, sugar, water) stable despite outside changes.</p>'}],
quiz:[
{q:'The correct order of organisation is', options:['organ → cell → tissue → system','cell → tissue → organ → system','tissue → cell → organ → system','system → organ → tissue → cell'], answer:1, explain:'Cells form tissues, tissues form organs, organs form systems.'},
{q:'Xylem tissue transports', options:['food','water and minerals','hormones','oxygen'], answer:1, explain:'Xylem carries water and minerals from roots upward.'},
{q:'Phloem transports', options:['water','food (sugars)','air','waste'], answer:1, explain:'Phloem translocates sugars from leaves to other parts.'},
{q:'Nervous tissue is specialised for', options:['contraction','carrying messages','support','covering'], answer:1, explain:'Nerve cells transmit electrical impulses.'},
{q:'Blood is a', options:['muscular tissue','connective tissue','epithelial tissue','nervous tissue'], answer:1, explain:'Blood connects and transports — a fluid connective tissue.'},
{q:'Meristematic tissue is found', options:['in old wood','at root and shoot tips','in fruits only','in seeds only'], answer:1, explain:'Meristems at tips divide to grow the plant.'},
{q:'The stomach is an example of', options:['a cell','a tissue','an organ','a system'], answer:2, explain:'Multiple tissues (muscle, epithelium, glands) make the stomach an organ.'},
{q:'Homeostasis means', options:['rapid growth','keeping internal conditions stable','cell division','digestion'], answer:1, explain:'Homeostasis maintains steady internal conditions.'},
{q:'Which system removes waste?', options:['digestive','excretory','nervous','skeletal'], answer:1, explain:'The excretory (urinary) system removes metabolic wastes.'},
{q:'A leaf performs photosynthesis through cooperation of', options:['one cell type','multiple tissues','the roots only','the stem only'], answer:1, explain:'Epidermis, mesophyll and veins work together — an organ.'}]},
{id:'bal-c9-bio-ch5', title:'Metabolism', urdu:'میٹابولزم', comingSoon:false, lessons:[
{id:'bal-c9-bio-ch5-l1', title:'Metabolism and Enzymes', html:'<h3>Metabolism</h3><p><strong>Metabolism</strong> is the sum of all chemical reactions in the body: <strong>anabolism</strong> (building up, e.g. photosynthesis) and <strong>catabolism</strong> (breaking down, e.g. respiration).</p><p><strong>Enzymes</strong> are biological <strong>catalysts</strong> — proteins that speed up reactions without being used up.</p>'},
{id:'bal-c9-bio-ch5-l2', title:'Mechanism of Enzyme Action', html:'<h3>Lock and Key</h3><p>Each enzyme has an <strong>active site</strong> shaped to fit its <strong>substrate</strong> — the <strong>lock-and-key model</strong>. The enzyme–substrate complex forms, products are released, and the enzyme is reused.</p><p>Example: <strong>amylase</strong> (saliva) digests starch; <strong>pepsin</strong> (stomach) digests protein.</p>'},
{id:'bal-c9-bio-ch5-l3', title:'Factors Affecting Enzymes and Inhibition', html:'<h3>Factors</h3><ul><li><strong>Temperature:</strong> rate rises to an optimum (~37 °C in humans), then the enzyme <strong>denatures</strong>.</li><li><strong>pH:</strong> each enzyme has an optimum pH (pepsin ~pH 2).</li><li><strong>Substrate concentration:</strong> more substrate, faster rate — until saturation.</li></ul><p><strong>Inhibitors:</strong> <strong>competitive</strong> block the active site; <strong>non-competitive</strong> change the enzyme’s shape.</p>'}],
quiz:[
{q:'Metabolism is', options:['only digestion','the sum of all chemical reactions in the body','cell division','breathing'], answer:1, explain:'Metabolism = all anabolic + catabolic reactions.'},
{q:'Building complex molecules from simpler ones is', options:['catabolism','anabolism','digestion','excretion'], answer:1, explain:'Anabolism builds up; catabolism breaks down.'},
{q:'Enzymes are', options:['carbohydrates','proteins acting as biological catalysts','lipids','minerals'], answer:1, explain:'Most enzymes are protein catalysts.'},
{q:'The lock-and-key model describes', options:['DNA replication','enzyme–substrate fitting','cell division','muscle contraction'], answer:1, explain:'The substrate fits the enzyme’s active site like a key in a lock.'},
{q:'Amylase digests', options:['protein','starch','fat','fibre'], answer:1, explain:'Salivary amylase breaks down starch.'},
{q:'Human enzymes work best at about', options:['0 °C','20 °C','37 °C','100 °C'], answer:2, explain:'Body temperature (~37 °C) is the optimum; higher denatures enzymes.'},
{q:'Denaturation of an enzyme means', options:['it works faster','its shape is destroyed and it stops working','it multiplies','it cools'], answer:1, explain:'Heat or extreme pH unfolds the protein — function is lost.'},
{q:'Pepsin works best at', options:['pH 7','pH 2 (acidic)','pH 10','pH 14'], answer:1, explain:'Stomach pepsin needs strongly acidic conditions.'},
{q:'A competitive inhibitor', options:['changes enzyme shape elsewhere','blocks the active site','increases temperature','adds substrate'], answer:1, explain:'It competes with substrate for the active site.'},
{q:'Enzymes are not used up because they', options:['are indestructible','are regenerated after each reaction','reproduce','are minerals'], answer:1, explain:'Catalysts emerge unchanged and act again.'}]},
{id:'bal-c9-bio-ch6', title:'Biodiversity and Classification', urdu:'حیاتیاتی تنوع اور درجہ بندی', comingSoon:false, lessons:[
{id:'bal-c9-bio-ch6-l1', title:'Biodiversity', html:'<h3>Biodiversity</h3><p><strong>Biodiversity</strong> is the variety of life on Earth — species, genes and ecosystems. It gives us food, medicines, clean air and stable ecosystems. Threats: <strong>deforestation, pollution, overhunting and climate change</strong>.</p>'},
{id:'bal-c9-bio-ch6-l2', title:'History of Classification', html:'<h3>Classifying Life</h3><p><strong>Classification</strong> groups organisms by similarities, making millions of species easier to study.</p><ul><li><strong>Aristotle:</strong> first grouped plants/animals.</li><li><strong>Linnaeus:</strong> binomial nomenclature and modern ranks.</li><li><strong>Whittaker:</strong> five kingdoms (Monera, Protista, Fungi, Plantae, Animalia).</li><li><strong>Woese:</strong> three domains — Bacteria, Archaea, Eukarya.</li></ul>'},
{id:'bal-c9-bio-ch6-l3', title:'Taxonomic Ranks and Binomial Nomenclature', html:'<h3>Ranks</h3><p><strong>Domain → Kingdom → Phylum → Class → Order → Family → Genus → Species.</strong> <strong>Species</strong> is the basic unit — organisms that can interbreed.</p><p><strong>Binomial nomenclature:</strong> every species gets a two-part Latin name — <em>Genus species</em>, e.g. <em>Homo sapiens</em> (humans), <em>Mangifera indica</em> (mango). Genus is capitalised; both are italicised.</p>'}],
quiz:[
{q:'Biodiversity means', options:['variety of rocks','variety of life on Earth','one species','only plants'], answer:1, explain:'Biodiversity = variety of species, genes and ecosystems.'},
{q:'A major threat to biodiversity is', options:['photosynthesis','deforestation','rainfall','pollination'], answer:1, explain:'Cutting forests destroys habitats and species.'},
{q:'The five-kingdom system was proposed by', options:['Linnaeus','Whittaker','Aristotle','Darwin'], answer:1, explain:'Whittaker (1969) proposed Monera, Protista, Fungi, Plantae, Animalia.'},
{q:'The three domains of life are', options:['plants, animals, fungi','Bacteria, Archaea, Eukarya','land, water, air','producers, consumers, decomposers'], answer:1, explain:'Woese’s three-domain system is the broadest grouping.'},
{q:'The basic unit of classification is', options:['genus','family','species','order'], answer:2, explain:'Species is the fundamental rank.'},
{q:'The scientific name of humans is', options:['Homo Sapiens written plainly','Homo sapiens','sapiens Homo','Human being'], answer:1, explain:'Genus capitalised, species lowercase, both italicised: Homo sapiens.'},
{q:'In binomial nomenclature, the first word is the', options:['species','genus','family','order'], answer:1, explain:'Name = Genus + species epithet.'},
{q:'Viruses are considered', options:['a sixth kingdom','on the border of living and non-living','plants','definitely alive'], answer:1, explain:'Viruses show some life traits only inside host cells.'},
{q:'Classification helps scientists', options:['create species','study organisms systematically','increase species','avoid fieldwork'], answer:1, explain:'Grouping by similarity organises millions of species.'},
{q:'Which is the correct rank order (broad to specific)?', options:['species → genus → family','kingdom → phylum → class → order','order → kingdom → phylum','family → domain → genus'], answer:1, explain:'Kingdom → Phylum → Class → Order → Family → Genus → Species.'}]},
{id:'bal-c9-bio-ch7', title:'Forms and Functions in Plants', urdu:'پودوں میں اشکال و افعال', comingSoon:false, lessons:[
{id:'bal-c9-bio-ch7-l1', title:'Mineral Nutrition in Plants', html:'<h3>Plant Nutrients</h3><p>Plants need <strong>macronutrients</strong> in large amounts (nitrogen, phosphorus, potassium, magnesium, calcium) and <strong>micronutrients</strong> in small amounts (iron, zinc, manganese).</p><ul><li><strong>Nitrogen</strong> — needed for <strong>proteins</strong> and chlorophyll; deficiency causes yellow, stunted leaves.</li><li><strong>Magnesium</strong> — central atom of <strong>chlorophyll</strong>; deficiency causes yellowing between veins.</li></ul>'},
{id:'bal-c9-bio-ch7-l2', title:'Transport in Plants', html:'<h3>Plant Transport</h3><ul><li><strong>Xylem</strong> — carries water and minerals from roots to leaves (transpiration pull).</li><li><strong>Phloem</strong> — carries sugars from leaves to other parts (translocation).</li></ul><p>Water enters <strong>root hairs</strong> by osmosis — their large surface area absorbs efficiently.</p>'},
{id:'bal-c9-bio-ch7-l3', title:'Root Structure and Fertilisers', html:'<h3>Roots and Fertilisers</h3><p>The <strong>root</strong> anchors the plant and absorbs water/minerals. Internally: epidermis (with root hairs) → cortex → xylem/phloem in the centre.</p><p><strong>Chemical fertilisers</strong> boost yield but overuse pollutes water (algal blooms), makes soil acidic and harms useful microbes — use them carefully.</p>'}],
quiz:[
{q:'Which is a macronutrient for plants?', options:['zinc','nitrogen','manganese','boron'], answer:1, explain:'Nitrogen is needed in large amounts; the others are micronutrients.'},
{q:'Nitrogen is essential for making', options:['chlorophyll only','proteins','cellulose','water'], answer:1, explain:'Nitrogen is a key part of amino acids and proteins.'},
{q:'Magnesium is the central atom of', options:['haemoglobin','chlorophyll','ATP','DNA'], answer:1, explain:'Each chlorophyll molecule holds one magnesium atom.'},
{q:'Yellowing of leaves can indicate deficiency of', options:['carbon','nitrogen or magnesium','oxygen','hydrogen'], answer:1, explain:'N and Mg are needed for chlorophyll; lack causes chlorosis.'},
{q:'Water is transported in plants by', options:['phloem','xylem','cambium','pith'], answer:1, explain:'Xylem vessels carry water and minerals upward.'},
{q:'Sugars are transported by', options:['xylem','phloem','root hairs','stomata'], answer:1, explain:'Phloem translocates food from leaves.'},
{q:'Root hairs absorb water by', options:['photosynthesis','osmosis','respiration','transpiration'], answer:1, explain:'Water moves by osmosis into root-hair cells.'},
{q:'Overuse of chemical fertilisers can cause', options:['more earthworms','water pollution and algal blooms','richer soil forever','cleaner air'], answer:1, explain:'Runoff fertilisers eutrophy ponds and harm aquatic life.'},
{q:'The function of roots is to', options:['make food','anchor the plant and absorb water/minerals','transport sugar','exchange gases'], answer:1, explain:'Roots anchor and absorb; leaves make food.'},
{q:'Which pair is correct?', options:['xylem — food','phloem — water','xylem — water, phloem — food','cortex — water'], answer:2, explain:'Xylem carries water up; phloem carries food around.'}]},
{id:'bal-c9-bio-ch8', title:'Evolution', urdu:'ارتقا', comingSoon:false, lessons:[
{id:'bal-c9-bio-ch8-l1', title:'Concept of Evolution', html:'<h3>Evolution</h3><p><strong>Evolution</strong> is the gradual change in organisms over generations. Early ideas: <strong>Lamarck</strong> proposed inheritance of acquired characters (giraffes stretching necks) — now rejected.</p><p><strong>Darwin</strong>, after his voyage on HMS <strong>Beagle</strong> (observing finches on the Galápagos Islands), proposed evolution by <strong>natural selection</strong>.</p>'},
{id:'bal-c9-bio-ch8-l2', title:'Natural Selection', html:'<h3>Theory of Natural Selection</h3><ol><li>Organisms produce <strong>more offspring</strong> than can survive.</li><li>There is <strong>variation</strong> among individuals.</li><li>Individuals with helpful traits <strong>survive and reproduce</strong> (survival of the fittest).</li><li>Useful traits are <strong>inherited</strong>, spreading through the population.</li></ol><p>Example: antibiotic-resistant bacteria survive medicines and multiply.</p>'},
{id:'bal-c9-bio-ch8-l3', title:'Evidences of Evolution', html:'<h3>Evidence</h3><ul><li><strong>Fossils</strong> — show extinct forms linking past and present.</li><li><strong>Homologous organs</strong> — same structure, different function (human arm, bat wing, whale flipper) → common ancestor.</li><li><strong>Vestigial organs</strong> — reduced structures (human appendix, tailbone).</li><li><strong>Embryology and DNA</strong> — similar embryos and genetic code point to common descent.</li></ul>'}],
quiz:[
{q:'Evolution is', options:['sudden creation','gradual change in organisms over generations','only extinction','growth of one animal'], answer:1, explain:'Evolution = descent with modification over long time.'},
{q:'Darwin made key observations during his voyage on', options:['Titanic','HMS Beagle','Mayflower','Victoria'], answer:1, explain:'The Beagle voyage (1831–36), especially Galápagos finches, shaped his theory.'},
{q:'Natural selection is driven by', options:['need only','variation + competition + inheritance','luck only','human choice'], answer:1, explain:'Variation, overproduction, survival of the fittest, inheritance.'},
{q:'“Survival of the fittest” means', options:['the strongest always win','best-adapted individuals reproduce more','only big animals survive','fitness for sports'], answer:1, explain:'Fitness = reproductive success in a given environment.'},
{q:'Lamarck’s theory proposed', options:['natural selection','inheritance of acquired characters','genetics','extinction'], answer:1, explain:'Lamarck wrongly suggested use/disuse traits are inherited.'},
{q:'Homologous organs (human arm, bat wing) indicate', options:['same function','common ancestry','convergent design','no relation'], answer:1, explain:'Same basic structure modified for different uses → shared ancestor.'},
{q:'The human appendix is an example of a', options:['homologous organ','vestigial organ','fossil','analogous organ'], answer:1, explain:'Vestigial organs are reduced remnants of once-useful structures.'},
{q:'Antibiotic resistance in bacteria is an example of', options:['artificial selection','natural selection in action','Lamarckism','extinction'], answer:1, explain:'Resistant bacteria survive antibiotics and multiply.'},
{q:'Fossils provide evidence of', options:['future species','organisms that lived in the past','weather','rocks only'], answer:1, explain:'Fossils are remains/traces of ancient life.'},
{q:'Similar DNA sequences between species suggest', options:['nothing','common descent','same diet','same habitat'], answer:1, explain:'Genetic similarity reflects shared ancestry.'}]}
]});
