window.__saMergeCourse({id:'bal-class9-math', board:'balochistan', title:'Mathematics', urdu:'ریاضی', class:'Class 9', icon:'📐', desc:'Balochistan Board Class 9 Mathematics — full syllabus with lessons and quizzes.', chapters:[
{id:'bal-c9-mat-ch1', title:'Real Numbers', urdu:'حقیقی اعداد', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch1-l1', title:'Rational and Irrational Numbers', html:'<h3>Real Numbers</h3><p><strong>Real numbers</strong> = <strong>rational</strong> + <strong>irrational</strong> numbers.</p><ul><li><strong>Rational:</strong> can be written as p/q (q ≠ 0); decimals terminate or repeat (½ = 0.5, ⅓ = 0.333…).</li><li><strong>Irrational:</strong> non-terminating, non-repeating decimals (√2, π).</li></ul><p>Every real number sits at a unique point on the <strong>number line</strong>.</p>'},
{id:'bal-c9-mat-ch1-l2', title:'Laws of Exponents (Indices)', html:'<h3>Laws of Indices</h3><ul><li>aᵐ × aⁿ = aᵐ⁺ⁿ</li><li>aᵐ ÷ aⁿ = aᵐ⁻ⁿ</li><li>(aᵐ)ⁿ = aᵐⁿ</li><li>a⁰ = 1 (a ≠ 0)</li><li>a⁻ⁿ = 1/aⁿ</li></ul><p>Example: 2³ × 2² = 2⁵ = 32. These laws work for rational exponents too: a^(1/2) = √a.</p>'},
{id:'bal-c9-mat-ch1-l3', title:'Radicals and Surds', html:'<h3>Surds</h3><p>A <strong>surd</strong> is an irrational root, e.g. √2, √3, ∛5. <strong>Radicand</strong> = number under the root sign.</p><p>Simplify: √50 = √(25 × 2) = 5√2. Rationalise: 1/√2 = √2/2 (multiply top and bottom by √2). Like surds can be added: 3√2 + 5√2 = 8√2.</p>'}],
quiz:[
{q:'Which is an irrational number?', options:['0.5','⅓','√2','−3'], answer:2, explain:'√2 = 1.414… never terminates or repeats.'},
{q:'0.333… is', options:['irrational','rational','not a real number','an integer'], answer:1, explain:'Repeating decimals are rational (0.333… = ⅓).'},
{q:'aᵐ × aⁿ equals', options:['aᵐⁿ','aᵐ⁺ⁿ','aᵐ⁻ⁿ','(am)ⁿ'], answer:1, explain:'Multiply powers: add the exponents.'},
{q:'(3²)³ equals', options:['3⁵','3⁶','3⁸','9³'], answer:1, explain:'(aᵐ)ⁿ = aᵐⁿ, so 3⁶ = 729.'},
{q:'5⁰ equals', options:['0','5','1','undefined'], answer:2, explain:'Any non-zero number to power 0 is 1.'},
{q:'2⁻³ equals', options:['−8','8','1/8','−1/8'], answer:2, explain:'a⁻ⁿ = 1/aⁿ, so 2⁻³ = 1/8.'},
{q:'√50 in simplest surd form is', options:['5√2','2√5','10√2','25√2'], answer:0, explain:'√50 = √(25×2) = 5√2.'},
{q:'Rationalising 1/√2 gives', options:['√2','√2/2','2√2','1/2'], answer:1, explain:'Multiply numerator and denominator by √2: √2/2.'},
{q:'3√2 + 5√2 equals', options:['8√4','8√2','15√2','√64'], answer:1, explain:'Like surds add: (3+5)√2 = 8√2.'},
{q:'Which is a rational number?', options:['π','√7','22/7','√2'], answer:2, explain:'22/7 is a ratio of integers — rational (though not exactly π).'}]},
{id:'bal-c9-mat-ch2', title:'Logarithms', urdu:'لوگارتھم', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch2-l1', title:'Definition of Logarithm', html:'<h3>Logarithms</h3><p>If aˣ = y, then <strong>logₐ y = x</strong> (log of y to base a). Example: 2³ = 8 → log₂ 8 = 3.</p><p><strong>Common logarithm:</strong> base 10 (log). <strong>Natural logarithm:</strong> base e (ln). Logarithms turn multiplication into addition — once vital for big calculations.</p>'},
{id:'bal-c9-mat-ch2-l2', title:'Laws of Logarithms', html:'<h3>Log Laws</h3><ul><li>log(mn) = log m + log n</li><li>log(m/n) = log m − log n</li><li>log(mⁿ) = n log m</li><li>logₐ a = 1; logₐ 1 = 0</li></ul><p>Example: log(1000) = log(10³) = 3 log 10 = 3.</p>'},
{id:'bal-c9-mat-ch2-l3', title:'Characteristic, Mantissa and Applications', html:'<h3>Parts of a Logarithm</h3><p>log 3720 = 3.5705: <strong>characteristic</strong> = 3 (integer part, gives magnitude), <strong>mantissa</strong> = .5705 (decimal part, always positive).</p><p><strong>Scientific notation:</strong> 3720 = 3.72 × 10³. <strong>Applications:</strong> pH scale, Richter scale for earthquakes, decibels for sound — all logarithmic.</p>'}],
quiz:[
{q:'If 2³ = 8, then log₂ 8 equals', options:['2','3','8','16'], answer:1, explain:'The logarithm is the exponent: 3.'},
{q:'logₐ a equals', options:['0','1','a','10'], answer:1, explain:'a¹ = a, so logₐ a = 1.'},
{q:'log 1 (any base) equals', options:['1','0','10','undefined'], answer:1, explain:'a⁰ = 1, so logₐ 1 = 0.'},
{q:'log(mn) equals', options:['log m × log n','log m + log n','log m − log n','(log m)ⁿ'], answer:1, explain:'Log of a product = sum of logs.'},
{q:'log(mⁿ) equals', options:['n + log m','n log m','log m ÷ n','(log m)ⁿ'], answer:1, explain:'Power rule: bring the exponent down.'},
{q:'log(1000) to base 10 equals', options:['2','3','10','100'], answer:1, explain:'10³ = 1000, so log₁₀ 1000 = 3.'},
{q:'In log 3720 = 3.5705, the characteristic is', options:['.5705','3','3720','35'], answer:1, explain:'The integer part (3) is the characteristic.'},
{q:'The mantissa is always', options:['negative','positive (or zero)','an integer','greater than 1'], answer:1, explain:'Mantissa is the positive decimal part.'},
{q:'The Richter scale for earthquakes is', options:['linear','logarithmic','quadratic','random'], answer:1, explain:'Each Richter point means ~32× more energy — logarithmic.'},
{q:'log 20 − log 4 equals', options:['log 5','log 16','log 80','5'], answer:0, explain:'log(m/n) = log m − log n → log(20/4) = log 5.'}]},
{id:'bal-c9-mat-ch3', title:'Sets and Relations', urdu:'سیٹ اور تعلقات', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch3-l1', title:'Sets and Types', html:'<h3>Sets</h3><p>A <strong>set</strong> is a well-defined collection of distinct objects. Written in <strong>roster form</strong> {1, 2, 3} or <strong>set-builder</strong> {x : x is even}.</p><ul><li><strong>Finite/infinite</strong>, <strong>empty (null) set</strong> ∅, <strong>singleton</strong> {5}.</li><li><strong>Subset:</strong> A ⊆ B if every element of A is in B.</li><li><strong>Universal set</strong> U contains everything under discussion.</li></ul>'},
{id:'bal-c9-mat-ch3-l2', title:'Operations on Sets and Venn Diagrams', html:'<h3>Set Operations</h3><ul><li><strong>Union:</strong> A ∪ B — in A or B.</li><li><strong>Intersection:</strong> A ∩ B — in both.</li><li><strong>Difference:</strong> A − B — in A but not B.</li><li><strong>Complement:</strong> A′ — in U but not in A.</li></ul><p><strong>Venn diagrams</strong> draw these as overlapping circles — ideal for word problems about students liking subjects.</p>'},
{id:'bal-c9-mat-ch3-l3', title:'Ordered Pairs, Cartesian Product and Relations', html:'<h3>Relations</h3><p>An <strong>ordered pair</strong> (a, b) has order: (1, 2) ≠ (2, 1). <strong>Cartesian product</strong> A × B = all pairs (a, b) with a ∈ A, b ∈ B.</p><p>A <strong>relation</strong> is a subset of A × B — e.g. “is greater than”. If each input has exactly one output, the relation is a <strong>function</strong>.</p>'}],
quiz:[
{q:'Which is a well-defined set?', options:['tall students','vowels of English alphabet','nice books','big cities'], answer:1, explain:'Vowels are precisely defined; the others are vague.'},
{q:'The empty set is denoted by', options:['{0}','∅','{∅}','0'], answer:1, explain:'∅ (or {}) is the set with no elements.'},
{q:'If A = {1,2,3} and B = {2,3,4}, A ∪ B equals', options:['{2,3}','{1,2,3,4}','{1,4}','{}'], answer:1, explain:'Union collects all distinct elements.'},
{q:'A ∩ B for the same sets equals', options:['{1,2,3,4}','{2,3}','{1,4}','{1,2}'], answer:1, explain:'Intersection keeps only common elements 2 and 3.'},
{q:'The complement of A (A′) is', options:['elements in A','elements in U but not in A','empty set','A itself'], answer:1, explain:'Complement = everything in the universal set outside A.'},
{q:'Venn diagrams are used to', options:['draw graphs','show set relationships visually','solve equations','measure angles'], answer:1, explain:'Overlapping circles display unions, intersections and complements.'},
{q:'(1, 2) and (2, 1) are', options:['equal','different ordered pairs','sets','not pairs'], answer:1, explain:'Order matters in ordered pairs.'},
{q:'If A = {1,2} and B = {x,y}, A × B has', options:['2 elements','4 elements','6 elements','3 elements'], answer:1, explain:'2 × 2 = 4 pairs: (1,x), (1,y), (2,x), (2,y).'},
{q:'A relation is a function if', options:['it has many outputs','each input has exactly one output','it is empty','inputs repeat'], answer:1, explain:'Function = one output per input.'},
{q:'A ⊆ B means', options:['A equals B','every element of A is in B','B is in A','A is empty'], answer:1, explain:'Subset: all of A’s elements belong to B.'}]},
{id:'bal-c9-mat-ch4', title:'Factorization and Algebraic Manipulation', urdu:'تجزی اور الجبری عمل', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch4-l1', title:'Factorization Methods', html:'<h3>Factorization</h3><ul><li><strong>Common factor:</strong> 6x² + 9x = 3x(2x + 3).</li><li><strong>Difference of squares:</strong> a² − b² = (a−b)(a+b).</li><li><strong>Trinomial:</strong> x² + 5x + 6 = (x+2)(x+3).</li><li><strong>Grouping:</strong> ax + ay + bx + by = (a+b)(x+y).</li></ul>'},
{id:'bal-c9-mat-ch4-l2', title:'HCF, LCM and Algebraic Fractions', html:'<h3>HCF and LCM</h3><p><strong>HCF</strong> of 12x² and 18x is 6x (highest common divisor). <strong>LCM</strong> is 36x² (smallest common multiple).</p><p><strong>Algebraic fractions:</strong> simplify by cancelling common factors: (x²−9)/(x+3) = x−3. Add using the LCM of denominators.</p>'},
{id:'bal-c9-mat-ch4-l3', title:'Square Roots of Algebraic Expressions', html:'<h3>Square Roots</h3><p>√(x² + 6x + 9) = √(x+3)² = x + 3 (taking the positive root). Method: factorise the expression into a perfect square, then take the root.</p><p>Also: √(16x⁴) = 4x². Surds in algebra simplify like numbers: √8x² = 2x√2.</p>'}],
quiz:[
{q:'Factorise: x² − 16', options:['(x−4)(x+4)','(x−8)(x+2)','(x−4)²','(x+4)²'], answer:0, explain:'Difference of squares: a²−b² = (a−b)(a+b).'},
{q:'Factorise: x² + 7x + 12', options:['(x+3)(x+4)','(x+6)(x+2)','(x+12)(x+1)','(x−3)(x−4)'], answer:0, explain:'Two numbers with product 12 and sum 7: 3 and 4.'},
{q:'HCF of 12x² and 18x is', options:['36x²','6x','6','3x'], answer:1, explain:'Highest common factor: 6x.'},
{q:'LCM of 12x² and 18x is', options:['6x','36x²','36x','216x³'], answer:1, explain:'Smallest common multiple: 36x².'},
{q:'Simplify: (x²−9)/(x+3)', options:['x+3','x−3','x−9','3'], answer:1, explain:'(x−3)(x+3)/(x+3) = x−3.'},
{q:'√(x² + 6x + 9) equals', options:['x+9','x+3','x²+3','3x'], answer:1, explain:'x²+6x+9 = (x+3)², so the root is x+3.'},
{q:'Factorise by grouping: ax + ay + bx + by', options:['(a+x)(b+y)','(a+b)(x+y)','ab(x+y)','(a−b)(x−y)'], answer:1, explain:'a(x+y) + b(x+y) = (a+b)(x+y).'},
{q:'6x² + 9x factorised is', options:['3x(2x+3)','3(2x²+3x)','x(6x+9)','9x(2x+1)'], answer:0, explain:'Common factor 3x: 3x(2x+3).'},
{q:'√(16x⁴) equals', options:['4x⁴','8x²','4x²','16x²'], answer:2, explain:'√16 = 4 and √(x⁴) = x².'},
{q:'x² + 5x + 6 = 0 gives x equals', options:['2, 3','−2, −3','−2, 3','1, 6'], answer:1, explain:'(x+2)(x+3) = 0 → x = −2 or −3.'}]},
{id:'bal-c9-mat-ch5', title:'Linear Equations and Inequalities', urdu:'خطی مساواتیں اور غیر مساواتیں', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch5-l1', title:'Linear Equations in One Variable', html:'<h3>Linear Equations</h3><p>A <strong>linear equation</strong> has the form ax + b = 0 (highest power 1). Solve by isolating x: 3x + 5 = 20 → 3x = 15 → x = 5.</p><p><strong>Radical equations:</strong> √(x+1) = 3 → square both sides: x + 1 = 9 → x = 8 (always check for extraneous roots).</p>'},
{id:'bal-c9-mat-ch5-l2', title:'Word Problems', html:'<h3>Turning Words into Equations</h3><p>Steps: let the unknown be x, translate the statement, solve, check.</p><p>Example: “A number added to 7 gives 15” → x + 7 = 15 → x = 8. “Father is 3 times as old as his son; sum is 48” → x + 3x = 48 → son is 12, father is 36.</p>'},
{id:'bal-c9-mat-ch5-l3', title:'Linear Inequalities', html:'<h3>Inequalities</h3><p>Symbols: &lt; &gt; ≤ ≥. Solve like equations, but <strong>reverse the sign when multiplying/dividing by a negative</strong>: −2x &gt; 6 → x &lt; −3.</p><p>Graph x ≥ 2 as a shaded number line starting at 2. Solutions are ranges, not single values.</p>'}],
quiz:[
{q:'Solve: 3x + 5 = 20', options:['x = 3','x = 5','x = 15','x = 25'], answer:1, explain:'3x = 15 → x = 5.'},
{q:'Solve: √(x+1) = 3', options:['x = 2','x = 8','x = 9','x = 10'], answer:1, explain:'Square: x + 1 = 9 → x = 8.'},
{q:'A number added to 7 gives 15. The number is', options:['7','8','22','15'], answer:1, explain:'x + 7 = 15 → x = 8.'},
{q:'Father is 3 times his son’s age; sum is 48. Son’s age is', options:['16','12','36','24'], answer:1, explain:'x + 3x = 48 → 4x = 48 → x = 12.'},
{q:'Solve: −2x > 6', options:['x > −3','x < −3','x > 3','x < 3'], answer:1, explain:'Divide by −2 and flip the sign: x < −3.'},
{q:'Which is a linear equation?', options:['x² + 1 = 0','2x + 3 = 7','1/x = 2','√x = 4'], answer:1, explain:'Highest power of x is 1.'},
{q:'Solve: 5x − 7 = 3x + 5', options:['x = 6','x = −6','x = 1','x = 12'], answer:0, explain:'2x = 12 → x = 6.'},
{q:'The solution of x ≥ 2 includes', options:['only 2','2 and all greater numbers','numbers less than 2','only integers'], answer:1, explain:'≥ means 2 and everything above it.'},
{q:'If 2(x − 3) = 10, x equals', options:['2','8','7','5'], answer:1, explain:'2x − 6 = 10 → 2x = 16 → x = 8.'},
{q:'Twice a number decreased by 5 is 11. The number is', options:['3','8','16','6'], answer:1, explain:'2x − 5 = 11 → 2x = 16 → x = 8.'}]},
{id:'bal-c9-mat-ch6', title:'Trigonometry and Bearing', urdu:'مثلثیات اور بیرنگ', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch6-l1', title:'Trigonometric Ratios', html:'<h3>Ratios in a Right Triangle</h3><p>For angle θ: <strong>sin θ = opposite/hypotenuse</strong>, <strong>cos θ = adjacent/hypotenuse</strong>, <strong>tan θ = opposite/adjacent</strong>.</p><p>Remember <strong>SOH–CAH–TOA</strong>. Angles measured in <strong>degrees</strong>; a right angle is 90°.</p>'},
{id:'bal-c9-mat-ch6-l2', title:'Trigonometric Identities', html:'<h3>Key Identities</h3><ul><li>sin²θ + cos²θ = 1</li><li>tan θ = sin θ / cos θ</li><li>1 + tan²θ = sec²θ</li></ul><p>Use them to prove expressions: e.g. (1 − sin²θ) = cos²θ.</p>'},
{id:'bal-c9-mat-ch6-l3', title:'Heights, Distances and Bearings', html:'<h3>Applications</h3><p><strong>Angle of elevation</strong> — looking up; <strong>angle of depression</strong> — looking down. If a 10 m pole casts a shadow with elevation 45°, height = shadow × tan45°.</p><p><strong>Bearing</strong> — direction measured <strong>clockwise from north</strong>, written with 3 digits (060°). Used in navigation and maps.</p>'}],
quiz:[
{q:'sin θ equals', options:['adjacent/hypotenuse','opposite/hypotenuse','opposite/adjacent','hypotenuse/opposite'], answer:1, explain:'SOH: sine = opposite over hypotenuse.'},
{q:'tan 45° equals', options:['0','1','√3','1/√2'], answer:1, explain:'tan 45° = 1.'},
{q:'sin²θ + cos²θ equals', options:['0','1','2','tan θ'], answer:1, explain:'The fundamental Pythagorean identity.'},
{q:'tan θ in terms of sin and cos is', options:['sin θ × cos θ','sin θ / cos θ','cos θ / sin θ','1 − sin θ'], answer:1, explain:'tan θ = sin θ ÷ cos θ.'},
{q:'The angle of elevation is measured', options:['from the ground up to the line of sight','downward from horizontal','from north','in radians only'], answer:0, explain:'Elevation = looking upward from the horizontal.'},
{q:'A bearing is measured', options:['anticlockwise from south','clockwise from north','from east','in kilometres'], answer:1, explain:'Bearings: clockwise from north, 3 digits.'},
{q:'Bearing 060° points', options:['due east','north-east','due north','south-east'], answer:1, explain:'060° is 60° clockwise from north — north-east.'},
{q:'cos 60° equals', options:['1','1/2','√3/2','0'], answer:1, explain:'cos 60° = 1/2.'},
{q:'In a right triangle, the hypotenuse is', options:['opposite the right angle','the shortest side','adjacent to θ','always 1'], answer:0, explain:'The hypotenuse is opposite the 90° angle.'},
{q:'If sin θ = 3/5 in a right triangle, cos θ equals', options:['4/5','3/4','5/3','5/4'], answer:0, explain:'3-4-5 triangle: cos θ = adjacent/hypotenuse = 4/5.'}]},
{id:'bal-c9-mat-ch7', title:'Coordinate Geometry', urdu:'متناسق جیومیٹری', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch7-l1', title:'The Cartesian Plane', html:'<h3>Coordinate System</h3><p>The plane is divided by the <strong>x-axis</strong> (horizontal) and <strong>y-axis</strong> (vertical) into four <strong>quadrants</strong>. A point (x, y): x = abscissa, y = ordinate.</p><p>Quadrants: I (+,+), II (−,+), III (−,−), IV (+,−). Point (−3, 5) lies in quadrant II.</p>'},
{id:'bal-c9-mat-ch7-l2', title:'Distance and Midpoint Formulae', html:'<h3>Formulae</h3><p><strong>Distance</strong> between (x₁,y₁) and (x₂,y₂): d = √[(x₂−x₁)² + (y₂−y₁)²].</p><p><strong>Midpoint:</strong> ((x₁+x₂)/2, (y₁+y₂)/2). Example: midpoint of (2, 4) and (6, 10) is (4, 7).</p>'},
{id:'bal-c9-mat-ch7-l3', title:'Gradient (Slope) of a Line', html:'<h3>Gradient</h3><p><strong>Gradient m</strong> = (y₂−y₁)/(x₂−x₁) = rise/run. It measures steepness: positive = rising, negative = falling, zero = horizontal, undefined = vertical.</p><p>Parallel lines have <strong>equal gradients</strong>.</p>'}],
quiz:[
{q:'The point (−3, 5) lies in', options:['quadrant I','quadrant II','quadrant III','quadrant IV'], answer:1, explain:'(−, +) is quadrant II.'},
{q:'In (4, −7), the abscissa is', options:['−7','4','(4,−7)','11'], answer:1, explain:'Abscissa = x-coordinate = 4.'},
{q:'Distance between (0,0) and (3,4) is', options:['5','7','12','25'], answer:0, explain:'√(9+16) = √25 = 5.'},
{q:'Midpoint of (2,4) and (6,10) is', options:['(8,14)','(4,7)','(3,5)','(4,6)'], answer:1, explain:'((2+6)/2, (4+10)/2) = (4,7).'},
{q:'Gradient of the line through (1,2) and (3,8) is', options:['2','3','4','6'], answer:2, explain:'m = (8−2)/(3−1) = 6/2 = 3.'},
{q:'A horizontal line has gradient', options:['1','0','undefined','−1'], answer:1, explain:'No rise → m = 0.'},
{q:'Parallel lines have', options:['equal gradients','gradients multiplying to −1','zero gradient','no gradient'], answer:0, explain:'Parallel lines rise at the same rate.'},
{q:'The point (0, −5) lies on the', options:['x-axis','y-axis','origin','quadrant IV'], answer:1, explain:'x = 0 means the point is on the y-axis.'},
{q:'Gradient measures', options:['length','steepness of a line','area','angle in degrees'], answer:1, explain:'Gradient = rise/run, the steepness.'},
{q:'A line with negative gradient', options:['rises left to right','falls left to right','is horizontal','is vertical'], answer:1, explain:'Negative slope goes downhill left to right.'}]},
{id:'bal-c9-mat-ch8', title:'Geometry of Straight Lines', urdu:'سیدھی لکیروں کی جیومیٹری', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch8-l1', title:'Angles and their Properties', html:'<h3>Types of Angles</h3><ul><li><strong>Acute</strong> &lt; 90°, <strong>right</strong> = 90°, <strong>obtuse</strong> 90°–180°, <strong>straight</strong> = 180°, <strong>reflex</strong> &gt; 180°.</li><li><strong>Complementary</strong> sum to 90°; <strong>supplementary</strong> sum to 180°.</li><li><strong>Vertically opposite</strong> angles are equal.</li></ul>'},
{id:'bal-c9-mat-ch8-l2', title:'Parallel Lines and Transversals', html:'<h3>Angles with Parallel Lines</h3><p>When a <strong>transversal</strong> cuts parallel lines:</p><ul><li><strong>Corresponding</strong> angles are equal (F pattern).</li><li><strong>Alternate</strong> angles are equal (Z pattern).</li><li><strong>Co-interior</strong> angles sum to 180° (C pattern).</li></ul>'},
{id:'bal-c9-mat-ch8-l3', title:'Angle Bisectors and Perpendicular Bisectors', html:'<h3>Bisectors</h3><p>An <strong>angle bisector</strong> divides an angle into two equal parts. A <strong>perpendicular bisector</strong> cuts a segment at 90° through its midpoint — every point on it is equidistant from the segment’s ends.</p><p>Constructed with compass and ruler — no protractor needed.</p>'}],
quiz:[
{q:'An angle of 120° is', options:['acute','right','obtuse','reflex'], answer:2, explain:'Between 90° and 180° = obtuse.'},
{q:'Complementary angles sum to', options:['180°','90°','360°','45°'], answer:1, explain:'Complementary = 90°; supplementary = 180°.'},
{q:'Vertically opposite angles are', options:['supplementary','equal','complementary','90°'], answer:1, explain:'Opposite angles formed by intersecting lines are equal.'},
{q:'Alternate interior angles formed by a transversal on parallel lines are', options:['supplementary','equal','90°','unrelated'], answer:1, explain:'The Z pattern gives equal alternate angles.'},
{q:'Co-interior angles sum to', options:['90°','180°','270°','360°'], answer:1, explain:'Interior angles on the same side add to 180°.'},
{q:'An angle bisector', options:['doubles the angle','divides it into two equal parts','is always vertical','measures 90°'], answer:1, explain:'Bisect = cut into two equal parts.'},
{q:'Every point on a perpendicular bisector of a segment is', options:['at the midpoint','equidistant from the segment’s endpoints','on the segment','at 45°'], answer:1, explain:'That equidistance property defines the perpendicular bisector.'},
{q:'A straight angle equals', options:['90°','180°','270°','360°'], answer:1, explain:'A straight line forms 180°.'},
{q:'The supplement of 70° is', options:['20°','110°','290°','70°'], answer:1, explain:'180 − 70 = 110°.'},
{q:'Corresponding angles are found in the', options:['Z pattern','F pattern','C pattern','X pattern'], answer:1, explain:'The F pattern marks corresponding (equal) angles.'}]},
{id:'bal-c9-mat-ch9', title:'Geometry and Polygons', urdu:'جیومیٹری اور کثیر الاضلاع', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch9-l1', title:'Polygons and their Angles', html:'<h3>Polygons</h3><p>A <strong>polygon</strong> is a closed figure of straight sides: triangle (3), quadrilateral (4), pentagon (5), hexagon (6).</p><p><strong>Sum of interior angles</strong> = (n − 2) × 180°. For a hexagon: 4 × 180° = 720°. Each exterior angle of a regular n-gon = 360°/n.</p>'},
{id:'bal-c9-mat-ch9-l2', title:'Triangles and Quadrilaterals', html:'<h3>Properties</h3><ul><li><strong>Triangle:</strong> angles sum to 180°; exterior angle equals sum of opposite interiors.</li><li><strong>Parallelogram:</strong> opposite sides parallel and equal; diagonals bisect each other.</li><li><strong>Rectangle/rhombus/square:</strong> special parallelograms with right angles and/or equal sides.</li></ul>'},
{id:'bal-c9-mat-ch9-l3', title:'Congruent and Similar Figures', html:'<h3>Congruence and Similarity</h3><p><strong>Congruent</strong> figures are identical in shape and size (SSS, SAS, ASA, RHS tests for triangles). <strong>Similar</strong> figures have the same shape but different size — corresponding angles equal, sides in proportion.</p><p>Maps and models use similarity: a 1:50000 map.</p>'}],
quiz:[
{q:'Sum of interior angles of a hexagon is', options:['360°','540°','720°','900°'], answer:2, explain:'(6−2) × 180° = 720°.'},
{q:'Each exterior angle of a regular pentagon is', options:['72°','108°','60°','90°'], answer:0, explain:'360° ÷ 5 = 72°.'},
{q:'The angles of a triangle sum to', options:['90°','180°','270°','360°'], answer:1, explain:'Angle sum of any triangle is 180°.'},
{q:'In a parallelogram, the diagonals', options:['are equal','bisect each other','are perpendicular','meet at 45°'], answer:1, explain:'Parallelogram diagonals bisect each other.'},
{q:'Congruent triangles are', options:['same shape, different size','identical in shape and size','always right-angled','similar only'], answer:1, explain:'Congruent = exactly the same shape and size.'},
{q:'Which is a valid congruence test?', options:['AAA','SSS','SSA','AA'], answer:1, explain:'SSS, SAS, ASA and RHS prove congruence.'},
{q:'Similar figures have', options:['equal areas','same shape, proportional sides','equal perimeters','same size'], answer:1, explain:'Similarity = same shape, sides in the same ratio.'},
{q:'A square is a special', options:['triangle','parallelogram','circle','pentagon'], answer:1, explain:'A square has both pairs of opposite sides parallel.'},
{q:'Sum of interior angles of a quadrilateral is', options:['180°','270°','360°','540°'], answer:2, explain:'(4−2) × 180° = 360°.'},
{q:'The exterior angle of a triangle equals', options:['the adjacent interior angle','sum of the two opposite interior angles','90°','180°'], answer:1, explain:'Exterior = sum of remote interiors.'}]},
{id:'bal-c9-mat-ch10', title:'Practical Geometry', urdu:'عملی جیومیٹری', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch10-l1', title:'Constructing Triangles', html:'<h3>Triangle Constructions</h3><p>With ruler and compass construct a triangle given:</p><ul><li><strong>SSS:</strong> three sides — draw base, arcs from each end.</li><li><strong>SAS:</strong> two sides and the included angle.</li><li><strong>ASA:</strong> two angles and the included side.</li></ul>'},
{id:'bal-c9-mat-ch10-l2', title:'The Ambiguous Case', html:'<h3>Ambiguous Case (SSA)</h3><p>Given two sides and a <strong>non-included</strong> angle, <strong>two different triangles</strong> may be possible — the swinging side can meet the base at two points. Always check both possibilities.</p><p>This is why SSA is not a congruence test.</p>'},
{id:'bal-c9-mat-ch10-l3', title:'Bisectors, Parallelograms and Circles', html:'<h3>More Constructions</h3><ul><li><strong>Angle bisector:</strong> arcs from the vertex, then from arc intersections.</li><li><strong>Perpendicular bisector:</strong> arcs from both endpoints.</li><li><strong>Parallelogram:</strong> use parallel-side properties with compass.</li><li><strong>Circle:</strong> through three non-collinear points — intersect two perpendicular bisectors to find the centre.</li></ul>'}],
quiz:[
{q:'To construct a triangle, the minimum sufficient data includes', options:['three angles','SSS, SAS or ASA','two sides only','one side one angle'], answer:1, explain:'SSS, SAS, ASA (or RHS) determine a unique triangle.'},
{q:'The ambiguous case arises with', options:['SSS','SAS','SSA','ASA'], answer:2, explain:'Two sides + non-included angle can give two possible triangles.'},
{q:'SSA is not a congruence test because', options:['it needs angles','two different triangles are possible','it is too hard','sides are unequal'], answer:1, explain:'The ambiguous case means SSA does not guarantee uniqueness.'},
{q:'An angle bisector is constructed with', options:['protractor only','compass and ruler','set square only','freehand'], answer:1, explain:'Classical constructions use only compass and straightedge.'},
{q:'The centre of a circle through three points is found by', options:['joining the points','intersecting two perpendicular bisectors','drawing tangents','guessing'], answer:1, explain:'The circumcentre is equidistant from all three vertices.'},
{q:'A perpendicular bisector is drawn', options:['at 45°','at 90° through the midpoint','along the segment','through one end'], answer:1, explain:'It cuts the segment at right angles at its middle.'},
{q:'In SSS construction, the arcs are drawn with radii equal to', options:['the base','the other two sides','half the base','any length'], answer:1, explain:'Arcs of the two side-lengths from each base endpoint meet at the third vertex.'},
{q:'A parallelogram can be constructed using the property that', options:['all sides are equal','opposite sides are parallel and equal','angles are 90°','diagonals are equal'], answer:1, explain:'Parallel-and-equal opposite sides define a parallelogram.'},
{q:'How many triangles can SSA data produce?', options:['always one','zero, one or two','always two','infinitely many'], answer:1, explain:'Depending on measurements: none, one, or two (ambiguous).'},
{q:'Construction of a 60° angle uses', options:['a protractor','an equilateral triangle arc','a set square','estimation'], answer:1, explain:'Arcs of equal radius from the vertex give a perfect 60°.'}]},
{id:'bal-c9-mat-ch11', title:'Basic Statistics', urdu:'بنیادی شماریات', comingSoon:false, lessons:[
{id:'bal-c9-mat-ch11-l1', title:'Data and Grouped Data', html:'<h3>Data</h3><p><strong>Statistics</strong> collects, organises and interprets data. <strong>Ungrouped data</strong> lists every value; <strong>grouped data</strong> collects values into <strong>class intervals</strong> (e.g. 10–20, 20–30) shown in a <strong>frequency table</strong>.</p>'},
{id:'bal-c9-mat-ch11-l2', title:'Mean, Median and Mode', html:'<h3>Measures of Central Tendency</h3><ul><li><strong>Mean:</strong> sum ÷ count. For 4, 6, 8: mean = 6.</li><li><strong>Median:</strong> middle value when ordered (average the two middles if even count).</li><li><strong>Mode:</strong> most frequent value.</li></ul><p>Mean is affected by extreme values; median resists them.</p>'},
{id:'bal-c9-mat-ch11-l3', title:'Probability and Relative Frequency', html:'<h3>Probability</h3><p><strong>Probability</strong> = favourable outcomes ÷ total outcomes. A fair coin: P(head) = ½.</p><p><strong>Relative frequency</strong> = observed frequency ÷ total trials — used to <strong>estimate</strong> probability from experiments (tossing a coin 100 times, 53 heads → ≈ 0.53).</p>'}],
quiz:[
{q:'Statistics is the science of', options:['numbers only','collecting, organising and interpreting data','drawing only','guessing'], answer:1, explain:'Statistics covers collection, presentation, analysis and interpretation.'},
{q:'Mean of 4, 6, 8 is', options:['4','6','8','18'], answer:1, explain:'(4+6+8) ÷ 3 = 6.'},
{q:'Median of 3, 9, 5, 1, 7 is', options:['3','5','7','9'], answer:1, explain:'Ordered: 1, 3, 5, 7, 9 — middle is 5.'},
{q:'Mode of 2, 5, 5, 7, 5, 9 is', options:['2','5','7','9'], answer:1, explain:'5 occurs most often (3 times).'},
{q:'Grouped data uses', options:['raw lists','class intervals and frequencies','only graphs','no numbers'], answer:1, explain:'Values are grouped into intervals with frequencies.'},
{q:'Probability of a head with a fair coin is', options:['1','1/2','1/3','2'], answer:1, explain:'One favourable of two equally likely outcomes.'},
{q:'Relative frequency equals', options:['total ÷ frequency','observed frequency ÷ total trials','mean ÷ median','probability × 2'], answer:1, explain:'It estimates probability from actual experiment results.'},
{q:'Tossing a coin 100 times gives 53 heads. Estimated P(head) is', options:['0.5','0.53','53','1'], answer:1, explain:'Relative frequency = 53/100 = 0.53.'},
{q:'Which average is least affected by extreme values?', options:['mean','median','range','total'], answer:1, explain:'The median depends on position, not extreme magnitudes.'},
{q:'Probability values lie between', options:['−1 and 1','0 and 1','0 and 100','1 and 10'], answer:1, explain:'Probability ranges from 0 (impossible) to 1 (certain).'}]}
]});
