window.__saMergeCourse({id:'bal-class10-physics', board:'balochistan', title:'Physics', urdu:'طبیعیات', class:'Class 10', icon:'⚛️', desc:'Balochistan Board Class 10 Physics — full syllabus with lessons and quizzes.', chapters:[
{id:'bal-c10-phy-ch1', title:'Simple Harmonic Motion and Waves', urdu:'سادہ ہم آہنگ حرکت اور موجیں', comingSoon:false, lessons:[
{id:'bal-c10-phy-ch1-l1', title:'Simple Harmonic Motion', html:'<h3>Simple Harmonic Motion (SHM)</h3><p><strong>SHM</strong> is to-and-fro motion in which acceleration is proportional to displacement and always directed toward the mean position: a = −ω²x. Examples: a mass on a spring, a simple pendulum (for small angles).</p><p><strong>Damped motion:</strong> oscillations die out as friction removes energy — like a swinging door coming to rest.</p>'},
{id:'bal-c10-phy-ch1-l2', title:'Wave Motion', html:'<h3>Waves</h3><p>A <strong>wave</strong> carries energy without carrying matter. <strong>Mechanical waves</strong> need a medium (sound, water); <strong>electromagnetic waves</strong> do not (light).</p><p><strong>Transverse</strong> waves vibrate perpendicular to travel (rope wave); <strong>longitudinal</strong> vibrate parallel (sound — compressions and rarefactions).</p>'},
{id:'bal-c10-phy-ch1-l3', title:'Wave Characteristics', html:'<h3>Wave Terms</h3><ul><li><strong>Wavelength (λ):</strong> distance between two crests.</li><li><strong>Frequency (f):</strong> waves per second (Hz).</li><li><strong>Amplitude:</strong> maximum displacement.</li><li><strong>Speed:</strong> v = fλ.</li></ul><p>A sound wave of 340 Hz with λ = 1 m travels at 340 m/s.</p>'}],
quiz:[
{q:'In SHM, acceleration is', options:['constant','proportional to displacement, toward the mean','zero','away from the mean'], answer:1, explain:'SHM: a = −ω²x — proportional to displacement, opposite in direction.'},
{q:'Which is an example of SHM?', options:['a car on a road','a mass on a spring','a falling stone','a rolling ball'], answer:1, explain:'A mass on a spring oscillates to and fro about mean position.'},
{q:'Damped motion means oscillations', options:['grow bigger','die out due to friction','stay constant','stop instantly'], answer:1, explain:'Damping removes energy, shrinking the amplitude.'},
{q:'Sound waves are', options:['transverse','longitudinal','electromagnetic','stationary'], answer:1, explain:'Sound is compressions and rarefactions — longitudinal.'},
{q:'Which wave needs no medium?', options:['sound','water wave','light','seismic wave'], answer:2, explain:'Light is electromagnetic and travels through vacuum.'},
{q:'The wave equation is', options:['v = f/λ','v = fλ','v = λ/f','v = f + λ'], answer:1, explain:'Wave speed = frequency × wavelength.'},
{q:'A 340 Hz wave with 1 m wavelength has speed', options:['34 m/s','340 m/s','3400 m/s','1 m/s'], answer:1, explain:'v = fλ = 340 × 1 = 340 m/s.'},
{q:'Frequency is measured in', options:['metres','hertz','seconds','joules'], answer:1, explain:'Frequency unit is the hertz (Hz) — cycles per second.'},
{q:'In a transverse wave, particles vibrate', options:['along the wave direction','perpendicular to wave direction','not at all','in circles only'], answer:1, explain:'Transverse = perpendicular vibration, e.g. a rope wave.'},
{q:'Amplitude of a wave is its', options:['speed','maximum displacement','wavelength','frequency'], answer:1, explain:'Amplitude measures the maximum displacement from rest.'}]},
{id:'bal-c10-phy-ch2', title:'Sound', urdu:'آواز', comingSoon:false, lessons:[
{id:'bal-c10-phy-ch2-l1', title:'Nature of Sound Waves', html:'<h3>Sound</h3><p><strong>Sound</strong> is a <strong>longitudinal</strong> mechanical wave needing a medium — it cannot travel in vacuum. <strong>Sound waves</strong> are produced by vibrating bodies (vocal cords, tabla skin).</p><p><strong>Ultrasound</strong> (&gt; 20000 Hz) is used in medical scans and sonar; <strong>infrasound</strong> (&lt; 20 Hz) is made by earthquakes and elephants.</p>'},
{id:'bal-c10-phy-ch2-l2', title:'Characteristics of Sound', html:'<h3>Loudness, Pitch and Quality</h3><ul><li><strong>Loudness</strong> — depends on <strong>amplitude</strong>; measured in <strong>decibels (dB)</strong>.</li><li><strong>Pitch</strong> — depends on <strong>frequency</strong>; high frequency = shrill sound.</li><li><strong>Quality (timbre)</strong> — distinguishes instruments playing the same note.</li></ul><p><strong>Intensity</strong> is power per unit area (W/m²).</p>'},
{id:'bal-c10-phy-ch2-l3', title:'Speed, Echo and Acoustics', html:'<h3>Speed and Reflection</h3><p>Speed of sound in air ≈ <strong>343 m/s</strong> (faster in solids). An <strong>echo</strong> is sound reflected from a surface; the minimum distance for a clear echo is about 17 m.</p><p><strong>Acoustics</strong> is the science of sound in buildings — halls use absorbent materials to control echoes. Bats navigate by <strong>echolocation</strong>.</p>'}],
quiz:[
{q:'Sound cannot travel through', options:['air','water','vacuum','steel'], answer:2, explain:'Sound needs a material medium; vacuum has none.'},
{q:'Sound waves are', options:['transverse','longitudinal','electromagnetic','torsional'], answer:1, explain:'Sound travels as compressions and rarefactions.'},
{q:'Ultrasound has frequency', options:['below 20 Hz','20–20000 Hz','above 20000 Hz','exactly 20000 Hz'], answer:2, explain:'Ultrasound is above the human hearing range (> 20 kHz).'},
{q:'Loudness depends on', options:['frequency','amplitude','wavelength','speed'], answer:1, explain:'Greater amplitude means louder sound.'},
{q:'Pitch depends on', options:['amplitude','frequency','medium','temperature'], answer:1, explain:'Higher frequency gives a higher (shriller) pitch.'},
{q:'Loudness is measured in', options:['hertz','decibels','watts','metres'], answer:1, explain:'The decibel (dB) measures sound level.'},
{q:'Speed of sound in air is about', options:['3 × 10⁸ m/s','343 m/s','1500 m/s','3 m/s'], answer:1, explain:'≈ 343 m/s at room temperature.'},
{q:'An echo is', options:['a new sound','reflected sound','absorbed sound','faster sound'], answer:1, explain:'Echo = sound reflected from a distant surface.'},
{q:'Bats navigate using', options:['light','echolocation','magnetism','smell'], answer:1, explain:'Bats emit ultrasound and listen for echoes.'},
{q:'Infrasound is produced by', options:['dogs whistling','earthquakes','bats','medical scans'], answer:1, explain:'Infrasound (< 20 Hz) comes from earthquakes and storms.'}]},
{id:'bal-c10-phy-ch3', title:'Geometrical Optics', urdu:'جیومیٹریکل آپٹکس', comingSoon:false, lessons:[
{id:'bal-c10-phy-ch3-l1', title:'Reflection of Light', html:'<h3>Reflection</h3><p><strong>Laws of reflection:</strong> (1) angle of incidence = angle of reflection; (2) incident ray, reflected ray and normal lie in one plane.</p><p><strong>Spherical mirrors:</strong> <strong>concave</strong> converge light (used in headlights, shaving mirrors); <strong>convex</strong> diverge light (car side mirrors — wider view).</p>'},
{id:'bal-c10-phy-ch3-l2', title:'Refraction and Total Internal Reflection', html:'<h3>Refraction</h3><p><strong>Refraction</strong> is the bending of light passing between media — caused by speed change. A straw looks bent in water.</p><p><strong>Total internal reflection:</strong> when light in a denser medium hits the boundary above the <strong>critical angle</strong>, it reflects fully inside. Used in <strong>optical fibres</strong> and sparkling diamonds.</p>'},
{id:'bal-c10-phy-ch3-l3', title:'Lenses and Optical Instruments', html:'<h3>Lenses</h3><p><strong>Convex (converging)</strong> lenses focus light — used in cameras and magnifiers. <strong>Concave (diverging)</strong> lenses spread light — used in some spectacles.</p><p><strong>Lens formula:</strong> 1/f = 1/v − 1/u. The <strong>human eye</strong> focuses with a convex lens; the retina detects the image. <strong>Mirages</strong> form by total internal reflection in hot air.</p>'}],
quiz:[
{q:'The first law of reflection states', options:['i > r','angle of incidence = angle of reflection','light bends','i + r = 90°'], answer:1, explain:'Angle of incidence always equals angle of reflection.'},
{q:'A concave mirror', options:['diverges light','converges light','absorbs light','has no focus'], answer:1, explain:'Concave mirrors bring parallel rays to a focus.'},
{q:'Car side mirrors are convex because they', options:['magnify','give a wider field of view','are cheaper','never fog'], answer:1, explain:'Convex mirrors diverge rays, showing more area (smaller image).'},
{q:'Refraction is caused by', options:['colour change','change in light speed between media','reflection','absorption'], answer:1, explain:'Different speeds bend the ray at the boundary.'},
{q:'Total internal reflection needs', options:['a rare medium only','angle greater than the critical angle in denser medium','a mirror','coloured light'], answer:1, explain:'Beyond the critical angle, light cannot escape the denser medium.'},
{q:'Optical fibres work on', options:['refraction','total internal reflection','diffraction','polarisation'], answer:1, explain:'Light bounces inside the fibre by repeated total internal reflection.'},
{q:'A convex lens is used in', options:['car side mirrors','cameras','peepholes','rear windows'], answer:1, explain:'Cameras focus images with converging lenses.'},
{q:'The lens formula is', options:['1/f = 1/v + 1/u','1/f = 1/v − 1/u','f = uv','1/f = u − v'], answer:1, explain:'With sign conventions, 1/f = 1/v − 1/u.'},
{q:'The image on the human retina is', options:['erect and real','inverted and real','virtual','not formed'], answer:1, explain:'The eye lens forms a real inverted image; the brain interprets it.'},
{q:'A mirage is caused by', options:['reflection from water','total internal reflection in hot air layers','clouds','dust'], answer:1, explain:'Hot air near the ground totally reflects sky light upward.'}]},
{id:'bal-c10-phy-ch4', title:'Electrostatics', urdu:'الیکٹرو اسٹیٹکس', comingSoon:false, lessons:[
{id:'bal-c10-phy-ch4-l1', title:'Static Charge', html:'<h3>Static Electricity</h3><p>Rubbing transfers electrons: glass rubbed with silk becomes <strong>positive</strong>, ebonite with fur becomes <strong>negative</strong>. Like charges <strong>repel</strong>, unlike <strong>attract</strong>.</p><p><strong>Electrostatic induction:</strong> a charged rod attracts a neutral body by separating its charges. The <strong>electroscope</strong> detects charge — its leaves diverge when charged.</p>'},
{id:'bal-c10-phy-ch4-l2', title:'Coulomb’s Law and Electric Field', html:'<h3>Coulomb’s Law</h3><p>Force between two charges: <strong>F = kq₁q₂/r²</strong> — proportional to charges, inverse-square of distance.</p><p><strong>Electric field</strong> is the region where a charge feels force. <strong>Electric intensity E = F/q</strong> (N/C). Field lines go from positive to negative charges.</p>'},
{id:'bal-c10-phy-ch4-l3', title:'Applications of Electrostatics', html:'<h3>Uses</h3><ul><li><strong>Photocopiers and laser printers</strong> — charged toner attracted to an image.</li><li><strong>Electrostatic precipitators</strong> — clean smoke in chimneys.</li><li><strong>Spray painting</strong> — charged paint coats evenly.</li></ul><p><strong>Lightning</strong> is a giant static discharge; <strong>lightning conductors</strong> protect buildings. <strong>Electrical breakdown</strong> of air occurs at very high fields.</p>'}],
quiz:[
{q:'Glass rubbed with silk becomes', options:['negative','positive','neutral','magnetic'], answer:1, explain:'Glass loses electrons to silk, becoming positive.'},
{q:'Like charges', options:['attract','repel','have no effect','combine'], answer:1, explain:'Like charges repel; unlike charges attract.'},
{q:'An electroscope is used to', options:['measure current','detect electric charge','measure voltage','store charge'], answer:1, explain:'Its leaves diverge when charge is present.'},
{q:'Coulomb’s law: F is proportional to', options:['1/r','q₁q₂/r²','r²','q₁+q₂'], answer:1, explain:'F = kq₁q₂/r².'},
{q:'If the distance between charges doubles, the force becomes', options:['double','half','one-fourth','four times'], answer:2, explain:'Inverse-square: (1/2)² = 1/4.'},
{q:'SI unit of electric charge is', options:['ampere','coulomb','volt','ohm'], answer:1, explain:'Charge is measured in coulombs (C).'},
{q:'Electric field lines go', options:['negative to positive','positive to negative','in circles','nowhere'], answer:1, explain:'By convention, lines leave positive and enter negative charges.'},
{q:'Photocopiers use', options:['magnets','electrostatics','gravity','sound'], answer:1, explain:'Charged toner sticks to the charged image areas.'},
{q:'Lightning is', options:['a magnetic storm','a giant static electric discharge','sound waves','heat'], answer:1, explain:'Charge build-up in clouds discharges as lightning.'},
{q:'Electrostatic induction can', options:['create charge','separate charges in a neutral body','destroy charge','magnetise iron'], answer:1, explain:'A nearby charge redistributes a neutral body’s charges.'}]},
{id:'bal-c10-phy-ch5', title:'Current Electricity', urdu:'کرنٹ الیکٹرسٹی', comingSoon:false, lessons:[
{id:'bal-c10-phy-ch5-l1', title:'Electric Current and EMF', html:'<h3>Current</h3><p><strong>Electric current</strong> is charge flowing per second: <strong>I = Q/t</strong>, measured in <strong>amperes (A)</strong>. <strong>Conventional current</strong> flows from positive to negative (opposite to electron flow).</p><p><strong>EMF</strong> is the energy per coulomb a source provides; <strong>potential difference (V)</strong> is energy per coulomb between two points.</p>'},
{id:'bal-c10-phy-ch5-l2', title:'Ohm’s Law, Resistance and Resistivity', html:'<h3>Ohm’s Law</h3><p><strong>V = IR</strong> — voltage across a conductor is proportional to current. <strong>Resistance</strong> (ohm, Ω) opposes current.</p><p><strong>Resistivity</strong> is a material property: R = ρL/A. Longer wire or thinner wire = more resistance. Copper has low resistivity — ideal for wires.</p>'},
{id:'bal-c10-phy-ch5-l3', title:'Measuring Instruments', html:'<h3>Meters</h3><ul><li><strong>Ammeter</strong> — measures current; connected in <strong>series</strong>.</li><li><strong>Voltmeter</strong> — measures voltage; connected in <strong>parallel</strong>.</li><li><strong>Galvanometer</strong> — detects small currents.</li></ul><p>A 12 V battery pushing 2 A through a resistor means R = V/I = 6 Ω.</p>'}],
quiz:[
{q:'Electric current is defined as', options:['voltage × time','charge ÷ time','resistance × voltage','energy ÷ charge'], answer:1, explain:'I = Q/t — coulombs per second = amperes.'},
{q:'Conventional current flows', options:['negative to positive','positive to negative','both ways','in circles'], answer:1, explain:'Conventional current is defined positive → negative.'},
{q:'Ohm’s law states', options:['V = I/R','V = IR','I = VR','R = VI'], answer:1, explain:'Voltage = current × resistance.'},
{q:'SI unit of resistance is', options:['volt','ampere','ohm','watt'], answer:2, explain:'Resistance is measured in ohms (Ω).'},
{q:'A 12 V battery drives 2 A through a resistor. R equals', options:['24 Ω','6 Ω','0.17 Ω','12 Ω'], answer:1, explain:'R = V/I = 12/2 = 6 Ω.'},
{q:'Resistance of a wire increases when it is made', options:['shorter','longer and thinner','thicker','colder'], answer:1, explain:'R = ρL/A — longer length and smaller area raise resistance.'},
{q:'An ammeter is connected in', options:['parallel','series','any way','reverse'], answer:1, explain:'Current must flow through the ammeter — series connection.'},
{q:'A voltmeter is connected in', options:['series','parallel','series-parallel','reverse'], answer:1, explain:'It measures voltage across a component — parallel.'},
{q:'EMF is', options:['a force','energy per unit charge from a source','current','resistance'], answer:1, explain:'EMF = joules per coulomb supplied by the source.'},
{q:'Copper is used for wires because of its', options:['high resistivity','low resistivity','high density','colour'], answer:1, explain:'Low resistivity means little energy lost as heat.'}]},
{id:'bal-c10-phy-ch6', title:'Electromagnetism', urdu:'برقی مقناطیسیت', comingSoon:false, lessons:[
{id:'bal-c10-phy-ch6-l1', title:'Magnetic Field of a Current', html:'<h3>Electricity Makes Magnetism</h3><p>A <strong>current-carrying wire</strong> produces a magnetic field around it (Oersted). A <strong>solenoid</strong> (coil) acts like a bar magnet; more turns or current = stronger field.</p><p>An <strong>electromagnet</strong> (soft-iron core in a solenoid) can be switched on and off — used in cranes and bells.</p>'},
{id:'bal-c10-phy-ch6-l2', title:'Force on a Current-Carrying Conductor', html:'<h3>Motor Effect</h3><p>A current-carrying conductor in a magnetic field feels a <strong>force</strong> (Fleming’s left-hand rule). This is the <strong>electric motor</strong> principle — electrical energy → mechanical energy.</p><p><strong>Electromagnetic induction:</strong> moving a magnet near a coil <strong>induces</strong> current (Faraday). <strong>Lenz’s law:</strong> the induced current opposes the change causing it.</p>'},
{id:'bal-c10-phy-ch6-l3', title:'Generators, Transformers and CRO', html:'<h3>Applications</h3><ul><li><strong>Electric generator:</strong> mechanical → electrical energy.</li><li><strong>Transformer:</strong> changes AC voltage (works on mutual induction); step-up raises voltage for transmission.</li><li><strong>Cathode ray oscilloscope (CRO):</strong> displays waveforms; electron beam deflected by electric/magnetic fields.</li></ul>'}],
quiz:[
{q:'A current-carrying straight wire produces', options:['no field','a magnetic field around it','an electric field only','light'], answer:1, explain:'Oersted discovered the magnetic effect of current.'},
{q:'A solenoid with an iron core carrying current is an', options:['permanent magnet','electromagnet','generator','motor'], answer:1, explain:'The coil magnetises the core while current flows.'},
{q:'An electric motor converts', options:['mechanical to electrical','electrical to mechanical','heat to light','chemical to heat'], answer:1, explain:'Motor effect: current in a field produces motion.'},
{q:'Electromagnetic induction was discovered by', options:['Oersted','Faraday','Ampere','Ohm'], answer:1, explain:'Faraday found that changing magnetism induces current.'},
{q:'Lenz’s law states the induced current', options:['helps the change','opposes the change producing it','is always zero','flows randomly'], answer:1, explain:'Induced effects oppose their cause — conservation of energy.'},
{q:'A generator converts', options:['electrical to mechanical','mechanical to electrical','chemical to light','heat to sound'], answer:1, explain:'Rotating a coil in a field generates electricity.'},
{q:'Transformers work on', options:['DC only','AC and mutual induction','static charge','batteries'], answer:1, explain:'Changing AC flux induces voltage in the second coil.'},
{q:'A step-up transformer', options:['raises voltage','lowers voltage','stores charge','makes DC'], answer:0, explain:'More secondary turns give higher voltage (lower current).'},
{q:'The CRO displays', options:['sound','electrical waveforms','magnetic fields','light spectra'], answer:1, explain:'The cathode ray oscilloscope traces voltage against time.'},
{q:'Fleming’s left-hand rule gives the direction of', options:['induced current','force on a current-carrying conductor','field lines','electron flow'], answer:1, explain:'First finger field, second current, thumb force.'}]},
{id:'bal-c10-phy-ch7', title:'Basic Electronics', urdu:'بنیادی الیکٹرانکس', comingSoon:false, lessons:[
{id:'bal-c10-phy-ch7-l1', title:'Thermionic Emission and Cathode Rays', html:'<h3>Electrons from Hot Metals</h3><p><strong>Thermionic emission:</strong> heating a metal filament gives electrons enough energy to escape. An <strong>electron gun</strong> accelerates them into a beam.</p><p><strong>Cathode rays</strong> are streams of fast electrons — they travel straight, carry negative charge and are deflected by electric and magnetic fields.</p>'},
{id:'bal-c10-phy-ch7-l2', title:'Semiconductors, Diodes and Transistors', html:'<h3>Semiconductor Devices</h3><ul><li><strong>Semiconductors</strong> (silicon): conductivity between conductors and insulators.</li><li><strong>Diode (p-n junction):</strong> conducts one way only — used in <strong>rectification</strong> (AC → DC). <strong>LEDs</strong> emit light.</li><li><strong>Transistor:</strong> three-layer device used as a <strong>switch</strong> and <strong>amplifier</strong>.</li></ul>'},
{id:'bal-c10-phy-ch7-l3', title:'Digital Electronics and Logic Gates', html:'<h3>Logic Gates</h3><p><strong>Digital electronics</strong> uses binary (0/1). Basic <strong>logic gates</strong>:</p><table><tr><th>Gate</th><th>Output is 1 when</th></tr><tr><td>AND</td><td>all inputs are 1</td></tr><tr><td>OR</td><td>any input is 1</td></tr><tr><td>NOT</td><td>input is 0</td></tr></table><p><strong>NAND/NOR</strong> are universal gates. <strong>Analogue</strong> signals vary continuously; <strong>digital</strong> signals are discrete steps.</p>'}],
quiz:[
{q:'Thermionic emission is the release of electrons from', options:['cold metal','a heated metal filament','a magnet','water'], answer:1, explain:'Heat gives electrons energy to escape the metal.'},
{q:'Cathode rays are streams of', options:['protons','electrons','neutrons','photons'], answer:1, explain:'Cathode rays are fast-moving electrons.'},
{q:'Silicon is a', options:['conductor','insulator','semiconductor','superconductor'], answer:2, explain:'Its conductivity lies between conductors and insulators.'},
{q:'A diode conducts current', options:['both ways','only one way','never','in circles'], answer:1, explain:'The p-n junction allows one-way flow — used for rectification.'},
{q:'Rectification converts', options:['DC to AC','AC to DC','high to low voltage','sound to light'], answer:1, explain:'Diodes turn alternating current into direct current.'},
{q:'An LED', options:['detects light','emits light when current passes','stores charge','amplifies'], answer:1, explain:'Light-emitting diodes glow when forward-biased.'},
{q:'A transistor can act as', options:['a wire only','a switch and an amplifier','a battery','a fuse'], answer:1, explain:'Transistors switch and amplify signals — the basis of computers.'},
{q:'An AND gate outputs 1 when', options:['any input is 1','all inputs are 1','inputs differ','input is 0'], answer:1, explain:'AND needs every input high.'},
{q:'A NOT gate', options:['adds inputs','inverts the input','multiplies','stores data'], answer:1, explain:'NOT outputs the opposite of its input.'},
{q:'Digital signals are', options:['continuous waves','discrete 0/1 steps','always loud','analogue'], answer:1, explain:'Digital = binary on/off levels.'}]},
{id:'bal-c10-phy-ch8', title:'Information Technology', urdu:'انفارمیشن ٹیکنالوجی', comingSoon:false, lessons:[
{id:'bal-c10-phy-ch8-l1', title:'What is Information Technology?', html:'<h3>Information Technology (IT)</h3><p><strong>IT</strong> is the use of computers and telecommunication to store, process and share information. A <strong>computer-based information system (CBIS)</strong> has hardware, software, data, people and procedures.</p><p>From mobile banking to online classes, IT touches every part of modern life.</p>'},
{id:'bal-c10-phy-ch8-l2', title:'The Internet and its Services', html:'<h3>Internet</h3><p>The <strong>Internet</strong> is a global network of connected computers. <strong>Services:</strong> the <strong>World Wide Web</strong> (websites via browsers), <strong>email</strong>, video calls, cloud storage and online learning.</p><p>Data travels as signals through wires, <strong>optical fibres</strong> (light pulses — fast and high capacity) and wireless waves.</p>'},
{id:'bal-c10-phy-ch8-l3', title:'Uses and Safe Use of IT', html:'<h3>IT in Daily Life</h3><ul><li>Education: online lectures, e-books, quizzes.</li><li>Health: telemedicine, digital records.</li><li>Business: e-commerce, digital payments.</li></ul><p><strong>Stay safe:</strong> use strong passwords, avoid suspicious links, protect personal data and respect others online.</p>'}],
quiz:[
{q:'IT stands for', options:['Internet Transfer','Information Technology','Internal Testing','Input Terminal'], answer:1, explain:'Information Technology.'},
{q:'A CBIS includes', options:['only hardware','hardware, software, data, people and procedures','only software','only people'], answer:1, explain:'A computer-based information system combines all five components.'},
{q:'The World Wide Web is', options:['the Internet itself','websites accessed through browsers','only email','a single computer'], answer:1, explain:'The Web is the system of linked pages on the Internet.'},
{q:'Optical fibres carry data as', options:['electrons','light pulses','sound','water'], answer:1, explain:'Light signals in glass fibres give fast, high-capacity links.'},
{q:'Email is a service for', options:['phone calls','sending messages electronically','printing','gaming only'], answer:1, explain:'Electronic mail sends messages over networks.'},
{q:'Telemedicine uses IT for', options:['farming','remote medical care','cooking','sports'], answer:1, explain:'Doctors consult patients at a distance via IT.'},
{q:'A strong password should be', options:['your name','long, mixed characters','12345','shared with friends'], answer:1, explain:'Long, mixed passwords resist guessing.'},
{q:'E-commerce means', options:['electronic voting','buying and selling online','email','online games'], answer:1, explain:'E-commerce is trade conducted over the Internet.'},
{q:'Browsers are used to', options:['write code only','access websites','cool computers','print pages only'], answer:1, explain:'Web browsers display websites.'},
{q:'Protecting personal data online is important because', options:['it saves time','it prevents misuse and fraud','it speeds the Internet','it is fashionable'], answer:1, explain:'Data protection guards against identity theft and fraud.'}]},
{id:'bal-c10-phy-ch9', title:'Atomic and Nuclear Physics', urdu:'ایٹمی اور نیوکلیائی طبیعیات', comingSoon:false, lessons:[
{id:'bal-c10-phy-ch9-l1', title:'Atom and Atomic Nucleus', html:'<h3>The Nucleus</h3><p>The <strong>nucleus</strong> (protons + neutrons) holds nearly all the atom’s mass in a tiny volume. <strong>Atomic number (Z)</strong> = protons; <strong>mass number (A)</strong> = protons + neutrons.</p><p><strong>Isotopes</strong> (same Z, different neutrons) include stable ones and <strong>radioisotopes</strong> like carbon-14.</p>'},
{id:'bal-c10-phy-ch9-l2', title:'Natural Radioactivity and Half-Life', html:'<h3>Radioactivity</h3><p><strong>Natural radioactivity:</strong> unstable nuclei decay, emitting <strong>alpha</strong> (helium nuclei), <strong>beta</strong> (electrons) or <strong>gamma</strong> (high-energy EM waves) radiation. <strong>Background radiation</strong> comes from rocks, cosmic rays and even bananas.</p><p><strong>Half-life</strong> = time for half the nuclei to decay. Carbon-14’s half-life (5730 years) dates ancient remains.</p>'},
{id:'bal-c10-phy-ch9-l3', title:'Fission, Fusion and Uses', html:'<h3>Nuclear Reactions</h3><ul><li><strong>Fission:</strong> heavy nucleus splits (uranium-235) — releases huge energy; used in <strong>nuclear power plants</strong>.</li><li><strong>Fusion:</strong> light nuclei join (hydrogen → helium) — powers the <strong>Sun</strong>; E = mc².</li></ul><p><strong>Radioisotopes</strong> are used in medicine (cancer treatment, scans), industry and agriculture. <strong>Safety:</strong> minimise time, maximise distance and use shielding (lead) against radiations.</p>'}],
quiz:[
{q:'The nucleus contains', options:['protons and electrons','protons and neutrons','electrons only','neutrons and electrons'], answer:1, explain:'Protons and neutrons make up the nucleus.'},
{q:'Atomic number equals the number of', options:['neutrons','protons','electrons + neutrons','isotopes'], answer:1, explain:'Z = number of protons, defining the element.'},
{q:'Alpha radiation consists of', options:['electrons','helium nuclei','EM waves','neutrons'], answer:1, explain:'Alpha particles are helium-4 nuclei.'},
{q:'Gamma rays are', options:['particles','high-energy electromagnetic waves','electrons','protons'], answer:1, explain:'Gamma is penetrating EM radiation from the nucleus.'},
{q:'Half-life is the time for', options:['all atoms to decay','half the nuclei to decay','one atom to decay','radiation to stop'], answer:1, explain:'After one half-life, half the original nuclei remain.'},
{q:'Carbon-14 dating works because of its', options:['long half-life of 5730 years','short half-life','stable nucleus','abundance'], answer:0, explain:'Its 5730-year half-life suits dating ancient organic remains.'},
{q:'Nuclear fission is', options:['joining of nuclei','splitting of a heavy nucleus','electron capture','chemical burning'], answer:1, explain:'Fission splits heavy nuclei like U-235, releasing energy.'},
{q:'The Sun’s energy comes from', options:['fission','fusion','burning coal','chemical reactions'], answer:1, explain:'Hydrogen fusion into helium powers the Sun (E = mc²).'},
{q:'Radioisotopes are used in medicine for', options:['only X-rays','cancer treatment and scans','surgery tools','bandages'], answer:1, explain:'Targeted radiation treats tumours; tracers image organs.'},
{q:'Protection from radiation includes', options:['more time near source','lead shielding and distance','looking at it','heating it'], answer:1, explain:'Time, distance and shielding minimise dose.'}]}
]});
/* ================= BALOCHISTAN BOARD — CLASS 10 CHEMISTRY ================= */
window.__saMergeCourse({id:'bal-class10-chemistry', board:'balochistan', title:'Chemistry', urdu:'کیمسٹری', class:'Class 10', icon:'🧪', desc:'Balochistan Board Class 10 Chemistry — full syllabus with lessons and quizzes.', chapters:[
{id:'bal-c10-che-ch1', title:'Chemical Equilibrium', urdu:'کیمیائی توازن', comingSoon:false, lessons:[
{id:'bal-c10-che-ch1-l1', title:'Reversible Reactions and Dynamic Equilibrium', html:'<h3>Equilibrium Basics</h3><p>In a <strong>closed system</strong>, reversible reactions (⇌) reach <strong>dynamic equilibrium</strong> — forward and reverse rates are equal, so concentrations stay constant while both reactions continue.</p><p>Example: N₂ + 3H₂ ⇌ 2NH₃.</p>'},
{id:'bal-c10-che-ch1-l2', title:'Law of Mass Action and Equilibrium Constant', html:'<h3>Equilibrium Constant</h3><p><strong>Law of mass action:</strong> rate is proportional to reactant concentrations. For aA + bB ⇌ cC + dD: <strong>Kc = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ</strong>.</p><p>Large Kc → products favoured; small Kc → reactants favoured. Units depend on the reaction’s stoichiometry.</p>'},
{id:'bal-c10-che-ch1-l3', title:'Importance and Shifting Equilibrium', html:'<h3>Using Equilibrium</h3><p>Kc predicts reaction direction and yield. <strong>Le Chatelier:</strong> more reactant or higher pressure (fewer gas moles) shifts toward products — the basis of the <strong>Haber process</strong> for ammonia and the <strong>Contact process</strong> for sulphuric acid.</p>'}],
quiz:[
{q:'Dynamic equilibrium occurs in a', options:['open system','closed system','hot system','large flask'], answer:1, explain:'Nothing may escape, or equilibrium cannot establish.'},
{q:'At equilibrium, the rates of forward and reverse reactions are', options:['zero','equal','maximum','unequal'], answer:1, explain:'Equal opposing rates keep concentrations constant.'},
{q:'For aA + bB ⇌ cC + dD, Kc equals', options:['[A]ᵃ[B]ᵇ/[C]ᶜ[D]ᵈ','[C]ᶜ[D]ᵈ/[A]ᵃ[B]ᵇ','[A][B]/[C][D]','[C]+[D]/[A]+[B]'], answer:1, explain:'Kc = products over reactants, each raised to its coefficient.'},
{q:'A very large Kc means', options:['no reaction','products strongly favoured','reactants favoured','Kc = 0'], answer:1, explain:'Large Kc → equilibrium lies far to the right.'},
{q:'The law of mass action relates rate to', options:['temperature only','reactant concentrations','catalysts','volume only'], answer:1, explain:'Rate ∝ product of reactant concentrations.'},
{q:'The Haber process makes', options:['sulphuric acid','ammonia','nitric acid','urea directly'], answer:1, explain:'N₂ + 3H₂ ⇌ 2NH₃ is the Haber process.'},
{q:'High pressure favours ammonia because', options:['gases cool','4 gas moles become 2','catalyst works','it is cheaper'], answer:1, explain:'Fewer product gas moles → pressure shifts equilibrium right.'},
{q:'A catalyst in the Haber process', options:['shifts equilibrium right','speeds up reaching equilibrium','is consumed','changes Kc'], answer:1, explain:'Iron catalyst reaches equilibrium faster; position unchanged.'},
{q:'If Kc < 1, the mixture at equilibrium has', options:['more products','more reactants','equal amounts','no reaction'], answer:1, explain:'Small Kc means reactants dominate.'},
{q:'Concentrations at equilibrium are', options:['always equal','constant over time','zero','increasing'], answer:1, explain:'Constant (not necessarily equal) concentrations define equilibrium.'}]},
{id:'bal-c10-che-ch2', title:'Acids, Bases and Salts', urdu:'تیزاب، اساس اور نمکیات', comingSoon:false, lessons:[
{id:'bal-c10-che-ch2-l1', title:'Concepts of Acids and Bases', html:'<h3>Acid–Base Concepts</h3><ul><li><strong>Arrhenius:</strong> acids give H⁺, bases give OH⁻ in water.</li><li><strong>Brønsted–Lowry:</strong> acids donate protons, bases accept them.</li><li><strong>Lewis:</strong> acids accept electron pairs, bases donate them.</li></ul><p>NH₃ + H⁺ → NH₄⁺: ammonia is a Brønsted–Lowry base and a Lewis base.</p>'},
{id:'bal-c10-che-ch2-l2', title:'The pH Scale', html:'<h3>pH</h3><p><strong>pH = −log[H⁺]</strong>. Each pH unit is a 10× change in [H⁺]: pH 3 is 10× more acidic than pH 4.</p><p>Uses: soil testing for crops, swimming-pool water, blood pH (7.4) control, food preservation.</p>'},
{id:'bal-c10-che-ch2-l3', title:'Salts', html:'<h3>Salts</h3><p><strong>Salts</strong> form from acid–base neutralisation. Types: <strong>normal</strong> (NaCl), <strong>acidic</strong> (NaHSO₄), <strong>basic</strong> (Ca(OH)Cl), <strong>double</strong> (potash alum), <strong>complex</strong>, <strong>hydrated</strong> (CuSO₄·5H₂O).</p><p>Uses: NaCl (food), NaHCO₃ (baking), CaSO₄ (plaster), Na₂CO₃ (glass, soap).</p>'}],
quiz:[
{q:'Lewis acid is an', options:['proton donor','electron-pair acceptor','OH⁻ donor','proton acceptor'], answer:1, explain:'Lewis acids accept electron pairs.'},
{q:'NH₃ acting as a base accepts', options:['electrons','a proton','neutrons','OH⁻'], answer:1, explain:'NH₃ + H⁺ → NH₄⁺ — proton acceptance.'},
{q:'pH is defined as', options:['log[H⁺}','−log[H⁺]','[H⁺]²','1/[OH⁻]'], answer:1, explain:'pH = −log₁₀[H⁺].'},
{q:'pH 3 compared to pH 4 is', options:['equally acidic','10× more acidic','10× less acidic','100× more acidic'], answer:1, explain:'Each pH unit = 10× concentration change.'},
{q:'Normal human blood pH is about', options:['7.0','7.4','6.0','8.5'], answer:1, explain:'Blood is slightly basic at ~7.4.'},
{q:'Baking soda is', options:['NaCl','NaHCO₃','Na₂CO₃','CaO'], answer:1, explain:'Sodium hydrogen carbonate — baking soda.'},
{q:'Washing soda is', options:['NaHCO₃','Na₂CO₃·10H₂O','CaCO₃','NaCl'], answer:1, explain:'Sodium carbonate decahydrate is washing soda.'},
{q:'An acidic salt is', options:['NaCl','NaHSO₄','Na₂SO₄','KNO₃'], answer:1, explain:'NaHSO₄ still has replaceable H⁺ — acidic.'},
{q:'Plaster of Paris is made from', options:['NaCl','gypsum (CaSO₄·2H₂O)','sand','lime'], answer:1, explain:'Heated gypsum gives plaster of Paris.'},
{q:'Acid + base →', options:['salt + hydrogen','salt + water','base + water','acid + salt'], answer:1, explain:'Neutralisation always gives salt + water.'}]},
{id:'bal-c10-che-ch3', title:'Organic Chemistry', urdu:'نامیاتی کیمسٹری', comingSoon:false, lessons:[
{id:'bal-c10-che-ch3-l1', title:'Organic Compounds and Sources', html:'<h3>Organic Compounds</h3><p>Carbon compounds (with H) — from <strong>natural sources</strong> (petroleum, natural gas, coal, plants, animals) and <strong>synthetic</strong> manufacture.</p><p><strong>Uses:</strong> fuels, plastics, medicines, soaps, detergents, pesticides, dyes, fibres.</p>'},
{id:'bal-c10-che-ch3-l2', title:'Alkanes and Alkyl Radicals', html:'<h3>Alkanes</h3><p><strong>Saturated</strong> hydrocarbons, CₙH₂ₙ₊₂: methane, ethane, propane, butane. An <strong>alkyl radical</strong> is an alkane minus one H: methyl (CH₃–), ethyl (C₂H₅–).</p><p>Alkanes burn cleanly (fuels) but are otherwise unreactive — <strong>paraffins</strong>.</p>'},
{id:'bal-c10-che-ch3-l3', title:'Functional Groups and Isomerism', html:'<h3>Functional Groups</h3><p>–OH (alcohols), –COOH (acids), –CHO (aldehydes), &gt;C=O (ketones), –NH₂ (amines), –X (haloalkanes).</p><p><strong>Isomerism:</strong> same molecular formula, different arrangement — e.g. butane vs methylpropane (C₄H₁₀).</p>'}],
quiz:[
{q:'Organic compounds are compounds of', options:['silicon','carbon','iron','calcium'], answer:1, explain:'Organic chemistry = carbon compounds.'},
{q:'A major natural source of organic compounds is', options:['sand','petroleum','limestone','water'], answer:1, explain:'Petroleum and natural gas are rich hydrocarbon sources.'},
{q:'The general formula of alkanes is', options:['CₙH₂ₙ','CₙH₂ₙ₊₂','CₙH₂ₙ₋₂','CₙHₙ'], answer:1, explain:'Alkanes: CₙH₂ₙ₊₂.'},
{q:'The methyl radical is', options:['CH₄','CH₃–','C₂H₅–','CH₂'], answer:1, explain:'Methane minus one H gives methyl CH₃–.'},
{q:'Alkanes are also called paraffins because they are', options:['poisonous','very reactive','quite unreactive','coloured'], answer:2, explain:'Paraffin = “little affinity” — low reactivity.'},
{q:'Butane and methylpropane are', options:['isotopes','isomers','polymers','allotropes'], answer:1, explain:'Same formula C₄H₁₀, different structures — isomers.'},
{q:'The –CHO group belongs to', options:['ketones','aldehydes','acids','alcohols'], answer:1, explain:'–CHO is the aldehyde functional group.'},
{q:'Which is an alcohol?', options:['CH₃COOH','C₂H₅OH','CH₃CHO','CH₃Cl'], answer:1, explain:'–OH group marks ethanol as an alcohol.'},
{q:'Uses of organic compounds include', options:['only fuels','plastics, medicines, soaps, fuels','only food','only metals'], answer:1, explain:'Organics span fuels, polymers, drugs and detergents.'},
{q:'Ethyl radical formula is', options:['CH₃–','C₂H₅–','C₃H₇–','C₂H₄'], answer:1, explain:'Ethane (C₂H₆) minus one H = C₂H₅–.'}]},
{id:'bal-c10-che-ch4', title:'Hydrocarbons', urdu:'ہائیڈرو کاربنز', comingSoon:false, lessons:[
{id:'bal-c10-che-ch4-l1', title:'Classification of Hydrocarbons', html:'<h3>Hydrocarbon Families</h3><ul><li><strong>Aliphatic:</strong> open chains — alkanes, alkenes, alkynes.</li><li><strong>Alicyclic:</strong> rings of carbon (cyclohexane).</li><li><strong>Aromatic:</strong> benzene ring (C₆H₆) — special stability.</li></ul>'},
{id:'bal-c10-che-ch4-l2', title:'Alkanes, Alkenes and Alkynes', html:'<h3>Properties and Preparation</h3><ul><li><strong>Alkanes:</strong> substitution reactions (chlorination in sunlight).</li><li><strong>Alkenes:</strong> C=C; decolourise bromine water (test for unsaturation); undergo <strong>addition</strong> reactions; polymerise to polythene.</li><li><strong>Alkynes:</strong> C≡C; ethyne burns with a very hot flame (welding).</li></ul>'},
{id:'bal-c10-che-ch4-l3', title:'Uses of Hydrocarbons', html:'<h3>Uses</h3><ul><li><strong>Methane:</strong> natural gas fuel, CNG vehicles.</li><li><strong>Ethene:</strong> ripening fruit, making polythene.</li><li><strong>Ethyne:</strong> oxy-acetylene welding.</li><li><strong>Benzene:</strong> solvent, making plastics and dyes.</li></ul>'}],
quiz:[
{q:'Benzene (C₆H₆) is', options:['aliphatic','aromatic','alicyclic','inorganic'], answer:1, explain:'Benzene’s ring gives it aromatic character.'},
{q:'The test for unsaturation uses', options:['limewater','bromine water','litmus','silver nitrate'], answer:1, explain:'Alkenes decolourise brown bromine water.'},
{q:'Alkenes typically undergo', options:['substitution','addition reactions','no reactions','neutralisation'], answer:1, explain:'The double bond opens for addition.'},
{q:'Polythene is made by polymerisation of', options:['methane','ethene','benzene','ethyne'], answer:1, explain:'Ethene polymerises to polythene plastic.'},
{q:'Ethyne is used in', options:['cooking','oxy-acetylene welding','drinking','cooling'], answer:1, explain:'Its very hot flame cuts and welds metals.'},
{q:'General formula of alkynes is', options:['CₙH₂ₙ₊₂','CₙH₂ₙ','CₙH₂ₙ₋₂','CₙHₙ₊₁'], answer:2, explain:'Alkynes: CₙH₂ₙ₋₂.'},
{q:'Cyclohexane is', options:['aromatic','alicyclic','straight chain','an alkene'], answer:1, explain:'A ring of single-bonded carbons — alicyclic.'},
{q:'Methane is mainly used as', options:['a solvent','a fuel (natural gas/CNG)','a plastic','a medicine'], answer:1, explain:'Natural gas is mostly methane.'},
{q:'Chlorination of methane in sunlight is a', options:['addition','substitution reaction','neutralisation','polymerisation'], answer:1, explain:'Cl replaces H — free-radical substitution.'},
{q:'Aromatic compounds are characterised by', options:['bad smell','the benzene ring','triple bonds','ionic bonds'], answer:1, explain:'The delocalised benzene ring defines aromatics.'}]},
{id:'bal-c10-che-ch5', title:'Biochemistry', urdu:'بائیو کیمسٹری', comingSoon:false, lessons:[
{id:'bal-c10-che-ch5-l1', title:'Carbohydrates', html:'<h3>Carbohydrates in Detail</h3><ul><li><strong>Monosaccharides:</strong> glucose, fructose — instant energy.</li><li><strong>Oligosaccharides:</strong> sucrose, lactose, maltose.</li><li><strong>Polysaccharides:</strong> starch, glycogen, cellulose.</li></ul><p>Excess glucose is stored as <strong>glycogen</strong> in liver and muscles.</p>'},
{id:'bal-c10-che-ch5-l2', title:'Proteins and Lipids', html:'<h3>Proteins</h3><p>Chains of <strong>amino acids</strong> — structural (muscle, hair), functional (enzymes, haemoglobin, insulin).</p><h3>Lipids</h3><p><strong>Fatty acids + glycerol</strong>; saturated vs unsaturated. Excess intake links to heart disease; essential for membranes and vitamins.</p>'},
{id:'bal-c10-che-ch5-l3', title:'Nucleic Acids and Vitamins', html:'<h3>Nucleic Acids</h3><p><strong>DNA</strong> (deoxyribose, double helix) stores genes; <strong>RNA</strong> (ribose, single strand) builds proteins.</p><h3>Vitamins</h3><p>Fat-soluble: <strong>A</strong> (vision), <strong>D</strong> (bones), <strong>E</strong>, <strong>K</strong> (clotting). Water-soluble: <strong>B-complex</strong>, <strong>C</strong> (immunity, anti-scurvy).</p>'}],
quiz:[
{q:'Glycogen is stored in', options:['plants','liver and muscles','bones','blood'], answer:1, explain:'Animals store glucose as glycogen in liver and muscle.'},
{q:'Lactose is a', options:['monosaccharide','disaccharide','polysaccharide','lipid'], answer:1, explain:'Milk sugar = glucose + galactose.'},
{q:'Haemoglobin is a protein that', options:['digests food','carries oxygen','builds bone','fights germs'], answer:1, explain:'Haemoglobin in red blood cells transports O₂.'},
{q:'Saturated fats are usually', options:['liquid oils','solid at room temperature','gases','water-soluble'], answer:1, explain:'Saturated fatty acids pack tightly — solid (ghee, butter).'},
{q:'DNA contains the sugar', options:['ribose','deoxyribose','glucose','fructose'], answer:1, explain:'Deoxyribose in DNA; ribose in RNA.'},
{q:'RNA is usually', options:['double helix','single stranded','triple helix','circular only'], answer:1, explain:'RNA is typically a single strand.'},
{q:'Vitamin A deficiency causes', options:['scurvy','night blindness','rickets','bleeding'], answer:1, explain:'Vitamin A maintains vision; lack causes night blindness.'},
{q:'Vitamin K is needed for', options:['vision','blood clotting','bones','immunity'], answer:1, explain:'Vitamin K helps clotting factors work.'},
{q:'B-complex vitamins are', options:['fat-soluble','water-soluble','not vitamins','minerals'], answer:1, explain:'B vitamins and C dissolve in water.'},
{q:'Scurvy is prevented by', options:['vitamin D','vitamin C','vitamin A','iron'], answer:1, explain:'Vitamin C (citrus) prevents scurvy.'}]},
{id:'bal-c10-che-ch6', title:'Environmental Chemistry-I: Atmosphere', urdu:'ماحولیاتی کیمسٹری-I: فضا', comingSoon:false, lessons:[
{id:'bal-c10-che-ch6-l1', title:'Composition and Layers of the Atmosphere', html:'<h3>Atmosphere</h3><p>Composition: N₂ 78%, O₂ 21%, Ar ~1%, CO₂ 0.04%, water vapour.</p><p><strong>Layers:</strong> <strong>troposphere</strong> (weather, ~12 km), <strong>stratosphere</strong> (ozone layer), <strong>mesosphere</strong>, <strong>thermosphere</strong>.</p>'},
{id:'bal-c10-che-ch6-l2', title:'Pollution and Pollutants', html:'<h3>Air Pollution</h3><p><strong>Pollutants:</strong> CO, SO₂, NOₓ, particulates, lead, CFCs, VOCs. Sources: vehicles, industry, burning fossil fuels, brick kilns.</p><p><strong>Smog</strong> (smoke + fog) in cities causes breathing problems — a serious issue in Lahore and other cities each winter.</p>'},
{id:'bal-c10-che-ch6-l3', title:'Acid Rain and Ozone Depletion', html:'<h3>Acid Rain</h3><p>SO₂/NOₓ + water → sulphuric/nitric acids (pH &lt; 5.6). Damages the Badshahi Mosque’s marble, crops and fish.</p><h3>Ozone Depletion</h3><p><strong>CFCs</strong> release chlorine that destroys ozone — the <strong>ozone hole</strong> over Antarctica. The <strong>Montreal Protocol</strong> phases out CFCs.</p>'}],
quiz:[
{q:'The lowest layer of the atmosphere is the', options:['stratosphere','troposphere','mesosphere','thermosphere'], answer:1, explain:'Weather happens in the troposphere.'},
{q:'The ozone layer is in the', options:['troposphere','stratosphere','mesosphere','thermosphere'], answer:1, explain:'Ozone concentrates in the stratosphere.'},
{q:'Smog is', options:['pure fog','smoke + fog with pollutants','clean air','rain'], answer:1, explain:'Smog mixes smoke, fog and chemical pollutants.'},
{q:'Acid rain has pH', options:['7','above 7','below 5.6','exactly 7'], answer:2, explain:'Below 5.6 counts as acid rain.'},
{q:'The ozone hole is largest over', options:['the equator','Antarctica','Asia','Africa'], answer:1, explain:'Severe depletion occurs over Antarctica each spring.'},
{q:'The Montreal Protocol controls', options:['CO₂','CFCs','noise','water use'], answer:1, explain:'It phases out ozone-depleting CFCs.'},
{q:'Argon is about what share of air?', options:['78%','21%','1%','0.04%'], answer:2, explain:'Argon ≈ 0.9% — roughly 1%.'},
{q:'Brick kilns contribute to air pollution mainly through', options:['oxygen','particulates and smoke','nitrogen','water vapour'], answer:1, explain:'Kilns release smoke, dust and gases.'},
{q:'CFCs were commonly used in', options:['old refrigerators and sprays','cars’ fuel','cooking','batteries'], answer:0, explain:'Refrigerants and aerosol propellants contained CFCs.'},
{q:'Weather phenomena occur in the', options:['stratosphere','troposphere','thermosphere','exosphere'], answer:1, explain:'Clouds, rain and storms are tropospheric.'}]},
{id:'bal-c10-che-ch7', title:'Environmental Chemistry-II: Water', urdu:'ماحولیاتی کیمسٹری-II: پانی', comingSoon:false, lessons:[
{id:'bal-c10-che-ch7-l1', title:'Water as a Solvent', html:'<h3>Universal Solvent</h3><p>Water’s <strong>polarity</strong> makes it an excellent solvent — the “universal solvent”. It dissolves salts, sugars and gases (O₂ for fish).</p><p>Water covers ~71% of Earth, but most is salty; fresh water is scarce.</p>'},
{id:'bal-c10-che-ch7-l2', title:'Hard and Soft Water', html:'<h3>Water Hardness</h3><p><strong>Hard water</strong> contains Ca²⁺/Mg²⁺ salts — wastes soap (forms scum), furs kettles with scale.</p><ul><li><strong>Temporary hardness</strong> (hydrogen carbonates) — removed by <strong>boiling</strong>.</li><li><strong>Permanent hardness</strong> (sulphates/chlorides) — removed by <strong>washing soda</strong> or ion exchange.</li></ul>'},
{id:'bal-c10-che-ch7-l3', title:'Water Pollution', html:'<h3>Pollution and Treatment</h3><p><strong>Sources:</strong> sewage, industrial waste, fertiliser runoff, oil spills. Causes <strong>waterborne diseases</strong> (cholera, typhoid, hepatitis).</p><p><strong>Treatment:</strong> filtration, chlorination, boiling. <strong>Conservation:</strong> fix leaks, drip irrigation, rainwater harvesting.</p>'}],
quiz:[
{q:'Water is called the universal solvent because', options:['it dissolves everything','its polarity dissolves many substances','it is abundant','it is tasteless'], answer:1, explain:'Polarity lets water dissolve ionic and polar substances.'},
{q:'Hard water contains dissolved', options:['sodium salts','calcium and magnesium salts','sugar','oxygen'], answer:1, explain:'Ca²⁺/Mg²⁺ cause hardness.'},
{q:'Temporary hardness is removed by', options:['filtration','boiling','cooling','adding salt'], answer:1, explain:'Boiling precipitates calcium hydrogen carbonate as scale.'},
{q:'Permanent hardness is removed by', options:['boiling','washing soda','freezing','stirring'], answer:1, explain:'Sodium carbonate precipitates Ca²⁺/Mg²⁺ as carbonates.'},
{q:'Hard water wastes soap because it forms', options:['lather','scum','bubbles','foam'], answer:1, explain:'Ca/Mg stearate scum instead of lather.'},
{q:'Which disease is waterborne?', options:['malaria','cholera','flu','measles'], answer:1, explain:'Cholera spreads through contaminated water.'},
{q:'Chlorination of water', options:['adds taste','kills germs','adds minerals','cools water'], answer:1, explain:'Chlorine disinfects drinking water.'},
{q:'Fertiliser runoff into lakes causes', options:['cleaner water','algal blooms and oxygen loss','more fish','clear water'], answer:1, explain:'Nutrient overload eutrophies water bodies.'},
{q:'About what share of Earth is covered by water?', options:['50%','71%','90%','30%'], answer:1, explain:'Oceans cover ~71% of Earth’s surface.'},
{q:'Drip irrigation helps', options:['flood fields','conserve water','add fertiliser','drain soil'], answer:1, explain:'Drip delivers water directly to roots with minimal waste.'}]},
{id:'bal-c10-che-ch8', title:'The Industrial Chemistry', urdu:'صنعتی کیمسٹری', comingSoon:false, lessons:[
{id:'bal-c10-che-ch8-l1', title:'Basic Metallurgical Operations', html:'<h3>Extracting Metals</h3><p><strong>Metallurgy</strong> steps: <strong>crushing/grinding</strong> ore → <strong>concentration</strong> (froth flotation, magnetic separation) → <strong>roasting/calcination</strong> → <strong>reduction</strong> (smelting with coke) → <strong>refining</strong> (electrolysis).</p><p>Iron is extracted in the <strong>blast furnace</strong> from haematite.</p>'},
{id:'bal-c10-che-ch8-l2', title:'The Solvay Process and Urea', html:'<h3>Solvay Process</h3><p>Makes <strong>sodium carbonate</strong> (soda ash) from brine (NaCl), ammonia and limestone: used in glass, soap and paper.</p><h3>Urea</h3><p><strong>Urea</strong> (NH₂CONH₂, 46% nitrogen) is Pakistan’s main nitrogen fertiliser, made from ammonia and CO₂ — vital for wheat and cotton yields.</p>'},
{id:'bal-c10-che-ch8-l3', title:'Petroleum Industry', html:'<h3>Petroleum</h3><p>Crude oil is separated by <strong>fractional distillation</strong> into refinery gas, petrol, kerosene, diesel, lubricants, bitumen.</p><p><strong>Petrochemicals</strong> from these make plastics, synthetic fibres, detergents and medicines — a huge industry for Pakistan’s economy.</p>'}],
quiz:[
{q:'The first step in metallurgy is', options:['refining','crushing and grinding the ore','smelting','electrolysis'], answer:1, explain:'Ore is crushed to liberate mineral particles.'},
{q:'Froth flotation is used for', options:['melting','concentration of sulphide ores','cooling','drying'], answer:1, explain:'It separates sulphide ore particles using froth.'},
{q:'Iron is extracted in the', options:['reverberatory furnace','blast furnace','open hearth','muffle furnace'], answer:1, explain:'Haematite is smelted with coke in the blast furnace.'},
{q:'The Solvay process manufactures', options:['urea','sodium carbonate','sulphuric acid','ammonia'], answer:1, explain:'Solvay makes soda ash (Na₂CO₃).'},
{q:'Raw materials for the Solvay process are', options:['iron and coal','brine, ammonia and limestone','oil and gas','sand and clay'], answer:1, explain:'NaCl brine + NH₃ + CaCO₃ → Na₂CO₃.'},
{q:'Urea contains about what percentage of nitrogen?', options:['20%','35%','46%','60%'], answer:2, explain:'Urea is 46% nitrogen — a rich fertiliser.'},
{q:'Urea is made from', options:['nitric acid','ammonia and carbon dioxide','urea ore','air directly'], answer:1, explain:'NH₃ + CO₂ react under pressure to form urea.'},
{q:'Fractional distillation of crude oil gives', options:['only petrol','petrol, diesel, kerosene and more','pure carbon','metals'], answer:1, explain:'Fractions separate by boiling point.'},
{q:'Petrochemicals are used to make', options:['steel','plastics and synthetic fibres','glass','cement'], answer:1, explain:'Oil/gas derivatives feed the polymer industry.'},
{q:'Refining of copper uses', options:['filtration','electrolysis','distillation','sublimation'], answer:1, explain:'Electrolytic refining gives 99.9% pure copper.'}]}
]});
