window.__saMergeCourse({id:'bal-class10-biology', board:'balochistan', title:'Biology', urdu:'حیاتیات', class:'Class 10', icon:'🧬', desc:'Balochistan Board Class 10 Biology — full syllabus with lessons and quizzes.', chapters:[
{id:'bal-c10-bio-ch1', title:'Gaseous Exchange', urdu:'گیسوں کا تبادلہ', comingSoon:false, lessons:[
{id:'bal-c10-bio-ch1-l1', title:'Gaseous Exchange in Plants', html:'<h3>Plants</h3><p>Leaves exchange gases through <strong>stomata</strong> (tiny pores); CO₂ enters for photosynthesis, O₂ and water vapour leave. Roots and stems exchange through <strong>lenticels</strong> and root hairs by <strong>diffusion</strong>.</p>'},
{id:'bal-c10-bio-ch1-l2', title:'Gaseous Exchange in Animals', html:'<h3>Animals</h3><p><strong>Aquatic animals</strong> (fish) use <strong>gills</strong>; <strong>terrestrial animals</strong> use lungs, skin (frog) or tracheae (insects). All rely on moist, thin surfaces with a rich blood supply.</p>'},
{id:'bal-c10-bio-ch1-l3', title:'Human Respiratory System', html:'<h3>Breathing in Humans</h3><p>Air path: nose → pharynx → larynx → <strong>trachea</strong> → bronchi → bronchioles → <strong>alveoli</strong> (gas exchange). <strong>Inhalation:</strong> diaphragm contracts, ribs rise; <strong>exhalation:</strong> they relax. <strong>Smoking</strong> damages alveoli (emphysema) and causes lung cancer.</p>'}],
quiz:[
{q:'In leaves, gaseous exchange occurs through', options:['lenticels','stomata','root hairs','xylem'], answer:1, explain:'Stomata are the leaf pores for gas exchange.'},
{q:'Fish exchange gases through', options:['lungs','gills','skin','tracheae'], answer:1, explain:'Gills extract dissolved oxygen from water.'},
{q:'In humans, gas exchange occurs in the', options:['trachea','bronchi','alveoli','nose'], answer:2, explain:'Alveoli are the tiny air sacs where O₂/CO₂ swap with blood.'},
{q:'During inhalation', options:['diaphragm relaxes','diaphragm contracts and flattens','ribs lower','lungs shrink'], answer:1, explain:'Contracting diaphragm and rising ribs expand the chest.'},
{q:'Emphysema is caused mainly by', options:['exercise','smoking','cold air','dust only'], answer:1, explain:'Smoking destroys alveolar walls — emphysema.'},
{q:'Lenticels are found in', options:['leaves','woody stems','flowers','seeds'], answer:1, explain:'Lenticels let woody stems exchange gases.'},
{q:'The correct air path is', options:['nose → trachea → alveoli','nose → pharynx → larynx → trachea → bronchi → alveoli','mouth → stomach → lungs','nose → bronchi → trachea'], answer:1, explain:'Air follows the respiratory tract in order.'},
{q:'Insects breathe through', options:['lungs','tracheae','gills','skin'], answer:1, explain:'Tracheal tubes carry air directly to insect tissues.'},
{q:'Oxygen is carried in blood mainly by', options:['plasma','haemoglobin in red cells','white cells','platelets'], answer:1, explain:'Haemoglobin binds oxygen in red blood cells.'},
{q:'Exhaled air contains more', options:['oxygen','carbon dioxide','nitrogen','helium'], answer:1, explain:'Exhaled air is rich in CO₂ from respiration.'}]},
{id:'bal-c10-bio-ch2', title:'Homeostasis', urdu:'ہومیوسٹیسس', comingSoon:false, lessons:[
{id:'bal-c10-bio-ch2-l1', title:'Homeostasis in Plants', html:'<h3>Plants</h3><p>Plants keep water balance by <strong>stomatal control</strong> (guard cells close stomata in drought), <strong>osmosis</strong> in roots, and shedding leaves. Succulents like cacti store water.</p>'},
{id:'bal-c10-bio-ch2-l2', title:'Homeostasis in Humans', html:'<h3>Human Regulation</h3><ul><li><strong>Temperature:</strong> sweating cools, shivering warms; skin blood vessels dilate/constrict.</li><li><strong>Water/salts:</strong> kidneys adjust urine concentration.</li><li><strong>Blood sugar:</strong> insulin lowers, glucagon raises glucose.</li></ul>'},
{id:'bal-c10-bio-ch2-l3', title:'Urinary System and Kidney Disorders', html:'<h3>Kidneys</h3><p>The <strong>urinary system</strong>: kidneys → ureters → bladder → urethra. Kidneys filter blood, reabsorb useful substances and excrete <strong>urine</strong> (urea, salts, water).</p><p><strong>Disorders:</strong> kidney stones, kidney failure (treated by <strong>dialysis</strong> or transplant). <strong>Diabetes</strong> results from insulin shortage — managed by diet, exercise and medication.</p>'}],
quiz:[
{q:'Homeostasis is', options:['rapid growth','keeping internal conditions stable','cell division','digestion'], answer:1, explain:'Stable internal environment despite external change.'},
{q:'Guard cells control', options:['photosynthesis rate','opening and closing of stomata','root growth','flowering'], answer:1, explain:'Guard cells regulate stomatal opening for water balance.'},
{q:'Shivering helps the body', options:['cool down','generate heat','lose water','sleep'], answer:1, explain:'Muscle activity in shivering produces heat.'},
{q:'Insulin', options:['raises blood sugar','lowers blood sugar','digests protein','carries oxygen'], answer:1, explain:'Insulin moves glucose into cells, lowering blood sugar.'},
{q:'Urine is carried from kidneys to bladder by the', options:['urethra','ureters','nephrons','aorta'], answer:1, explain:'Ureters connect kidneys to the bladder.'},
{q:'The functional unit of the kidney is the', options:['alveolus','nephron','neuron','villus'], answer:1, explain:'Nephrons filter blood and form urine.'},
{q:'Kidney failure patients may need', options:['surgery only','dialysis','antibiotics','rest only'], answer:1, explain:'Dialysis artificially filters the blood.'},
{q:'Diabetes mellitus results from', options:['excess insulin','insulin shortage or resistance','kidney stones','high salt'], answer:1, explain:'Without effective insulin, blood sugar stays high.'},
{q:'Sweating cools the body by', options:['losing salt','evaporation of water','washing skin','reducing blood'], answer:1, explain:'Evaporation carries heat away from skin.'},
{q:'Cacti survive drought by', options:['deep breathing','storing water in fleshy stems','shedding roots','fast growth'], answer:1, explain:'Succulent stems store water for dry periods.'}]},
{id:'bal-c10-bio-ch3', title:'Coordination and Control', urdu:'ہم آہنگی اور کنٹرول', comingSoon:false, lessons:[
{id:'bal-c10-bio-ch3-l1', title:'Coordination in Plants', html:'<h3>Plant Responses</h3><p>Plants respond via <strong>hormones</strong>: <strong>auxins</strong> (cell elongation, phototropism), <strong>gibberellins</strong> (stem growth, seed germination), <strong>cytokinins</strong> (cell division), <strong>abscisic acid</strong> (dormancy, stomatal closing).</p><p><strong>Tropisms:</strong> phototropism (light), geotropism (gravity), thigmotropism (touch).</p>'},
{id:'bal-c10-bio-ch3-l2', title:'Human Nervous System', html:'<h3>Nervous Coordination</h3><p><strong>Neurons</strong> carry impulses: dendrites → cell body → axon. <strong>CNS</strong> = brain + spinal cord; <strong>peripheral nerves</strong> connect the body.</p><p><strong>Reflex action</strong> (withdrawing from heat) is a fast spinal response. The <strong>synapse</strong> passes signals between neurons.</p>'},
{id:'bal-c10-bio-ch3-l3', title:'Hormones and Glands in Humans', html:'<h3>Endocrine System</h3><ul><li><strong>Pituitary:</strong> growth hormone (master gland).</li><li><strong>Thyroid:</strong> thyroxine (metabolism; iodine needed).</li><li><strong>Pancreas:</strong> insulin and glucagon.</li><li><strong>Adrenal:</strong> adrenaline (emergency response).</li></ul><p><strong>Diabetes</strong> and <strong>goitre</strong> (iodine deficiency) are hormonal disorders.</p>'}],
quiz:[
{q:'Auxins promote', options:['dormancy','cell elongation and phototropism','leaf fall','flowering only'], answer:1, explain:'Auxins drive growth toward light.'},
{q:'Phototropism is growth in response to', options:['gravity','light','touch','water'], answer:1, explain:'Photo- = light; shoots bend toward it.'},
{q:'The structural unit of the nervous system is the', options:['nephron','neuron','alveolus','osteon'], answer:1, explain:'Neurons transmit nerve impulses.'},
{q:'A reflex action is controlled by the', options:['brain','spinal cord','heart','muscles alone'], answer:1, explain:'Reflexes are fast spinal responses bypassing the brain.'},
{q:'The master gland is the', options:['thyroid','pituitary','adrenal','pancreas'], answer:1, explain:'Pituitary hormones control other glands.'},
{q:'Adrenaline is released during', options:['sleep','emergency (fight or flight)','digestion','rest'], answer:1, explain:'Adrenal glands release adrenaline under stress.'},
{q:'Goitre is caused by deficiency of', options:['iron','iodine','calcium','vitamin C'], answer:1, explain:'Iodine is needed for thyroxine; lack enlarges the thyroid.'},
{q:'Insulin is secreted by the', options:['liver','pancreas','kidney','thyroid'], answer:1, explain:'Pancreatic beta cells release insulin.'},
{q:'Gibberellins promote', options:['dormancy','stem elongation and seed germination','root death','leaf fall'], answer:1, explain:'Gibberellins stimulate growth and break dormancy.'},
{q:'Signals pass between neurons at the', options:['node','synapse','axon','dendrite'], answer:1, explain:'The synapse is the junction between neurons.'}]},
{id:'bal-c10-bio-ch4', title:'Support and Movement', urdu:'سہارا اور حرکت', comingSoon:false, lessons:[
{id:'bal-c10-bio-ch4-l1', title:'The Human Skeleton', html:'<h3>Skeleton</h3><p>206 bones: <strong>axial</strong> (skull, vertebral column, ribs) and <strong>appendicular</strong> (limbs, girdles). Functions: support, protection (skull, ribcage), movement, blood-cell formation in <strong>bone marrow</strong>, mineral storage.</p><p><strong>Cartilage</strong> cushions joints; <strong>ligaments</strong> join bone to bone, <strong>tendons</strong> join muscle to bone.</p>'},
{id:'bal-c10-bio-ch4-l2', title:'Joints', html:'<h3>Joints</h3><ul><li><strong>Immovable</strong> (skull sutures), <strong>slightly movable</strong> (vertebrae), <strong>freely movable/synovial</strong> — <strong>hinge</strong> (elbow, knee), <strong>ball-and-socket</strong> (shoulder, hip).</li></ul><p>Synovial fluid lubricates movable joints.</p>'},
{id:'bal-c10-bio-ch4-l3', title:'Muscles and Movement', html:'<h3>Muscles</h3><p><strong>Skeletal muscles</strong> (voluntary, striped) work in <strong>antagonistic pairs</strong>: biceps contracts to bend the arm, triceps to straighten it.</p><p><strong>Smooth muscles</strong> (involuntary, gut) and <strong>cardiac muscle</strong> (heart) work automatically.</p>'}],
quiz:[
{q:'An adult human skeleton has', options:['106 bones','206 bones','306 bones','256 bones'], answer:1, explain:'Adults have 206 bones.'},
{q:'Blood cells are formed in the', options:['liver','bone marrow','spleen','heart'], answer:1, explain:'Red marrow produces blood cells.'},
{q:'Ligaments join', options:['muscle to bone','bone to bone','muscle to muscle','skin to bone'], answer:1, explain:'Ligaments stabilise joints bone-to-bone.'},
{q:'Tendons join', options:['bone to bone','muscle to bone','bone to skin','cartilage to nerve'], answer:1, explain:'Tendons anchor muscles to bones.'},
{q:'The elbow joint is a', options:['ball-and-socket','hinge joint','fixed joint','pivot joint'], answer:1, explain:'Hinge joints allow back-and-forth movement.'},
{q:'The shoulder joint is a', options:['hinge','ball-and-socket','gliding','fixed'], answer:1, explain:'Ball-and-socket allows rotation in many directions.'},
{q:'Biceps and triceps are', options:['identical','antagonistic muscles','smooth muscles','cardiac muscles'], answer:1, explain:'They oppose each other to move the arm.'},
{q:'Cardiac muscle is found in the', options:['arms','heart','gut','legs'], answer:1, explain:'The heart wall is cardiac muscle.'},
{q:'Skull bones are joined by', options:['hinge joints','immovable joints','ball-and-socket','cartilage'], answer:1, explain:'Sutures fuse skull bones rigidly.'},
{q:'Ribs protect the', options:['brain','heart and lungs','kidneys','liver only'], answer:1, explain:'The ribcage shields heart and lungs.'}]},
{id:'bal-c10-bio-ch5', title:'Reproduction', urdu:'تولید', comingSoon:false, lessons:[
{id:'bal-c10-bio-ch5-l1', title:'Asexual Reproduction', html:'<h3>Asexual Reproduction</h3><p>One parent, no gametes — offspring are <strong>clones</strong>.</p><ul><li><strong>Binary fission</strong> (Amoeba), <strong>budding</strong> (Hydra, yeast).</li><li><strong>Spore formation</strong> (fungi, ferns).</li><li><strong>Vegetative propagation</strong> — runners, tubers (potato), cuttings (rose), grafting.</li></ul>'},
{id:'bal-c10-bio-ch5-l2', title:'Sexual Reproduction in Plants', html:'<h3>Plant Reproduction</h3><p>Flower parts: sepals, petals, <strong>stamens</strong> (anther + filament — male), <strong>carpel</strong> (stigma, style, ovary — female).</p><p><strong>Pollination</strong> (pollen → stigma) → <strong>fertilisation</strong> in the ovule → <strong>seed</strong> and <strong>fruit</strong>. Agents: wind, insects, water.</p>'},
{id:'bal-c10-bio-ch5-l3', title:'Sexual Reproduction in Animals and Humans', html:'<h3>Animals</h3><p><strong>External fertilisation</strong> (fish, frogs — in water) vs <strong>internal fertilisation</strong> (mammals, birds). <strong>Viviparous</strong> animals give birth (humans); <strong>oviparous</strong> lay eggs (hens).</p><p><strong>Human:</strong> testes make sperm, ovaries make eggs; fertilisation in the oviduct; embryo develops in the <strong>uterus</strong>; birth after ~9 months.</p>'}],
quiz:[
{q:'Binary fission occurs in', options:['Hydra','Amoeba','yeast','rose'], answer:1, explain:'Amoeba splits into two equal halves.'},
{q:'Budding is seen in', options:['Amoeba','Hydra','mushroom','fern'], answer:1, explain:'Hydra grows a bud that detaches.'},
{q:'Potato tubers are an example of', options:['sexual reproduction','vegetative propagation','spore formation','budding'], answer:1, explain:'Tubers grow new plants asexually.'},
{q:'The male part of a flower is the', options:['carpel','stamen','sepal','ovary'], answer:1, explain:'Stamens (anther + filament) produce pollen.'},
{q:'Fertilisation in flowering plants occurs in the', options:['stigma','ovule','petal','style'], answer:1, explain:'The pollen tube reaches the ovule for fertilisation.'},
{q:'Agents of pollination include', options:['only wind','wind, insects and water','only bees','soil'], answer:1, explain:'Pollen travels by wind, insects, water and animals.'},
{q:'Frogs show', options:['internal fertilisation','external fertilisation','no fertilisation','budding'], answer:1, explain:'Frogs release eggs and sperm into water.'},
{q:'Viviparous animals', options:['lay eggs','give birth to live young','reproduce by spores','split in two'], answer:1, explain:'Viviparous = live birth (mammals).'},
{q:'In humans, fertilisation occurs in the', options:['uterus','oviduct (fallopian tube)','ovary','vagina'], answer:1, explain:'Sperm meets egg in the oviduct.'},
{q:'Asexual reproduction produces offspring that are', options:['varied','genetically identical to the parent','half similar','always weaker'], answer:1, explain:'No gamete fusion — clones of the single parent.'}]},
{id:'bal-c10-bio-ch6', title:'Inheritance', urdu:'وراثت', comingSoon:false, lessons:[
{id:'bal-c10-bio-ch6-l1', title:'Mendel’s Laws', html:'<h3>Mendel</h3><p><strong>Gregor Mendel</strong> (pea plants) discovered:</p><ul><li><strong>Law of segregation:</strong> each trait’s two alleles separate into different gametes.</li><li><strong>Law of independent assortment:</strong> different traits inherit independently.</li></ul><p><strong>Dominant</strong> alleles mask <strong>recessive</strong> ones (Tt looks tall).</p>'},
{id:'bal-c10-bio-ch6-l2', title:'Genotype, Phenotype and Monohybrid Cross', html:'<h3>Crosses</h3><p><strong>Genotype</strong> = gene combination (TT, Tt, tt); <strong>phenotype</strong> = observable trait (tall/dwarf).</p><p><strong>Monohybrid cross</strong> Tt × Tt → <strong>3:1</strong> phenotypic ratio (3 tall : 1 dwarf); genotypic ratio 1:2:1.</p>'},
{id:'bal-c10-bio-ch6-l3', title:'Dihybrid Cross, Co-dominance and Sex Determination', html:'<h3>Advanced Inheritance</h3><ul><li><strong>Dihybrid cross</strong> → <strong>9:3:3:1</strong> phenotypic ratio.</li><li><strong>Co-dominance:</strong> both alleles show (AB blood group).</li><li><strong>Sex determination:</strong> XX = female, XY = male — the <strong>father’s sperm</strong> decides the child’s sex.</li></ul><p><strong>Variations</strong> arise from mutation and recombination.</p>'}],
quiz:[
{q:'Mendel worked on', options:['fruit flies','pea plants','mice','maize'], answer:1, explain:'Pea plants revealed the laws of inheritance.'},
{q:'The law of segregation states', options:['traits blend','allele pairs separate into gametes','genes never separate','only dominant traits pass'], answer:1, explain:'Each gamete gets one allele of each pair.'},
{q:'In Tt, the phenotype is tall because T is', options:['recessive','dominant','absent','mutated'], answer:1, explain:'Dominant alleles mask recessive ones.'},
{q:'A monohybrid cross Tt × Tt gives phenotypic ratio', options:['1:1','3:1','9:3:3:1','1:2:1'], answer:1, explain:'3 dominant phenotype : 1 recessive.'},
{q:'The genotypic ratio of Tt × Tt is', options:['3:1','1:2:1','9:3:3:1','1:1'], answer:1, explain:'1 TT : 2 Tt : 1 tt.'},
{q:'A dihybrid cross gives phenotypic ratio', options:['3:1','9:3:3:1','1:1','1:2:1'], answer:1, explain:'9:3:3:1 for two independently assorting traits.'},
{q:'AB blood group shows', options:['dominance','co-dominance','recessiveness','mutation'], answer:1, explain:'Both A and B alleles express together.'},
{q:'Human females have sex chromosomes', options:['XY','XX','XO','YY'], answer:1, explain:'XX = female, XY = male.'},
{q:'The child’s sex is determined by', options:['the mother’s egg','the father’s sperm','diet','temperature'], answer:1, explain:'Sperm carries X or Y; eggs carry only X.'},
{q:'Genotype refers to', options:['observable traits','the gene combination','physical height','chromosome number'], answer:1, explain:'Genotype = genetic makeup; phenotype = appearance.'}]},
{id:'bal-c10-bio-ch7', title:'Man and His Environment', urdu:'انسان اور اس کا ماحول', comingSoon:false, lessons:[
{id:'bal-c10-bio-ch7-l1', title:'Ecology and Ecosystem', html:'<h3>Ecology</h3><p><strong>Ecology</strong> studies organisms and their environment. An <strong>ecosystem</strong> = biotic community + abiotic surroundings (pond, forest).</p><p><strong>Biotic</strong> factors: living (plants, animals, microbes). <strong>Abiotic</strong>: light, temperature, water, soil, air.</p>'},
{id:'bal-c10-bio-ch7-l2', title:'Food Chains, Food Webs and Energy Flow', html:'<h3>Feeding Relationships</h3><p><strong>Producers</strong> (plants) → <strong>primary consumers</strong> (herbivores) → <strong>secondary consumers</strong> (carnivores) → <strong>decomposers</strong> (bacteria, fungi).</p><p>Interlinked chains form a <strong>food web</strong>. Energy flows one way; only ~10% passes to each next <strong>trophic level</strong>.</p>'},
{id:'bal-c10-bio-ch7-l3', title:'Human Impact and Conservation', html:'<h3>Humans and Environment</h3><p>Human activities — <strong>deforestation, pollution, overpopulation, fossil-fuel burning</strong> — cause global warming, habitat loss and extinction.</p><p><strong>Conservation:</strong> national parks (Hingol, Kirthar), wildlife sanctuaries, the 3Rs (reduce, reuse, recycle), tree plantation drives.</p>'}],
quiz:[
{q:'Ecology is the study of', options:['cells','organisms and their environment','rocks','stars'], answer:1, explain:'Ecology examines organism–environment interactions.'},
{q:'An ecosystem includes', options:['only animals','biotic community + abiotic surroundings','only plants','only water'], answer:1, explain:'Both living and non-living components.'},
{q:'Which is an abiotic factor?', options:['bacteria','temperature','trees','fish'], answer:1, explain:'Abiotic = non-living (light, temperature, water, soil).'},
{q:'In a food chain, producers are', options:['herbivores','green plants','carnivores','decomposers'], answer:1, explain:'Plants produce food by photosynthesis.'},
{q:'Decomposers include', options:['lions','bacteria and fungi','grass','rabbits'], answer:1, explain:'They break down dead matter, recycling nutrients.'},
{q:'About how much energy passes to the next trophic level?', options:['50%','10%','90%','100%'], answer:1, explain:'Roughly 10% transfers; the rest is lost as heat.'},
{q:'A food web is', options:['one chain','interconnected food chains','a spider’s web','a pyramid'], answer:1, explain:'Real ecosystems have many linked feeding paths.'},
{q:'Hingol is a', options:['city','national park','river','desert'], answer:1, explain:'Hingol National Park in Balochistan protects wildlife.'},
{q:'A major cause of global warming is', options:['planting trees','burning fossil fuels','recycling','solar energy'], answer:1, explain:'Fossil fuels release greenhouse gases.'},
{q:'The 3Rs stand for', options:['read, write, recite','reduce, reuse, recycle','run, rest, relax','rock, rain, river'], answer:1, explain:'The 3Rs cut waste and conserve resources.'}]},
{id:'bal-c10-bio-ch8', title:'Biotechnology', urdu:'بائیو ٹیکنالوجی', comingSoon:false, lessons:[
{id:'bal-c10-bio-ch8-l1', title:'What is Biotechnology?', html:'<h3>Biotechnology</h3><p><strong>Biotechnology</strong> uses living organisms to make useful products — ancient (bread, yoghurt) and modern (insulin, vaccines).</p><p>Branches: <strong>red</strong> (medical), <strong>green</strong> (agricultural), <strong>white</strong> (industrial).</p>'},
{id:'bal-c10-bio-ch8-l2', title:'Genetic Engineering', html:'<h3>Genetic Engineering</h3><p>Moving genes between organisms using <strong>restriction enzymes</strong> (cut DNA) and <strong>vectors</strong> (plasmids carry genes into bacteria).</p><p><strong>Recombinant DNA:</strong> human insulin gene in bacteria → cheap <strong>insulin</strong> for diabetics. <strong>Bt crops</strong> (cotton) resist pests.</p>'},
{id:'bal-c10-bio-ch8-l3', title:'Applications and Concerns', html:'<h3>Uses and Ethics</h3><ul><li><strong>Fermentation:</strong> yeast makes bread, ethanol; bacteria make yoghurt, cheese.</li><li><strong>Medicine:</strong> vaccines, antibiotics, gene therapy.</li><li><strong>Environment:</strong> microbes clean oil spills (bioremediation).</li></ul><p><strong>Concerns:</strong> safety of GM foods, misuse of genetic data, effects on biodiversity — regulated by <strong>bioethics</strong>.</p>'}],
quiz:[
{q:'Biotechnology is', options:['study of rocks','use of living organisms to make useful products','computer science','mining'], answer:1, explain:'Bio = life; technology = application.'},
{q:'An ancient biotechnology product is', options:['plastic','bread','steel','glass'], answer:1, explain:'Yeast fermentation for bread is millennia old.'},
{q:'Restriction enzymes', options:['join proteins','cut DNA at specific sites','kill bacteria','copy RNA'], answer:1, explain:'They are molecular scissors for DNA.'},
{q:'In genetic engineering, plasmids act as', options:['scissors','vectors carrying genes','glue','fuel'], answer:1, explain:'Plasmids deliver foreign genes into bacteria.'},
{q:'Human insulin is now made using', options:['pigs only','genetically engineered bacteria','plants','chemical synthesis'], answer:1, explain:'Recombinant bacteria produce human insulin.'},
{q:'Bt cotton is', options:['a pesticide spray','genetically modified to resist pests','dyed cotton','wild cotton'], answer:1, explain:'Bt genes make the plant resist bollworms.'},
{q:'Fermentation by yeast produces', options:['oxygen','ethanol and CO₂','nitrogen','methane'], answer:1, explain:'Yeast ferments sugar into alcohol and carbon dioxide.'},
{q:'Bioremediation uses microbes to', options:['make plastic','clean pollution like oil spills','cause disease','eat crops'], answer:1, explain:'Microbes break down pollutants.'},
{q:'Green biotechnology deals with', options:['medicine','agriculture','industry','mining'], answer:1, explain:'Green = agricultural applications.'},
{q:'Bioethics addresses', options:['only profits','moral issues of biotechnology','lab safety only','patents only'], answer:1, explain:'Bioethics weighs benefits against risks and rights.'}]},
{id:'bal-c10-bio-ch9', title:'Pharmacology', urdu:'فارماکولوجی', comingSoon:false, lessons:[
{id:'bal-c10-bio-ch9-l1', title:'Drugs and their Sources', html:'<h3>Pharmacology</h3><p><strong>Pharmacology</strong> studies drugs — their sources, actions and uses. <strong>Sources:</strong> plants (morphine from poppy, quinine from cinchona), animals (insulin), minerals (iron tonics), synthetic (aspirin, paracetamol).</p>'},
{id:'bal-c10-bio-ch9-l2', title:'Types of Drugs', html:'<h3>Drug Types</h3><ul><li><strong>Antibiotics</strong> (penicillin) — kill bacteria.</li><li><strong>Analgesics</strong> (paracetamol) — relieve pain.</li><li><strong>Vaccines</strong> — prevent disease by building immunity.</li><li><strong>Antiseptics</strong> — kill germs on skin.</li></ul><p><strong>Dosage</strong> matters — overdose can poison; always follow a doctor’s prescription.</p>'},
{id:'bal-c10-bio-ch9-l3', title:'Drug Abuse and Misuse', html:'<h3>Dangers</h3><p><strong>Drug abuse</strong> (heroin, cocaine, alcohol, tobacco) damages health, families and society. <strong>Addiction</strong> is compulsive use despite harm.</p><p><strong>Prevention:</strong> awareness, strong family bonds, healthy activities, saying no to peer pressure. <strong>Antibiotic misuse</strong> breeds resistant germs — never self-medicate.</p>'}],
quiz:[
{q:'Pharmacology is the study of', options:['plants','drugs — sources, actions and uses','insects','minerals'], answer:1, explain:'Pharmacology covers medicines and their effects.'},
{q:'Quinine comes from', options:['poppy','cinchona bark','willow','fungus'], answer:1, explain:'Cinchona bark yields the antimalarial quinine.'},
{q:'Morphine is obtained from', options:['cinchona','opium poppy','penicillium','willow'], answer:1, explain:'Poppy latex gives morphine, a painkiller.'},
{q:'Penicillin is an', options:['analgesic','antibiotic','vaccine','antiseptic'], answer:1, explain:'Penicillin kills bacteria — the first antibiotic.'},
{q:'Vaccines work by', options:['killing germs directly','building immunity before infection','relieving pain','cleaning wounds'], answer:1, explain:'Vaccines train the immune system in advance.'},
{q:'Paracetamol is an', options:['antibiotic','analgesic','antiseptic','vaccine'], answer:1, explain:'It relieves pain and fever.'},
{q:'Drug addiction means', options:['occasional use','compulsive use despite harm','doctor’s prescription','vitamin use'], answer:1, explain:'Addiction is loss of control over drug use.'},
{q:'Antibiotic misuse leads to', options:['faster cure','drug-resistant germs','no effect','immunity'], answer:1, explain:'Overuse selects resistant bacteria.'},
{q:'Aspirin was originally derived from', options:['poppy','willow bark','cinchona','fungus'], answer:1, explain:'Willow bark salicin led to aspirin.'},
{q:'The best protection against drug abuse is', options:['curiosity','awareness and refusing peer pressure','isolation','money'], answer:1, explain:'Education and strong resolve prevent abuse.'}]}
]});
